function checkQueryGuardrails(rawText) {
    const q = (rawText || "").toLowerCase();
    const unsafeRegex = /\b(make a bomb|how to make bomb|rdx|ied explosive|terrorist attack|how to murder|kill someone|commit suicide|how to die|make poison|hack bank|child abuse)\b|बम कैसे बनाएं|मर्डर कैसे/i;
    if (unsafeRegex.test(q)) {
        return {
            blocked: true,
            reply: "⚠️ **Safety Alert:** I cannot assist with dangerous, violent, or illegal activities. Please ask about studies, health, or safe daily topics."
        };
    }
    const codingRegex = /\b(write a code|write code|html code|javascript code|python code|java code|c\+\+ code|source code|program banao|code likho)\b/i;
    if (codingRegex.test(q)) {
        return {
            blocked: true,
            reply: "🚫 **Coding Disabled:** Programming code generation is currently turned off in Zoreno. Feel free to ask about any study subject, health, or general knowledge!"
        };
    }
    return { blocked: false };
}

function isHealthOrMedicalQuery(rawText) {
    const q = (rawText || "").toLowerCase();
    return /\b(health|doctor|medicine|tablet|symptom|fever|stomach|pain|ache|headache|panic attack|anxiety|depression|vomiting|diarrhea|disease|infection|blood pressure|diabetes|pregnancy|period|reproduction|allergy|bukhar|pet kharab|dard|tabiyat|dawa|bimari|ilaj)\b/i.test(q);
}

// ================= SPAM & SAFETY ALGORITHM =================
let zorenoSpamState = { lastMessages: [], lastSentTimestamps: [] };

function evaluateZorenoSafetyAlgorithm(rawText) {
    const text = (rawText || "").trim();
    if (!text) return { score: 0, action: "allow", reason: "" };
    let score = 0;
    let reasons = [];
    const now = Date.now();

    const recentSameCount = zorenoSpamState.lastMessages.filter(m => m.toLowerCase() === text.toLowerCase()).length;
    if (recentSameCount >= 2) { score += 3; reasons.push("repeated identical messages"); }

    const suspiciousUrlRegex = /(?:bit\.ly|tinyurl\.com|ngrok|free-gift|mod-apk|\.apk\b|\.exe\b|http:\/\/)/i;
    if (suspiciousUrlRegex.test(text)) { score += 4; reasons.push("suspicious or unverified link"); }

    zorenoSpamState.lastSentTimestamps = zorenoSpamState.lastSentTimestamps.filter(t => now - t < 6000);
    if (zorenoSpamState.lastSentTimestamps.length >= 4) { score += 2; reasons.push("sending messages too fast"); }

    zorenoSpamState.lastMessages.push(text);
    if (zorenoSpamState.lastMessages.length > 5) zorenoSpamState.lastMessages.shift();
    zorenoSpamState.lastSentTimestamps.push(now);

    if (score >= 5) return { score, action: "block", reason: reasons.join(" & ") };
    if (score >= 4) return { score, action: "warn", reason: reasons.join(" & ") };
    return { score, action: "allow", reason: "" };
}

function checkPersonalPrivacyBeforeSend(rawText) {
    const txt = (rawText || "").trim();
    if (!txt) return true;
    const sensitiveDigitsRegex = /\b(?:\d{4}[\s-]?\d{4}[\s-]?\d{4}(?:[\s-]?\d{4})?)\b/;
    const otpRegex = /\b(?:otp|cvv|pin|password)\s*(?:is|:|-)?\s*\d{4,6}\b/i;
    if (sensitiveDigitsRegex.test(txt) || otpRegex.test(txt)) {
        return confirm("🛡️ Privacy Alert: Your message appears to contain a private card/ID number or OTP. Are you sure you want to send it?");
    }
    return true;
}

function getSafeAvatar(url) {
    if (!url || typeof url !== "string") return DEFAULT_AVATAR_URL;
    if (url.includes("i.pravatar.cc")) return DEFAULT_AVATAR_URL;
    return url;
}

function escapeHtml(s) {
    return String(s || "").replace(/[&<>"']/g, function(c) {
        return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#039;" }[c];
    });
}

