// Unified Subscription Tier Getter & Setter (Keeps `userTier` and `window.userTier` 100% Identical)
function getEffectiveTier() {
    const lsTier = parseInt(localStorage.getItem("userTier") || "0", 10) || 0;
    const current = Math.max(lsTier, typeof userTier === "number" ? userTier : 0);
    userTier = current;
    window.userTier = current;
    return current;
}

function setEffectiveTier(newTier, expiryMs) {
    const t = parseInt(newTier, 10) || 0;
    const exp = expiryMs !== undefined ? expiryMs : (t > 0 ? Date.now() + SUBSCRIPTION_VALIDITY_MS : 0);
    userTier = t;
    window.userTier = t;
    subExpiresAtMs = exp;
    window.subExpiresAtMs = exp;
    localStorage.setItem("userTier", String(t));
    localStorage.setItem("subExpiresAtMs", String(exp));
}

