function loadExternalScript(src, id) {
    return new Promise((resolve, reject) => {
        let old = document.getElementById(id);
        if (old) {
            if (old.dataset.loaded === "true") return resolve();
            old.addEventListener("load", resolve, { once: true });
            return;
        }
        let s = document.createElement("script");
        s.id = id;
        s.src = src;
        s.onload = () => { s.dataset.loaded = "true"; resolve(); };
        s.onerror = () => reject(Error("Failed to load " + src));
        document.head.appendChild(s);
    });
}

function formatSmartTimeLabel(ms) {
    if (!ms || typeof ms !== "number") return "";
    const d = new Date(ms);
    const now = new Date();
    if (d.toDateString() === now.toDateString()) {
        return d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    }
    const yesterday = new Date(now);
    yesterday.setDate(now.getDate() - 1);
    if (d.toDateString() === yesterday.toDateString()) return "Yesterday";
    return d.toLocaleDateString([], { day: "2-digit", month: "short" });
}

function formatPresenceStatusText(isOnlineFlag, lastActiveAtMs, fallbackLabel) {
    const now = Date.now();
    const isRecentlyActive = lastActiveAtMs && (now - lastActiveAtMs < 120000);
    if (isOnlineFlag && (isRecentlyActive || !lastActiveAtMs)) {
        return { online: true, text: "Online" };
    }
    if (lastActiveAtMs) {
        const d = new Date(lastActiveAtMs);
        const nowDate = new Date();
        const timePart = d.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
        if (d.toDateString() === nowDate.toDateString()) return { online: false, text: `Last seen today at ${timePart}` };
        const yest = new Date(nowDate);
        yest.setDate(nowDate.getDate() - 1);
        if (d.toDateString() === yest.toDateString()) return { online: false, text: `Last seen yesterday at ${timePart}` };
        const datePart = d.toLocaleDateString([], { day: "2-digit", month: "short" });
        return { online: false, text: `Last seen ${datePart}, ${timePart}` };
    }
    return { online: false, text: `Last seen ${fallbackLabel || "recently"}` };
}

function getTodayLocalMidnightKey() {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

// Compact Apple Dynamic-Island Toast Pill
function showCompactGlassToast(iconHtml, titleText, subText = "") {
    let old = document.getElementById("zorenoCompactGlassToast");
    if (old) old.remove();
    const pill = document.createElement("div");
    pill.id = "zorenoCompactGlassToast";
    pill.className = "zoreno-glass-toast-pill";
    pill.innerHTML = `
        <span style="font-size:15px;">${iconHtml}</span>
        <span><strong>${escapeHtml(titleText)}</strong>${subText ? ` • <span style="opacity:0.85; font-weight:500;">${escapeHtml(subText)}</span>` : ""}</span>
    `;
    document.body.appendChild(pill);
    setTimeout(() => {
        if (pill.parentNode) {
            pill.style.opacity = "0";
            pill.style.transition = "opacity 0.25s ease";
            setTimeout(() => pill.remove(), 260);
        }
    }, 2300);
}

// ================= FIREBASE INIT & REALTIME CROSS-DEVICE SYNC =================
async function initFirebase() {
    if (firebaseReadyPromise) return firebaseReadyPromise;
    firebaseReadyPromise = (async () => {
        try {
            if (!window.firebase?.initializeApp)
                await loadExternalScript("https://www.gstatic.com/firebasejs/10.8.0/firebase-app-compat.js", "zfb-app");
            if (!window.firebase?.auth)
                await loadExternalScript("https://www.gstatic.com/firebasejs/10.8.0/firebase-auth-compat.js", "zfb-auth");
            if (!window.firebase?.firestore)
                await loadExternalScript("https://www.gstatic.com/firebasejs/10.8.0/firebase-firestore-compat.js", "zfb-firestore");

            if (!firebase.apps.length) firebase.initializeApp(firebaseConfig);
            db = firebase.firestore();
            auth = firebase.auth();

            // Load live Gemini API key from Firebase appConfig
            db.collection("appConfig").doc("aiSettings").onSnapshot(doc => {
                if (doc.exists && doc.data()?.geminiApiKey) {
                    GEMINI_API_KEY = String(doc.data().geminiApiKey).trim();
                    localStorage.setItem("zorenoCloudApiKey", GEMINI_API_KEY);
                }
            }, () => {});

            auth.onAuthStateChanged(async u => {
                const authScreen = document.getElementById("authScreen");
                const splashScreen = document.getElementById("splashScreen");
                const bottomNav = document.getElementById("bottomNav");

                if (u) {
                    isLoggedIn = true;
                    userName = u.displayName || userName || "Student";
                    userEmail = u.email || "";
                    if (u.photoURL && !userAvatarUrl.startsWith("data:image")) {
                        userAvatarUrl = getSafeAvatar(u.photoURL);
                    }

                    localStorage.setItem("isLoggedIn", "true");
                    localStorage.setItem("userName", userName);
                    localStorage.setItem("userEmail", userEmail);
                    window.AndroidPrefs?.setString?.("zorenoActiveUid", u.uid);

                    await loadUserProfile(u);
                    await ensureUniqueUsernameForUser(u);
                    startRealtimeCrossDeviceListeners(u.uid);
                    updateProfileUI();
                    updatePricingUI(currentCountry);
                    updateMyPresenceStatus(true);
                    startPresenceHeartbeat();
                    requestNotificationPermissionSafely();
                    await loadUserChatsFromFirebase();

                    if (splashScreen) splashScreen.style.setProperty("display", "none", "important");
                    if (authScreen) authScreen.style.setProperty("display", "none", "important");
                    if (bottomNav) bottomNav.style.setProperty("display", "flex", "important");

                    showChatsHome();
                } else {
                    isLoggedIn = false;
                    stopPresenceHeartbeat();
                    if (incomingChatsUnsub) { incomingChatsUnsub(); incomingChatsUnsub = null; }
                    if (liveUserDocUnsub) { liveUserDocUnsub(); liveUserDocUnsub = null; }
                    if (liveAiChatsUnsub) { liveAiChatsUnsub(); liveAiChatsUnsub = null; }
                    hideAllScreens();
                    if (bottomNav) bottomNav.style.setProperty("display", "none", "important");
                    if (authScreen) authScreen.style.setProperty("display", "flex", "important");
                    if (splashScreen) splashScreen.style.setProperty("display", "none", "important");
                }
            });

            return true;
        } catch (e) {
            console.error("Firebase init:", e);
            return false;
        }
    })();
    return firebaseReadyPromise;
}

function startRealtimeCrossDeviceListeners(uid) {
    if (!db || !uid) return;
    if (liveUserDocUnsub) liveUserDocUnsub();

    // Real-time listener on users/{uid} so Subscription Tier & Quota sync across devices in 1 second!
    liveUserDocUnsub = db.collection("users").doc(uid).onSnapshot(doc => {
        if (!doc.exists) return;
        const data = doc.data() || {};
        let remoteTier = typeof data.userTier === "number" ? data.userTier : 0;
        let remoteExp = data.subscriptionExpiresAtMs || data.subscriptionExpiryMs || 0;

        if (remoteTier > 0 && remoteExp > 0 && Date.now() > remoteExp) {
            remoteTier = 0;
            remoteExp = 0;
        }

        if (remoteTier !== userTier || remoteExp !== subExpiresAtMs) {
            setEffectiveTier(remoteTier, remoteExp);
            updatePricingUI(currentCountry);
            updateProfileUI();
        }
    }, () => {});
}

async function loadUserProfile(user) {
    if (!user) return;
    try {
        if (!db) await initFirebase();
        const userDocRef = db.collection("users").doc(user.uid);
        const userDoc = await userDocRef.get();

        if (userDoc.exists) {
            const data = userDoc.data();
            userName = data.name || user.displayName || "Student";
            currentUsername = data.username || "";
            currentBio = data.bio || currentBio;
            userAvatarUrl = getSafeAvatar(data.photoURL || data.avatarUrl || user.photoURL);

            if (data.blockedUsers && typeof data.blockedUsers === "object") {
                blockedUsersMap = { ...blockedUsersMap, ...data.blockedUsers };
                localStorage.setItem("zorenoBlockedUsers", JSON.stringify(blockedUsersMap));
            }

            const todayKey = getTodayLocalMidnightKey();
            if (data.dailyAiDate === todayKey) {
                const fbCount = typeof data.dailyAiCount === "number" ? data.dailyAiCount : 0;
                const fbLimit = typeof data.dailyAiLimit === "number" ? data.dailyAiLimit : 10;
                const finalCnt = Math.max(fbCount, getLocalDailyAiCount());
                const finalLim = Math.max(fbLimit, getLocalDailyAiLimit());
                localStorage.setItem("zorenoAiDate", todayKey);
                localStorage.setItem("zorenoAiCount", String(finalCnt));
                localStorage.setItem("zorenoAiLimitDate", todayKey);
                localStorage.setItem("zorenoAiDailyLimit", String(finalLim));
            }

            let savedTier = typeof data.userTier === "number" ? data.userTier : 0;
            let expiresMs = data.subscriptionExpiresAtMs || data.subscriptionExpiryMs || 0;

            if (savedTier > 0 && expiresMs > 0 && Date.now() > expiresMs) {
                savedTier = 0;
                expiresMs = 0;
                await userDocRef.set({ userTier: 0, subscriptionExpiresAtMs: 0 }, { merge: true });
            }

            setEffectiveTier(savedTier, expiresMs);
            localStorage.setItem("username", currentUsername);
            localStorage.setItem("userName", userName);
            localStorage.setItem("userBio", currentBio);
            localStorage.setItem("userAvatarUrl", userAvatarUrl);

            syncEditProfileInputs();
            updateProfileUI();
            updatePricingUI(currentCountry);
        } else {
            const cleanName = (user.displayName || "student").toLowerCase().replace(/[^a-z0-9]/g, "") || "student";
            const defaultUsername = `@${cleanName}_${Math.floor(1000 + Math.random() * 9000)}`;

            const initialData = {
                uid: user.uid,
                name: user.displayName || "Student",
                nameLower: (user.displayName || "Student").toLowerCase(),
                email: user.email || "",
                username: defaultUsername,
                usernameLower: defaultUsername.toLowerCase(),
                photoURL: getSafeAvatar(userAvatarUrl),
                bio: currentBio,
                userTier: 0,
                subscriptionExpiresAtMs: 0,
                isOnline: true,
                lastActiveAtMs: Date.now(),
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
            };

            await userDocRef.set(initialData, { merge: true });
            userName = initialData.name;
            currentUsername = initialData.username;
            userAvatarUrl = initialData.photoURL;

            localStorage.setItem("username", currentUsername);
            localStorage.setItem("userName", userName);
            localStorage.setItem("userAvatarUrl", userAvatarUrl);
            syncEditProfileInputs();
        }
    } catch (err) {
        console.error("Error loading user profile:", err);
    }
}

// ================= NAVIGATION & SCREENS =================
function closeAllDropdownMenus() {
    ["aiHeaderDropdownMenu", "dmHeaderDropdownMenu", "fpHeaderDropdownMenu"].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.style.display = "none";
    });
}

function hideAllScreens() {
    closeAllDropdownMenus();
    [
        "chatListScreen", "subScreen", "toolsScreen", "settingsScreen",
        "chatScreen", "webSearchScreen", "activeChatScreen", "profileScreen", "historyScreen", "friendProfileScreen"
    ].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.style.setProperty("display", "none", "important");
    });
}

function switchTab(tabId, element) {
    hideAllScreens();
    document.getElementById("inputAreaContainer")?.style.setProperty("display", "none", "important");
    document.getElementById("bottomNav")?.style.setProperty("display", "flex", "important");

    if (tabId === "chat") {
        document.getElementById("chatListScreen")?.style.setProperty("display", "block", "important");
    } else if (tabId === "pro") {
        document.getElementById("subScreen")?.style.setProperty("display", "block", "important");
        if (getEffectiveTier() === 1) selectedTierLevel = 2;
        updatePricingUI(currentCountry);
    } else if (tabId === "tools") {
        document.getElementById("toolsScreen")?.style.setProperty("display", "flex", "important");
    } else if (tabId === "settings") {
        document.getElementById("settingsScreen")?.style.setProperty("display", "block", "important");
    }

    document.querySelectorAll(".nav-item").forEach(btn => btn.classList.remove("active"));
    if (element) element.classList.add("active");
    window.scrollTo(0, 0);
}

function showChatsHome() {
    hideAllScreens();
    if (window.AndroidSecurity?.setScreenshotBlock) window.AndroidSecurity.setScreenshotBlock(false);
    document.getElementById("chatListScreen")?.style.setProperty("display", "block", "important");
    document.getElementById("inputAreaContainer")?.style.setProperty("display", "none", "important");
    document.getElementById("bottomNav")?.style.setProperty("display", "flex", "important");

    document.querySelectorAll(".nav-item").forEach(btn => btn.classList.remove("active"));
    const firstTab = document.querySelector(".floating-nav .nav-item");
    if (firstTab) firstTab.classList.add("active");
}

function goHome() {
    if (window.speechSynthesis) window.speechSynthesis.cancel();
    if (window.AndroidTTS?.stop) window.AndroidTTS.stop();
    showChatsHome();
}

function openSettings() {
    pushScreenState("settings");
    hideAllScreens();
    document.getElementById("settingsScreen")?.style.setProperty("display", "block", "important");
    document.getElementById("inputAreaContainer")?.style.setProperty("display", "none", "important");
}

function openSubscription() {
    pushScreenState("sub");
    hideAllScreens();
    document.getElementById("subScreen")?.style.setProperty("display", "block", "important");
    document.getElementById("inputAreaContainer")?.style.setProperty("display", "none", "important");
    selectedTierLevel = getEffectiveTier() >= 1 ? 2 : 1;
    updatePricingUI(currentCountry);
}

function openProfile() {
    pushScreenState("profile");
    hideAllScreens();
    document.getElementById("profileScreen")?.style.setProperty("display", "block", "important");
    document.getElementById("inputAreaContainer")?.style.setProperty("display", "none", "important");
    document.getElementById("bottomNav")?.style.setProperty("display", "none", "important");
    syncEditProfileInputs();
    updateProfileUI();
}

function pushScreenState(screenName) {
    try { history.pushState({ screen: screenName }, ""); } catch (e) {}
}

// Mutually Exclusive Dark Mode & Eye Protection Mode
function syncDarkModeUI(enabled) {
    const toggle = document.getElementById("darkModeToggle");
    if (toggle) toggle.classList.toggle("off", !enabled);
    const lightDot = document.getElementById("authThemeLight");
    const darkDot = document.getElementById("authThemeDark");
    if (lightDot && darkDot) {
        lightDot.classList.toggle("active", !enabled);
        darkDot.classList.toggle("active", enabled);
    }
}

function toggleDarkMode() {
    const willEnableDark = !document.body.classList.contains("dark-mode");
    if (willEnableDark && document.body.classList.contains("eye-care-mode")) {
        document.body.classList.remove("eye-care-mode");
        localStorage.setItem("eyeCareMode", "false");
        document.getElementById("eyeCareToggle")?.classList.add("off");
    }
    document.body.classList.toggle("dark-mode", willEnableDark);
    localStorage.setItem("darkMode", willEnableDark ? "true" : "false");
    syncDarkModeUI(willEnableDark);
}

function toggleEyeProtectionMode() {
    const willEnableEye = !document.body.classList.contains("eye-care-mode");
    if (willEnableEye && document.body.classList.contains("dark-mode")) {
        document.body.classList.remove("dark-mode");
        localStorage.setItem("darkMode", "false");
        syncDarkModeUI(false);
    }
    document.body.classList.toggle("eye-care-mode", willEnableEye);
    localStorage.setItem("eyeCareMode", willEnableEye ? "true" : "false");
    document.getElementById("eyeCareToggle")?.classList.toggle("off", !willEnableEye);
}

// ================= MODALS & POLICIES =================
function showCustomAlert(title, message, isSuccess = false) {
    const modal = document.getElementById("alertModal");
    if (!modal) return alert(`${title}\n\n${message}`);
    const titleEl = document.getElementById("alertModalTitle");
    const msgEl = document.getElementById("alertModalMsg");
    const iconEl = document.getElementById("alertModalIcon");

    if (titleEl) titleEl.textContent = title || "Notice";
    if (msgEl) msgEl.textContent = message || "";
    if (iconEl) {
        iconEl.className = isSuccess ? "modal-icon" : "modal-icon error-icon";
        iconEl.innerHTML = isSuccess
            ? '<i class="fa-solid fa-circle-check" style="color:#16a34a;"></i>'
            : '<i class="fa-solid fa-circle-info"></i>';
    }
    modal.style.display = "flex";
}

function closeCustomAlert() {
    const modal = document.getElementById("alertModal");
    if (modal) modal.style.display = "none";
}

function closePolicyModal() {
    const modal = document.getElementById("policyModal");
    if (modal) modal.style.display = "none";
}

// =========================================================
// ZORENO CLEAN MASTER APP.JS — PART 2 OF 4
// POLICIES, PRICING, 10-TAP VAULT, AUTH, ZORENO ACCOUNT & PROFILE
// =========================================================

async function openPolicyModal(type) {
    const modal = document.getElementById("policyModal");
    if (!modal) return;
    const modalBox = modal.querySelector(".custom-modal-box");
    if (modalBox) modalBox.classList.add("zoreno-frosted-modal-card");

    const titleEl = document.getElementById("policyModalTitle");
    const contentEl = document.getElementById("policyModalContent");
    const acceptBtn = modal.querySelector(".modal-submit-btn");

    const masterPolicies = {
        terms: {
            title: "Terms & Conditions",
            body: `<h3>1. Acceptance of Terms</h3><p>By accessing and using Zoreno (operated by Toko Platforms), you agree to comply with these Terms & Conditions and applicable app store policies.</p><h3>2. AI-Generated Content Disclaimer</h3><p>Zoreno uses advanced AI models to assist with study and general queries. Users can report any inappropriate AI response using the Feedback option in the chat menu.</p><h3>3. User-Generated Content (UGC) & Safety</h3><p>In direct messaging, abusive, spam, or illegal content is strictly prohibited. Users can Block and Report any user from the 3-dot chat menu.</p><h3>4. 30-Day Subscription Validity</h3><p>Zoreno Plus and Zoreno Pro remain active for 30 days from purchase via Google Play Billing or Razorpay.</p>`
        },
        privacy: {
            title: "Privacy Policy & Data Safety",
            body: `<h3>1. Information We Collect</h3><p>We collect basic account details (Name, Email, Username, optional Profile Photo) and chat messages via Google Firebase to provide real-time sync.</p><h3>2. Data Storage & Security</h3><p>All data is transmitted over encrypted HTTPS/TLS connections and stored on Google Firebase servers.</p><h3>3. Account & Data Deletion</h3><p>You can permanently delete your account and all associated data anytime directly from Settings -> Delete Account.</p>`
        },
        refund: {
            title: "Refund & Cancellation Policy",
            body: `<h3>1. Subscription Validity & Cancellation</h3><p>Purchased plans are active for 30 days. You may manage or cancel renewals anytime through Google Play Subscriptions or support.</p><h3>2. Payment Issues</h3><p>If payment is deducted without plan activation, contact support with your transaction ID for immediate resolution.</p>`
        }
    };

    const basePolicy = masterPolicies[type];
    if (!basePolicy) return;

    if (titleEl) titleEl.textContent = basePolicy.title;
    if (contentEl) contentEl.innerHTML = basePolicy.body;
    if (acceptBtn) acceptBtn.textContent = "I Understand & Accept";
    modal.style.display = "flex";

    const langCode = localStorage.getItem("zorenoAppLangCode") || "en-IN";
    const baseLang = langCode.split("-")[0];
    if (baseLang === "en" || typeof translateStringArrayViaGtx !== "function") return;

    try {
        const nodes = Array.from(contentEl.querySelectorAll("h3, p"));
        const linesToTranslate = [basePolicy.title, "I Understand & Accept", ...nodes.map(n => n.innerText.trim())];
        const translatedArr = await translateStringArrayViaGtx(linesToTranslate, langCode);
        if (translatedArr && translatedArr.length === linesToTranslate.length) {
            if (titleEl) titleEl.textContent = translatedArr[0];
            if (acceptBtn) acceptBtn.textContent = translatedArr[1];
            nodes.forEach((n, idx) => { n.textContent = translatedArr[idx + 2]; });
        }
    } catch (e) {}
}

// ================= COUNTRY MODAL & SUBSCRIPTION PRICING =================
function openWorldCountryModal() {
    const modal = document.getElementById("worldCountryModal");
    const searchInput = document.getElementById("countrySearchInput");
    if (searchInput) searchInput.value = "";
    renderWorldCountries(RAW_WORLD_COUNTRIES);
    if (modal) modal.style.display = "flex";
}

function closeWorldCountryModal() {
    const modal = document.getElementById("worldCountryModal");
    if (modal) modal.style.display = "none";
}

function filterWorldCountries(query) {
    const q = (query || "").toLowerCase().trim();
    const filtered = RAW_WORLD_COUNTRIES.filter(c =>
        c.name.toLowerCase().includes(q) || c.code.toLowerCase().includes(q)
    );
    renderWorldCountries(filtered);
}

function renderWorldCountries(list) {
    const container = document.getElementById("worldCountryList");
    if (!container) return;
    container.innerHTML = list.map(c => {
        const isSelected = c.code === currentCountry;
        return `
            <div class="world-country-option ${isSelected ? 'active' : ''}" onclick="selectWorldCountry('${c.code}')">
                <div class="wc-left">
                    <span class="wc-flag">${c.flag}</span>
                    <div class="wc-text">
                        <h5>${c.name}</h5>
                        <span>${c.curr}</span>
                    </div>
                </div>
                <div class="wc-radio">
                    ${isSelected ? '<i class="fa-solid fa-circle-check"></i>' : '<i class="fa-regular fa-circle"></i>'}
                </div>
            </div>
        `;
    }).join("");
}

function selectWorldCountry(code) {
    currentCountry = code || "IN";
    localStorage.setItem("manualCountry", currentCountry);
    updatePricingUI(currentCountry);
    closeWorldCountryModal();
}

function detectAndSetCountry() {
    const saved = localStorage.getItem("manualCountry");
    if (saved) {
        currentCountry = saved;
        updatePricingUI(saved);
        return;
    }
    fetch("https://ipapi.co/json/")
        .then(r => r.json())
        .then(data => {
            const code = data?.country_code || "IN";
            currentCountry = code;
            localStorage.setItem("manualCountry", code);
            updatePricingUI(code);
        })
        .catch(() => {
            currentCountry = "IN";
            updatePricingUI("IN");
        });
}

function getRemainingSubDays() {
    if (!subExpiresAtMs || subExpiresAtMs <= Date.now()) return 30;
    return Math.max(1, Math.ceil((subExpiresAtMs - Date.now()) / (24 * 60 * 60 * 1000)));
}

function selectPlan(tierLevel) {
    const activeTier = getEffectiveTier();
    if (activeTier >= 2) {
        showCompactGlassToast("✓", `Zoreno Pro Active (${getRemainingSubDays()}d left)`);
        return;
    }
    if (activeTier === 1 && tierLevel <= 1) {
        showCompactGlassToast("✦", "Plus is already active. Select Pro to upgrade!");
        selectedTierLevel = 2;
        updatePricingUI(currentCountry);
        return;
    }
    selectedTierLevel = tierLevel;
    updatePricingUI(currentCountry);
}

function updatePricingUI(countryCode) {
    const activeTier = getEffectiveTier();
    currentCountry = countryCode || localStorage.getItem("manualCountry") || "IN";
    localStorage.setItem("manualCountry", currentCountry);

    const isIndia = currentCountry === "IN";
    const symbol = isIndia ? "₹" : "$";
    const plusPrice = isIndia ? 249 : 3.99;
    const proPrice = isIndia ? 349 : 6.99;

    const found = RAW_WORLD_COUNTRIES.find(c => c.code === currentCountry) || RAW_WORLD_COUNTRIES[0];
    const displayEl = document.getElementById("selectedCountryDisplay");
    if (displayEl) displayEl.innerText = `${found.flag} ${found.name} (${symbol})`;

    const plusCard = document.getElementById("plusPlanCard");
    const proCard = document.getElementById("proPlanCard");
    const plan1Title = document.getElementById("plan1Title");
    const plan2Title = document.getElementById("plan2Title");
    const plan1Desc = document.getElementById("plan1Description");
    const plan2Desc = document.getElementById("plan2Description");
    const payBtn = document.getElementById("payButtonText");
    const payBtnText = document.querySelector("#payButtonText .btn-text");

    if (plan1Title) plan1Title.innerText = `${symbol}${plusPrice} / Month (Plus)`;
    if (plan2Title) plan2Title.innerText = `${symbol}${proPrice} / Month (Pro)`;

    const daysLeft = getRemainingSubDays();

    if (activeTier === 0) {
        if (plan1Desc) plan1Desc.innerText = "Higher AI Limits • 30 Days Validity";
        if (plan2Desc) plan2Desc.innerText = "Highest AI Limits • 30 Days • Vision";
        if (plusCard) {
            plusCard.style.opacity = "1";
            plusCard.classList.toggle("active", selectedTierLevel === 1);
        }
        if (proCard) {
            proCard.style.opacity = "1";
            proCard.classList.toggle("active", selectedTierLevel === 2);
        }
        selectedAmount = selectedTierLevel === 2 ? proPrice : plusPrice;
        if (payBtn) {
            payBtn.disabled = false;
            payBtn.style.opacity = "1";
            payBtn.style.background = "";
        }
        if (payBtnText) payBtnText.innerText = `Upgrade to ${selectedTierLevel === 2 ? "Pro" : "Plus"} (${symbol}${selectedAmount})`;
    } else if (activeTier === 1) {
        if (plan1Desc) plan1Desc.innerHTML = `<strong style="color:#10b981;">✓ Plus Active (${daysLeft}d Left)</strong>`;
        if (plan2Desc) plan2Desc.innerText = "Upgrade for Highest AI Limits & Pro Tools";
        if (plusCard) {
            plusCard.classList.remove("active");
            plusCard.style.opacity = "0.55";
        }
        if (proCard) {
            proCard.classList.add("active");
            proCard.style.opacity = "1";
        }
        selectedTierLevel = 2;
        selectedAmount = proPrice;
        if (payBtn) {
            payBtn.disabled = false;
            payBtn.style.opacity = "1";
            payBtn.style.background = "";
        }
        if (payBtnText) payBtnText.innerText = `Upgrade to Pro (${symbol}${proPrice})`;
    } else {
        if (plan1Desc) plan1Desc.innerHTML = `<span style="color:#10b981; font-weight:700;">✓ Included in your Pro plan</span>`;
        if (plan2Desc) plan2Desc.innerHTML = `<strong style="color:#10b981;">✓ Pro Active (${daysLeft}d) • All Unlocked</strong>`;
        if (plusCard) {
            plusCard.classList.remove("active");
            plusCard.style.opacity = "0.45";
        }
        if (proCard) {
            proCard.classList.add("active");
            proCard.style.opacity = "1";
        }
        if (payBtn) {
            payBtn.disabled = true;
            payBtn.style.opacity = "0.95";
            payBtn.style.background = "linear-gradient(135deg, #059669, #10b981)";
        }
        if (payBtnText) payBtnText.innerText = `Zoreno Pro Active ✓`;
    }
    renderCleanPremiumFeatureList();
}

async function activateUserSubscriptionInFirestore(newTier, paymentReferenceId, providerName) {
    const expMs = Date.now() + SUBSCRIPTION_VALIDITY_MS;
    setEffectiveTier(newTier, expMs);

    if (db && auth?.currentUser) {
        await db.collection("users").doc(auth.currentUser.uid).set({
            userTier: newTier,
            subscriptionExpiresAtMs: expMs,
            paymentId: paymentReferenceId || "",
            paymentProvider: providerName || "unknown",
            subscriptionUpdatedAt: firebase.firestore.FieldValue.serverTimestamp()
        }, { merge: true });
    }

    updatePricingUI(currentCountry);
    updateProfileUI();
    showCustomAlert(
        "Subscription Activated (30 Days)! 🎉",
        `Welcome to Zoreno ${newTier === 2 ? "Pro" : "Plus"}! Your plan is now active across all your devices.`,
        true
    );
}

window.onPlayBillingSuccess = function (tierLevel, purchaseToken) {
    activateUserSubscriptionInFirestore(parseInt(tierLevel, 10) || selectedTierLevel, purchaseToken || "play_billing", "google_play");
};

async function openRazorpayCheckout(targetTierOverride) {
    const targetTier = targetTierOverride || selectedTierLevel || 1;
    const isIndia = currentCountry === "IN";
    const plusPrice = isIndia ? 249 : 3.99;
    const proPrice = isIndia ? 349 : 6.99;
    const finalAmount = targetTier === 2 ? proPrice : plusPrice;

    if (!window.Razorpay) {
        try {
            await loadExternalScript("https://checkout.razorpay.com/v1/checkout.js", "rzp-checkout-js");
        } catch (e) {
            showCustomAlert("Loading Payment", "Payment gateway could not be loaded. Please check your internet connection.");
            return;
        }
    }

    const options = {
        key: RAZORPAY_KEY_ID,
        amount: Math.round(finalAmount * 100),
        currency: isIndia ? "INR" : "USD",
        name: "Zoreno",
        description: targetTier === 2 ? "Zoreno Pro (30 Days)" : "Zoreno Plus (30 Days)",
        handler: async function (response) {
            await activateUserSubscriptionInFirestore(targetTier, response?.razorpay_payment_id || "rzp_store", "razorpay");
        },
        prefill: { name: userName || "", email: userEmail || "" },
        theme: { color: "#7c3aed" }
    };
    const rzp = new Razorpay(options);
    rzp.open();
}

window.triggerRazorpayFallback = function () {
    openRazorpayCheckout(selectedTierLevel);
};

async function triggerRazorpay() {
    const activeTier = getEffectiveTier();
    if (activeTier >= 2) {
        showCompactGlassToast("✓", `Zoreno Pro is already active (${getRemainingSubDays()}d left)`);
        return;
    }
    if (activeTier === 1 && selectedTierLevel <= 1) {
        selectedTierLevel = 2;
        updatePricingUI(currentCountry);
    }

    const targetTier = selectedTierLevel;
    const skuId = PLAY_BILLING_SKUS[targetTier];
    const isPlayStoreInstall = window.AndroidPrefs?.isFromPlayStore ? window.AndroidPrefs.isFromPlayStore() : false;

    if (isPlayStoreInstall && window.AndroidBilling?.purchaseSubscription) {
        window.AndroidBilling.purchaseSubscription(skuId, targetTier);
        return;
    }
    await openRazorpayCheckout(targetTier);
}

