// 10-Tap Crown Secret Vault (Double Password Verification)
let crownTapCounter = 0;
let crownTapTimer = null;
window.selectedVaultTierTab = 2;
window.vaultPasswordStep = 1;
window.vaultStep1EnteredPass = "";


document.addEventListener("click", (e) => {
    const crownEl = e.target.closest("#subScreen .liquid-crown-badge, #subScreen .fa-crown");
    if (crownEl) {
        e.stopPropagation();
        crownTapCounter++;
        clearTimeout(crownTapTimer);
        if (crownTapCounter >= 10) {
            crownTapCounter = 0;
            window.vaultPasswordStep = 1;
            window.vaultStep1EnteredPass = "";
            if (navigator.vibrate) navigator.vibrate([40, 60, 40]);
            openFounderSecretTierVaultModal();
            return;
        }
        crownTapTimer = setTimeout(() => { crownTapCounter = 0; }, 3000);
    }
}, true);

// Clean AI Daily Energy (%) Modal (33544 Fix: No Text Overlap & No Crown Spam)
window.openZorenoUsageLimitModal = function () {
    closeAllDropdownMenus();
    let modal = document.getElementById("zorenoUsageLimitModal");
    if (!modal) {
        modal = document.createElement("div");
        modal.id = "zorenoUsageLimitModal";
        modal.className = "custom-modal-overlay";
        document.body.appendChild(modal);
    }
    modal.style.setProperty("z-index", "2147483647", "important");

    const tierNow = getEffectiveTier();
    const usedCount = getLocalDailyAiCount();
    const totalCap = tierNow === 2 ? Math.max(90, getLocalDailyAiLimit()) : tierNow === 1 ? Math.max(50, getLocalDailyAiLimit()) : getLocalDailyAiLimit();

    let remainingPct = Math.max(0, Math.min(100, Math.round(((totalCap - usedCount) / Math.max(1, totalCap)) * 100)));
    if (usedCount >= totalCap) remainingPct = 0;
    const usedPct = 100 - remainingPct;

    const planTitle = tierNow === 2
        ? "Zoreno Pro • Maximum AI Capacity"
        : tierNow === 1
            ? "Zoreno Plus • Expanded AI Capacity"
            : "Standard Tier • Daily Free Capacity";

    modal.innerHTML = `
        <div class="custom-modal-box zoreno-frosted-modal-card" style="max-width:365px; text-align:left; padding:22px;">
            <div class="policy-modal-header" style="margin-bottom:14px;">
                <h3 style="display:flex; align-items:center; gap:9px; font-size:17.5px; font-weight:800; margin:0;">
                    <i class="fa-solid fa-bolt" style="color:#7c3aed;"></i>
                    <span>AI Daily Energy & Usage</span>
                </h3>
                <button type="button" class="modal-close-btn" onclick="document.getElementById('zorenoUsageLimitModal').style.display='none'">
                    <i class="fa-solid fa-xmark"></i>
                </button>
            </div>

            <div style="background:rgba(124,58,237,0.09); border:1px solid rgba(124,58,237,0.24); border-radius:18px; padding:14px; margin-bottom:16px;">
                <div style="font-size:10.5px; font-weight:800; color:#7c3aed;">ACTIVE PLAN</div>
                <div style="font-size:15px; font-weight:800; margin-top:3px;">${escapeHtml(planTitle)}</div>
                <div style="font-size:11.5px; color:#64748b; margin-top:4px;">Refills to 100% every midnight (12:00 AM)</div>
            </div>

            <div style="margin-bottom:12px;">
                <div style="display:flex; justify-content:space-between; align-items:baseline; margin-bottom:8px;">
                    <span style="font-size:13px; font-weight:700; color:#64748b;">Available AI Energy</span>
                    <span style="font-size:22px; font-weight:900; color:${remainingPct > 20 ? '#10b981' : '#ef4444'};">${remainingPct}%</span>
                </div>
                <div style="width:100%; height:11px; background:rgba(148,163,184,0.2); border-radius:99px; overflow:hidden;">
                    <div style="width:${remainingPct}%; height:100%; background:linear-gradient(90deg,#10b981,#06b6d4); border-radius:99px; transition:width 0.35s ease;"></div>
                </div>
                <div style="display:flex; justify-content:space-between; font-size:11.5px; color:#64748b; margin-top:8px; font-weight:700;">
                    <span>Consumed Today: ${usedPct}%</span>
                    <span>Remaining: ${remainingPct}%</span>
                </div>
            </div>

            ${tierNow < 2 ? `
            <button type="button" class="modal-submit-btn" style="background:linear-gradient(135deg,#2563eb,#7c3aed); font-weight:800; margin-top:8px;" onclick="document.getElementById('zorenoUsageLimitModal').style.display='none'; openSubscription();">
                Upgrade AI Capacity
            </button>` : ""}
        </div>
    `;
    modal.style.display = "flex";
};

