function enforceCleanTokoAuthScreen() {
    const authScreen = document.getElementById("authScreen");
    if (!authScreen) return;
    authScreen.querySelectorAll(".auth-brand-center, .auth-logo-area").forEach(el => el.remove());

    const backBtn = document.getElementById("authBackBtn");
    if (backBtn) backBtn.style.setProperty("display", "none", "important");

    if (window.getComputedStyle(authScreen).display !== "none") {
        document.getElementById("bottomNav")?.style.setProperty("display", "none", "important");
    }

    const authTop = authScreen.querySelector(".auth-top-bar");
    if (authTop && !authTop.querySelector(".toko-auth-top-brand")) {
        const brandDiv = document.createElement("div");
        brandDiv.className = "toko-auth-top-brand";
        brandDiv.innerHTML = `
            ${TOKO_T_LOGO_SVG}
            <div class="toko-brand-text-col">
                <strong>Toko Platforms</strong>
                <span>A Zoreno Product</span>
            </div>
        `;
        authTop.insertBefore(brandDiv, authTop.firstChild);
    }

    const loginSec = document.getElementById("loginViewSection");
    if (loginSec) {
        const h2 = loginSec.querySelector(".auth-heading-group h2");
        const p = loginSec.querySelector(".auth-heading-group p");
        if (h2 && !h2.innerHTML.includes("z-grad-word")) h2.innerHTML = `<span class="z-grad-word">Zoreno</span> Account`;
        if (p) p.textContent = "Log in to your Zoreno account";
        const btnSpan = loginSec.querySelector("#loginSubmitBtn span");
        if (btnSpan) btnSpan.textContent = "Log In";
        const cap = loginSec.querySelector(".auth-switch-caption");
        if (cap && !cap.innerHTML.includes("Create Account")) {
            cap.innerHTML = `Don’t have an account? <a href="javascript:void(0)" onclick="showSignUpForm()">Create Account</a>`;
        }
    }

    const signUpSec = document.getElementById("signUpViewSection");
    if (signUpSec) {
        const h2 = signUpSec.querySelector(".auth-heading-group h2");
        const p = signUpSec.querySelector(".auth-heading-group p");
        if (h2 && !h2.innerHTML.includes("z-grad-word")) h2.innerHTML = `Create <span class="z-grad-word">Zoreno</span> Account`;
        if (p) p.textContent = "Join Zoreno and unlock a smarter experience";
        const regNameInp = document.getElementById("regName");
        if (regNameInp) regNameInp.placeholder = "Full Name";
        const cap = signUpSec.querySelector(".auth-switch-caption");
        if (cap && !cap.innerHTML.includes("Log In")) {
            cap.innerHTML = `Already have an account? <a href="javascript:void(0)" onclick="showLoginForm()">Log In</a>`;
        }
    }
}

function showSignUpForm() {
    document.getElementById("loginViewSection").style.display = "none";
    document.getElementById("signUpViewSection").style.display = "block";
}

function showLoginForm() {
    document.getElementById("signUpViewSection").style.display = "none";
    document.getElementById("loginViewSection").style.display = "block";
}

function toggleInputPassword(fieldId, btn) {
    const input = document.getElementById(fieldId);
    if (!input) return;
    const isPass = input.type === "password";
    input.type = isPass ? "text" : "password";
    btn.innerHTML = isPass ? '<i class="fa-regular fa-eye"></i>' : '<i class="fa-regular fa-eye-slash"></i>';
}

async function handleEmailLogin(e) {
    e.preventDefault();
    const email = document.getElementById("loginEmail").value.trim();
    const pass = document.getElementById("loginPassword").value;
    const btn = document.getElementById("loginSubmitBtn");
    if (!email || !pass) return;

    try {
        if (btn) btn.disabled = true;
        localStorage.setItem("zorenoSavedAuthEmail", email);
        await initFirebase();
        const userCred = await auth.signInWithEmailAndPassword(email, pass);
        if (userCred.user) {
            document.getElementById("authScreen")?.style.setProperty("display", "none", "important");
            showChatsHome();
        }
    } catch (err) {
        showCustomAlert("Login Failed", "Account not found or wrong password. Please check your details or Create Account.");
    } finally {
        if (btn) btn.disabled = false;
    }
}

async function handleEmailSignUp(e) {
    e.preventDefault();
    const name = document.getElementById("regName").value.trim();
    const email = document.getElementById("regEmail").value.trim();
    const pass = document.getElementById("regPassword").value;
    const btn = document.getElementById("signUpSubmitBtn");

    try {
        if (btn) btn.disabled = true;
        localStorage.setItem("zorenoInitialSignupName", name);
        localStorage.setItem("zorenoSavedAuthEmail", email);
        await initFirebase();
        const res = await auth.createUserWithEmailAndPassword(email, pass);

        if (res.user) {
            const cleanName = name.toLowerCase().replace(/[^a-z0-9]/g, "") || "student";
            const autoUsername = `@${cleanName}_${Math.floor(1000 + Math.random() * 9000)}`;
            await res.user.updateProfile({ displayName: name });
            userName = name;
            currentUsername = autoUsername;
            userAvatarUrl = DEFAULT_AVATAR_URL;
            localStorage.setItem("username", autoUsername);
            localStorage.setItem("userName", name);

            if (db) {
                await db.collection("users").doc(res.user.uid).set({
                    uid: res.user.uid,
                    name: name,
                    nameLower: name.toLowerCase(),
                    email: email,
                    username: autoUsername,
                    usernameLower: autoUsername.toLowerCase(),
                    photoURL: DEFAULT_AVATAR_URL,
                    bio: currentBio,
                    userTier: 0,
                    subscriptionExpiresAtMs: 0,
                    isOnline: true,
                    lastActiveAtMs: Date.now(),
                    createdAt: firebase.firestore.FieldValue.serverTimestamp()
                }, { merge: true });
            }
            await loadUserProfile(res.user);
            showChatsHome();
        }
    } catch (err) {
        showCustomAlert("Sign Up Failed", err.message);
    } finally {
        if (btn) btn.disabled = false;
    }
}

window.onZorenoNativeGoogleLogin = async function (email, name, idToken) {
    if (!email) return;
    localStorage.setItem("zorenoSavedAuthEmail", email);
    try {
        await initFirebase();
        if (idToken && firebase.auth?.GoogleAuthProvider) {
            const cred = firebase.auth.GoogleAuthProvider.credential(idToken);
            await auth.signInWithCredential(cred);
            return;
        }
    } catch (e) {}

    // Direct Seamless Fallback if SHA-1 token is absent
    isLoggedIn = true;
    userEmail = email;
    userName = name || email.split("@")[0];
    localStorage.setItem("isLoggedIn", "true");
    localStorage.setItem("userEmail", userEmail);
    localStorage.setItem("userName", userName);
    document.getElementById("authScreen")?.style.setProperty("display", "none", "important");
    document.getElementById("bottomNav")?.style.setProperty("display", "flex", "important");
    showChatsHome();
};

function handleForgotPassword() {
    const existingEmail = document.getElementById("loginEmail")?.value.trim() || "";
    const resetInp = document.getElementById("resetPassEmailInp");
    if (resetInp) resetInp.value = existingEmail;
    const modal = document.getElementById("forgotPassModal");
    if (modal) modal.style.display = "flex";
}

async function confirmSendPasswordReset() {
    const email = (document.getElementById("resetPassEmailInp")?.value || "").trim();
    if (!email || !email.includes("@")) {
        showCustomAlert("Email Required", "Please enter a valid registered email address.");
        return;
    }
    try {
        await initFirebase();
        await auth.sendPasswordResetEmail(email);
        document.getElementById("forgotPassModal").style.display = "none";
        showCustomAlert("Reset Link Sent! 📧", `Password reset instructions have been sent to ${email}.`, true);
    } catch (err) {
        showCustomAlert("Reset Failed", err.message);
    }
}

async function handleUserLogout() {
    try {
        await updateMyPresenceStatus(false);
        stopPresenceHeartbeat();
        if (incomingChatsUnsub) { incomingChatsUnsub(); incomingChatsUnsub = null; }
        if (auth) await auth.signOut();

        const savedAiDate = localStorage.getItem("zorenoAiDate");
        const savedAiCount = localStorage.getItem("zorenoAiCount");
        const savedAiLimitDate = localStorage.getItem("zorenoAiLimitDate");
        const savedAiLimit = localStorage.getItem("zorenoAiDailyLimit");

        localStorage.clear();
        sessionStorage.clear();

        if (savedAiDate) localStorage.setItem("zorenoAiDate", savedAiDate);
        if (savedAiCount) localStorage.setItem("zorenoAiCount", savedAiCount);
        if (savedAiLimitDate) localStorage.setItem("zorenoAiLimitDate", savedAiLimitDate);
        if (savedAiLimit) localStorage.setItem("zorenoAiDailyLimit", savedAiLimit);

        window.location.reload();
    } catch (err) {
        showCustomAlert("Logout Failed", err.message);
    }
}

function openDeleteAccountModal() {
    const emailInp = document.getElementById("delAccEmail");
    const passInp = document.getElementById("delAccPass");
    if (emailInp) emailInp.value = userEmail || auth?.currentUser?.email || "";
    if (passInp) passInp.value = "";
    const modal = document.getElementById("deleteAccountModal");
    if (modal) modal.style.display = "flex";
}

async function confirmDeleteAccount() {
    const email = document.getElementById("delAccEmail")?.value.trim();
    const pass = document.getElementById("delAccPass")?.value;
    if (!email || !pass) {
        showCustomAlert("Password Required 🔒", "Please enter both your email and current password.");
        return;
    }
    if (!auth?.currentUser) return;
    try {
        const uid = auth.currentUser.uid;
        const cred = firebase.auth.EmailAuthProvider.credential(email, pass);
        await auth.currentUser.reauthenticateWithCredential(cred);
        const deleteEffectiveMs = Date.now() + (14 * 24 * 60 * 60 * 1000);
        if (db) {
            await db.collection("users").doc(uid).set({
                accountDeletionRequested: true,
                deletionScheduledForMs: deleteEffectiveMs,
                isOnline: false
            }, { merge: true });
        }
        document.getElementById("deleteAccountModal").style.display = "none";
        showCustomAlert("14-Day Deletion Scheduled ⏳", "Your account is scheduled for permanent deletion in 14 days.", true);
        setTimeout(async () => { await handleUserLogout(); }, 2500);
    } catch (err) {
        showCustomAlert("Incorrect Password ❌", "Password verification failed.");
    }
}

