function injectManageZorenoAccountInSettings() {
    const settingsScreen = document.getElementById("settingsScreen");
    if (!settingsScreen || document.getElementById("zorenoManageAccountSettingCard")) return;
    const firstSectionTitle = settingsScreen.querySelector(".settings-section-title");
    if (!firstSectionTitle) return;

    const accCard = document.createElement("div");
    accCard.id = "zorenoManageAccountSettingCard";
    accCard.className = "settings-card";
    accCard.style.marginBottom = "18px";
    accCard.innerHTML = `
        <div class="setting-item" onclick="openZorenoAccountCenter()">
            <div class="setting-item-left">
                <div class="setting-icon" style="background:linear-gradient(135deg,#06b6d4,#7c3aed); color:#ffffff;">
                    <i class="fa-solid fa-user-shield"></i>
                </div>
                <div class="setting-text">
                    <h4>Manage Zoreno Account</h4>
                    <p>Account, password, security & privacy</p>
                </div>
            </div>
            <div class="setting-item-right"><i class="fa-solid fa-chevron-right"></i></div>
        </div>
    `;
    settingsScreen.insertBefore(accCard, firstSectionTitle);
}

