window.linkOrUpdateEmailPassword = async function () {
    const newPw = (document.getElementById("zaNewPassInlineInp")?.value || "").trim();
    if (!newPw || newPw.length < 6) {
        showCompactGlassToast("⚠️", "Password must be at least 6 characters");
        return;
    }
    localStorage.setItem("zorenoSavedAccountPassword", newPw);
    const u = auth?.currentUser;
    if (u && u.email) {
        try {
            const cred = firebase.auth.EmailAuthProvider.credential(u.email, newPw);
            await u.linkWithCredential(cred);
        } catch (linkErr) {
            try { await u.updatePassword(newPw); } catch (upErr) {}
        }
    }
    openZorenoAccountSubSection("security");
    showCompactGlassToast("✓", "Email + Password Login Enabled!");
};

window.setMyZorenoAccentColor = function (hexColor) {
    if (getEffectiveTier() < 1) {
        document.getElementById("zorenoAccountSubModal")?.style.setProperty("display", "none");
        closeZorenoAccountCenter();
        openSubscription();
        showCompactGlassToast("✦", "Unlock Plus or Pro for Custom Colors!");
        return;
    }
    myProfileAccentColor = hexColor;
    localStorage.setItem("zorenoMyAccentColor", hexColor);

    let dynColorStyle = document.getElementById("zorenoDynamicAccentStyle");
    if (!dynColorStyle) {
        dynColorStyle = document.createElement("style");
        dynColorStyle.id = "zorenoDynamicAccentStyle";
        document.head.appendChild(dynColorStyle);
    }
    dynColorStyle.textContent = `
        .clean-right-bubble:not(.media-only-bubble):not(.sticker-transparent-bubble),
        .chat-send-btn,
        .profile-save-btn {
            background: linear-gradient(135deg, ${hexColor} 0%, #7c3aed 100%) !important;
        }
    `;
    const previewBubble = document.getElementById("zaLiveColorPreviewBubble");
    if (previewBubble) {
        previewBubble.style.background = `linear-gradient(135deg, ${hexColor} 0%, #7c3aed 100%)`;
    }
    showCompactGlassToast("🎨", "Chat Bubble Color Applied!");
};

// ================= PROFILE EDIT & PRESENCE HEARTBEAT =================
function getSubscriptionBadgeHTML(tierLevel) {
    const t = parseInt(tierLevel, 10) || 0;
    if (t === 1) {
        return `<span class="zoreno-sub-badge plus-green-badge"><i class="fa-solid fa-circle-check"></i> Plus</span>`;
    } else if (t >= 2) {
        return `<span class="zoreno-sub-badge pro-blue-badge">Pro</span>`;
    }
    return "";
}

function updateProfileUI() {
    const activeTier = getEffectiveTier();
    const tierLabel = activeTier === 2
        ? `Pro Member (${getRemainingSubDays()}d left)`
        : activeTier === 1
            ? `Plus Member (${getRemainingSubDays()}d left)`
            : "Free Member";
    const cardTierEl = document.getElementById("profileCardTierTitle");
    if (cardTierEl) cardTierEl.textContent = tierLabel;

    const avImg = document.getElementById("profileEditAvatarImg");
    if (avImg) avImg.src = getSafeAvatar(userAvatarUrl);

    const badge = document.getElementById("profileUsernameBadge");
    if (badge) badge.innerHTML = `${escapeHtml(currentUsername || "@student")} ${getSubscriptionBadgeHTML(activeTier)}`;
}

function syncEditProfileInputs() {
    const uInp = document.getElementById("profileEditUsername");
    const nInp = document.getElementById("profileEditName");
    const bInp = document.getElementById("profileEditBio");
    const avImg = document.getElementById("profileEditAvatarImg");

    if (uInp) uInp.value = (currentUsername || "").replace(/^@/, "");
    if (nInp) nInp.value = userName || "Student";
    if (bInp) bInp.value = currentBio;
    if (avImg) avImg.src = getSafeAvatar(userAvatarUrl);
}

function previewAndUploadProfilePic(event) {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = function (e) {
        const img = new Image();
        img.onload = async function () {
            const canvas = document.createElement("canvas");
            const MAX_SIZE = 200;
            let w = img.width, h = img.height;
            if (w > h && w > MAX_SIZE) { h = Math.round((h * MAX_SIZE) / w); w = MAX_SIZE; }
            else if (h >= w && h > MAX_SIZE) { w = Math.round((w * MAX_SIZE) / h); h = MAX_SIZE; }
            canvas.width = w;
            canvas.height = h;
            canvas.getContext("2d").drawImage(img, 0, 0, w, h);

            const compressedBase64 = canvas.toDataURL("image/jpeg", 0.72);
            userAvatarUrl = compressedBase64;
            localStorage.setItem("userAvatarUrl", compressedBase64);
            updateProfileUI();

            const zaImg = document.querySelector("#zorenoAccountCenterScreen .za-avatar-wrap img");
            if (zaImg) zaImg.src = compressedBase64;

            if (db && auth?.currentUser) {
                try {
                    await db.collection("users").doc(auth.currentUser.uid).set({
                        photoURL: compressedBase64,
                        avatarUrl: compressedBase64,
                        updatedAt: firebase.firestore.FieldValue.serverTimestamp()
                    }, { merge: true });
                } catch (err) {}
            }
        };
        img.src = e.target.result;
    };
    reader.readAsDataURL(file);
}

async function ensureUniqueUsernameForUser(u) {
    if (!db || !u) return;
    try {
        const userRef = db.collection("users").doc(u.uid);
        const snap = await userRef.get();
        let data = snap.exists ? snap.data() : {};

        if (data.username && data.username !== "@user" && data.username !== "@friend") {
            currentUsername = data.username;
        } else {
            const base = (u.displayName || userName || "student").toLowerCase().replace(/[^a-z0-9]/g, "").slice(0, 10) || "student";
            currentUsername = `@${base}_${Math.floor(1000 + Math.random() * 9000)}`;
            await userRef.set({
                uid: u.uid,
                name: u.displayName || userName || "Student",
                nameLower: (u.displayName || userName || "Student").toLowerCase(),
                username: currentUsername,
                usernameLower: currentUsername.toLowerCase(),
                bio: currentBio,
                photoURL: getSafeAvatar(userAvatarUrl)
            }, { merge: true });
        }

        if (data.bio) currentBio = data.bio;
        if (data.photoURL) userAvatarUrl = getSafeAvatar(data.photoURL);
        localStorage.setItem("username", currentUsername);
        localStorage.setItem("userBio", currentBio);
        localStorage.setItem("userAvatarUrl", userAvatarUrl);

        syncEditProfileInputs();
        if (typeof listenIncomingRealtimeChats === "function") {
            listenIncomingRealtimeChats(u.uid);
        }
    } catch (e) {}
}

async function saveUserProfileChanges() {
    const uInp = document.getElementById("profileEditUsername");
    const nInp = document.getElementById("profileEditName");
    const bInp = document.getElementById("profileEditBio");
    const hint = document.getElementById("usernameStatusHint");
    const saveBtn = document.getElementById("profileSaveBtn");

    let rawU = (uInp?.value || "").trim().toLowerCase().replace(/^@/, "").replace(/[^a-z0-9_.]/g, "");
    let newName = (nInp?.value || "").trim() || userName;
    let newBio = (bInp?.value || "").trim() || currentBio;

    if (rawU.length < 3 || rawU === "user" || rawU === "friend") {
        if (hint) {
            hint.style.color = "#ef4444";
            hint.innerText = "Please choose a valid unique username (min 3 chars).";
        }
        return;
    }

    const formattedUsername = `@${rawU}`;
    try {
        if (saveBtn) { saveBtn.disabled = true; saveBtn.innerText = "Saving..."; }
        if (db && auth?.currentUser) {
            const q = await db.collection("users").where("usernameLower", "==", formattedUsername.toLowerCase()).get();
            let isTaken = false;
            q.forEach(doc => { if (doc.id !== auth.currentUser.uid) isTaken = true; });
            if (isTaken) {
                if (hint) {
                    hint.style.color = "#ef4444";
                    hint.innerText = `❌ ${formattedUsername} is already taken!`;
                }
                return;
            }
            await db.collection("users").doc(auth.currentUser.uid).set({
                name: newName,
                nameLower: newName.toLowerCase(),
                username: formattedUsername,
                usernameLower: formattedUsername.toLowerCase(),
                bio: newBio,
                photoURL: getSafeAvatar(userAvatarUrl)
            }, { merge: true });
        }

        currentUsername = formattedUsername;
        userName = newName;
        currentBio = newBio;
        localStorage.setItem("username", currentUsername);
        localStorage.setItem("userName", userName);
        localStorage.setItem("userBio", currentBio);

        if (hint) hint.innerText = "";
        syncEditProfileInputs();
        updateProfileUI();
        showChatsHome();
    } catch (err) {
        console.error("Save profile error:", err);
    } finally {
        if (saveBtn) { saveBtn.disabled = false; saveBtn.innerText = "Save"; }
    }
}

async function updateMyPresenceStatus(isOnlineNow) {
    if (!db || !auth?.currentUser) return;
    const nowMs = Date.now();
    const nowTime = new Date(nowMs).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    try {
        await db.collection("users").doc(auth.currentUser.uid).set({
            isOnline: isOnlineNow,
            lastSeenLabel: nowTime,
            lastActiveAtMs: nowMs,
            lastActiveAt: firebase.firestore.FieldValue.serverTimestamp()
        }, { merge: true });
    } catch (e) {}
}

function startPresenceHeartbeat() {
    stopPresenceHeartbeat();
    presenceHeartbeatTimer = setInterval(() => {
        if (!document.hidden && auth?.currentUser) updateMyPresenceStatus(true);
    }, 45000);
}

function stopPresenceHeartbeat() {
    if (presenceHeartbeatTimer) {
        clearInterval(presenceHeartbeatTimer);
        presenceHeartbeatTimer = null;
    }
}

function requestNotificationPermissionSafely() {
    if ("Notification" in window && Notification.permission === "default") {
        Notification.requestPermission().catch(() => {});
    }
}

let inAppNotifTimeout = null;
function showZorenoIncomingNotification(friendUid, senderName, senderAvatar, senderUsername, messageText) {
    if (blockedUsersMap[friendUid]) return;
    const banner = document.getElementById("zorenoInAppNotifBanner");
    const nameEl = document.getElementById("znotifSenderName");
    const msgEl = document.getElementById("znotifMsgPreview");
    const avatarEl = document.getElementById("znotifSenderAvatar");

    if (banner && nameEl && msgEl && avatarEl) {
        nameEl.textContent = senderName || "Friend";
        msgEl.textContent = messageText || "Sent you a message";
        avatarEl.src = getSafeAvatar(senderAvatar);
        banner.onclick = () => {
            banner.classList.remove("show");
            openChatWithUser(friendUid, senderName, getSafeAvatar(senderAvatar), senderUsername);
        };
        banner.classList.add("show");
        clearTimeout(inAppNotifTimeout);
        inAppNotifTimeout = setTimeout(() => banner.classList.remove("show"), 4500);
    }

    if (window.AndroidNotif?.showNotification) {
        try { window.AndroidNotif.showNotification(senderName || "Zoreno Message", messageText || "New message received"); } catch (e) {}
    }
}


