function syncFriendProfileViewDOM() {
    if (!currentChatUserMeta) return;
    const fpGrid = document.querySelector("#friendProfileScreen .fp-actions-grid");
    if (fpGrid && !document.getElementById("fpMakeFriendBtn")) {
        const fBtn = document.createElement("button");
        fBtn.type = "button";
        fBtn.id = "fpMakeFriendBtn";
        fBtn.className = "fp-action-box fp-friend-btn";
        fBtn.onclick = () => handleMakeAsFriendClick();
        fpGrid.appendChild(fBtn);
    }
    syncMakeFriendButtonUI();

    const cleanHandle = (currentChatUserMeta.username || "@student").replace(/^@/, "");
    const fullHandle = `@${cleanHandle}`;
    const bioStr = currentChatUserMeta.bio || "Student | Exploring new things | Keep learning.";
    const pres = formatPresenceStatusText(currentChatUserMeta.isOnline, currentChatUserMeta.lastActiveAtMs, currentChatUserMeta.lastSeenLabel);
    const dotColor = pres.online ? "#10b981" : "#94a3b8";

    const avImg = document.getElementById("fpAvatarImg");
    const avDot = document.getElementById("fpAvatarDot");
    const fName = document.getElementById("fpFullName");
    const uSub = document.getElementById("fpUsernameSub");
    const pillDot = document.getElementById("fpPillDot");
    const pillTxt = document.getElementById("fpPillText");

    if (avImg) avImg.src = getSafeAvatar(currentChatUserMeta.avatar);
    if (avDot) avDot.style.background = dotColor;
    if (fName) fName.textContent = currentChatUserMeta.name || "Student";
    if (uSub) uSub.textContent = fullHandle;
    if (pillDot) pillDot.style.background = dotColor;
    if (pillTxt) pillTxt.textContent = pres.text;

    const cUser = document.getElementById("fpCardUsername");
    const cName = document.getElementById("fpCardName");
    const cBio = document.getElementById("fpCardBio");
    const cBioCount = document.getElementById("fpBioCount");
    const bDot = document.getElementById("fpBottomStatusDot");
    const bTxt = document.getElementById("fpBottomStatusText");

    if (cUser) cUser.textContent = cleanHandle;
    if (cName) cName.textContent = currentChatUserMeta.name || "Student";
    if (cBio) cBio.textContent = bioStr;
    if (cBioCount) cBioCount.textContent = `${bioStr.length}/150`;
    if (bDot) bDot.style.background = dotColor;
    if (bTxt) bTxt.textContent = pres.text;
}

async function copyFriendUsername() {
    if (!currentChatUserMeta) return;
    const handle = (currentChatUserMeta.username || "").replace(/^@/, "");
    try {
        await navigator.clipboard.writeText(handle);
        showCompactGlassToast("✓", `@${handle} copied`);
    } catch (e) {}
}

function renderDmHeaderStatus() {
    const statusEl = document.getElementById("activeChatStatus");
    const dotEl = document.getElementById("activeChatOnlineDot");
    if (!statusEl || !currentChatUserMeta || currentChatIsGroup) return;

    const uHandle = escapeHtml(currentChatUserMeta.username || "@student");
    if (isFriendCurrentlyTyping) {
        statusEl.innerHTML = `${uHandle} • <span style="color:#10b981; font-weight:800;">typing...</span>`;
        if (dotEl) dotEl.style.background = "#10b981";
        return;
    }

    const pres = formatPresenceStatusText(currentChatUserMeta.isOnline, currentChatUserMeta.lastActiveAtMs, currentChatUserMeta.lastSeenLabel);
    if (pres.online) {
        statusEl.innerHTML = `${uHandle} • <span style="color:#10b981; font-weight:700;">Online</span>`;
        if (dotEl) dotEl.style.background = "#10b981";
    } else {
        statusEl.innerHTML = `${uHandle} • <span style="color:#94a3b8;">${escapeHtml(pres.text)}</span>`;
        if (dotEl) dotEl.style.background = "#94a3b8";
    }
}

function handleLiveTypingInput() {
    if (!db || !auth?.currentUser || !currentChatUserId || currentChatIsGroup) return;
    const myUid = auth.currentUser.uid;
    const chatId = myUid < currentChatUserId ? `${myUid}_${currentChatUserId}` : `${currentChatUserId}_${myUid}`;

    db.collection("chats").doc(chatId).set({ [`typing_${myUid}`]: true }, { merge: true }).catch(() => {});
    clearTimeout(typingTimeoutTimer);
    typingTimeoutTimer = setTimeout(() => {
        db.collection("chats").doc(chatId).set({ [`typing_${myUid}`]: false }, { merge: true }).catch(() => {});
    }, 1500);
}

// Friend Request / Cancel Request / Unfriend Lifecycle
function listenMyFriendsAndRequests(myUid) {
    if (!db || !myUid) return;
    if (friendReqsUnsub) friendReqsUnsub();

    db.collection("users").doc(myUid).onSnapshot(doc => {
        if (!doc.exists) return;
        const d = doc.data() || {};
        if (d.friendsMap && typeof d.friendsMap === "object") {
            myFriendsMap = d.friendsMap;
            localStorage.setItem("zorenoFriendsMap", JSON.stringify(myFriendsMap));
            syncMakeFriendButtonUI();
            scheduleRenderSavedDmChats();
        }
    });

    friendReqsUnsub = db.collection("friendRequests")
        .where("toUid", "==", myUid)
        .where("status", "==", "pending")
        .onSnapshot(snap => {
            incomingFriendReqs = snap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            scheduleRenderSavedDmChats();
            syncMakeFriendButtonUI();
        });
}

async function checkPendingOutgoingRequestForCurrentChat() {
    if (!db || !auth?.currentUser || !currentChatUserId || currentChatIsGroup) return;
    try {
        const snap = await db.collection("friendRequests")
            .where("fromUid", "==", auth.currentUser.uid)
            .where("toUid", "==", currentChatUserId)
            .where("status", "==", "pending").get();
        if (!snap.empty) outgoingFriendReqsMap[currentChatUserId] = snap.docs[0].id;
        else delete outgoingFriendReqsMap[currentChatUserId];
        syncMakeFriendButtonUI();
    } catch (e) {}
}

function syncMakeFriendButtonUI() {
    const fpBtn = document.getElementById("fpMakeFriendBtn");
    const menuBtn = document.getElementById("dmFriendActionMenuBtn");
    if (!currentChatUserId || currentChatIsGroup) return;
    const uid = currentChatUserId;

    if (myFriendsMap && myFriendsMap[uid]) {
        if (fpBtn) fpBtn.innerHTML = `<i class="fa-solid fa-user-minus" style="color:#ef4444;"></i><span style="color:#ef4444;">Unfriend</span>`;
        if (menuBtn) menuBtn.innerHTML = `<i class="fa-solid fa-user-minus" style="color:#ef4444;"></i> Unfriend`;
    } else if (outgoingFriendReqsMap && outgoingFriendReqsMap[uid]) {
        if (fpBtn) fpBtn.innerHTML = `<i class="fa-solid fa-xmark" style="color:#f59e0b;"></i><span style="color:#f59e0b;">Cancel Req</span>`;
        if (menuBtn) menuBtn.innerHTML = `<i class="fa-solid fa-xmark" style="color:#f59e0b;"></i> Cancel Invitation`;
    } else {
        if (fpBtn) fpBtn.innerHTML = `<i class="fa-solid fa-user-plus" style="color:#10b981;"></i><span style="color:#10b981;">Add Friend</span>`;
        if (menuBtn) menuBtn.innerHTML = `<i class="fa-solid fa-user-plus" style="color:#10b981;"></i> Add as Friend`;
    }
}

async function handleMakeAsFriendClick() {
    closeAllDropdownMenus();
    if (!currentChatUserId || currentChatIsGroup || !db || !auth?.currentUser) return;
    const myUid = auth.currentUser.uid;
    const targetUid = currentChatUserId;
    const targetName = currentChatUserMeta?.name || "User";

    if (myFriendsMap && myFriendsMap[targetUid]) {
        delete myFriendsMap[targetUid];
        localStorage.setItem("zorenoFriendsMap", JSON.stringify(myFriendsMap));
        syncMakeFriendButtonUI();
        scheduleRenderSavedDmChats();
        try {
            await db.collection("users").doc(myUid).set({ friendsMap: { [targetUid]: firebase.firestore.FieldValue.delete() } }, { merge: true });
            await db.collection("users").doc(targetUid).set({ friendsMap: { [myUid]: firebase.firestore.FieldValue.delete() } }, { merge: true });
        } catch (e) {}
        showCompactGlassToast("✓", `Unfriended ${targetName}`);
        return;
    }

    if (outgoingFriendReqsMap && outgoingFriendReqsMap[targetUid]) {
        const reqDocId = outgoingFriendReqsMap[targetUid];
        delete outgoingFriendReqsMap[targetUid];
        syncMakeFriendButtonUI();
        try {
            if (typeof reqDocId === "string" && reqDocId.length > 3) {
                await db.collection("friendRequests").doc(reqDocId).delete();
            } else {
                const snap = await db.collection("friendRequests").where("fromUid", "==", myUid).where("toUid", "==", targetUid).get();
                snap.forEach(d => d.ref.delete());
            }
        } catch (e) {}
        showCompactGlassToast("✕", "Friend request cancelled");
        return;
    }

    try {
        outgoingFriendReqsMap[targetUid] = true;
        syncMakeFriendButtonUI();
        const docRef = await db.collection("friendRequests").add({
            fromUid: myUid,
            fromName: userName || "Student",
            fromUsername: currentUsername || "@student",
            fromAvatar: getSafeAvatar(userAvatarUrl),
            toUid: targetUid,
            status: "pending",
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });
        outgoingFriendReqsMap[targetUid] = docRef.id;
        syncMakeFriendButtonUI();
        showCompactGlassToast("✓", `Request sent to ${targetName}`);
    } catch (e) {}
}

async function respondToFriendRequest(reqDocId, fromUid, fromName, accept) {
    if (!db || !auth?.currentUser) return;
    const myUid = auth.currentUser.uid;
    try {
        if (accept) {
            myFriendsMap[fromUid] = true;
            localStorage.setItem("zorenoFriendsMap", JSON.stringify(myFriendsMap));
            await db.collection("users").doc(myUid).set({ friendsMap: { [fromUid]: true } }, { merge: true });
            await db.collection("users").doc(fromUid).set({ friendsMap: { [myUid]: true } }, { merge: true });
        }
        await db.collection("friendRequests").doc(reqDocId).update({ status: accept ? "accepted" : "declined" });
        if (accept) showCompactGlassToast("🤝", `You and ${fromName || "friend"} are now connected!`);
        scheduleRenderSavedDmChats();
    } catch (e) {}
}

// ================= DM MESSAGE RENDERING (FRAMELESS 3D STICKERS, AGREEMENT CARDS, QUOTES) =================
function renderDmMessagesListToDOM(chatId, messagesArray, myUid) {
    const msgContainer = document.getElementById("activeChatMessages");
    if (!msgContainer) return;

    const clearedAt = chatClearedAtMap[chatId] || 0;
    const visibleMsgs = messagesArray.filter(m => {
        if (deletedMsgsMap[m.id]) return false;
        if (clearedAt && (m.timestampMs || 0) <= clearedAt) return false;
        return true;
    });

    const firstName = escapeHtml((currentChatUserMeta?.name || "Friend").split(" ")[0]);

    // Cute Waving 3D Character on Empty Chat (Replaces Ugly Robot - 33537 Fix!)
    if (visibleMsgs.length === 0) {
        msgContainer.innerHTML = `
            <div class="zoreno-toy-empty-card" onclick="sendAnimated3DStickerInChat('1f44b', 'Wave Hi')">
                <div style="font-size:15.5px; font-weight:800; margin-bottom:4px;">No messages here yet...</div>
                <div style="font-size:12.5px; opacity:0.8; font-weight:500; line-height:1.4; margin-bottom:10px;">
                    Send a message or tap below to wave hello to ${firstName}!
                </div>
                <div class="zoreno-toy-mascot-stage" style="height:105px;">
                    <img src="https://fonts.gstatic.com/s/e/notoemoji/latest/1f970/512.gif" alt="Say Hi" style="width:92px; height:92px; object-fit:contain; filter:drop-shadow(0 10px 20px rgba(124,58,237,0.28));">
                </div>
                <div style="display:inline-flex; align-items:center; gap:6px; background:linear-gradient(135deg,#2563eb,#7c3aed); color:#ffffff; font-size:12px; font-weight:800; padding:7px 16px; border-radius:999px; margin-top:4px; box-shadow:0 6px 16px rgba(124,58,237,0.3);">
                    <span>👋 Tap to Send Animated Greeting</span>
                </div>
            </div>
        `;
        return;
    }

    const friendDp = escapeHtml(getSafeAvatar(currentChatUserMeta?.avatar));
    const fragment = document.createDocumentFragment();

    visibleMsgs.forEach(d => {
        const isMe = d.senderId === myUid;
        let rawText = String(d.text || "").trim();

        // 1. Check Expiry Timer Metadata [[EXP:timestamp]]
        let expiryBadgeHtml = "";
        const expMatch = rawText.match(/^\[\[EXP:(\d+)\]\]\s*([\s\S]*)$/);
        if (expMatch) {
            const expMs = parseInt(expMatch[1], 10);
            rawText = expMatch[2].trim();
            if (Date.now() >= expMs) {
                if (db && chatId && d.id) {
                    const col = currentChatIsGroup ? "groups" : "chats";
                    db.collection(col).doc(chatId).collection("messages").doc(d.id).delete().catch(() => {});
                }
                return;
            }
            const minsLeft = Math.max(1, Math.ceil((expMs - Date.now()) / 60000));
            expiryBadgeHtml = `<span class="zoreno-expiry-pill">⏱️ ${minsLeft}m</span> `;
        }

        // 2. Check Frameless 3D Animated Sticker [[ANIM3D:code|name]] (NO YELLOW BUBBLE BOX - 33538 & 33539 Fix!)
        const animMatch = rawText.match(/^\[\[ANIM3D:([^|]+)\|([^\]]+)\]\]$/);
        const isStickerOnly = Boolean(animMatch && !d.imageData);

        // 3. Check Quoted Reply [[REPLY:Sender|Quote]]
        let quotedBoxHtml = "";
        const replyMatch = rawText.match(/^\[\[REPLY:([^|]+)\|([^\]]+)\]\]\s*([\s\S]*)$/);
        if (replyMatch) {
            quotedBoxHtml = `
                <div class="zoreno-quoted-msg-box">
                    <span class="zoreno-quoted-sender">${escapeHtml(replyMatch[1].trim())}</span>
                    <span class="zoreno-quoted-snippet">${escapeHtml(replyMatch[2].trim())}</span>
                </div>
            `;
            rawText = replyMatch[3].trim();
        }

        // 4. Check Shared Agreement Card [[MEMORY:Title|Time|Loc|Status]]
        let innerBodyHtml = "";
        const memMatch = rawText.match(/^\[\[MEMORY:([^|]+)\|([^|]+)\|([^|]+)\|([^\]]+)\]\]$/);
        if (isStickerOnly) {
            const [, code, label] = animMatch;
            const gifUrl = `https://fonts.gstatic.com/s/e/notoemoji/latest/${code}/512.gif`;
            innerBodyHtml = `<img src="${gifUrl}" alt="${escapeHtml(label)}" class="zoreno-sent-3d-sticker">`;
        } else if (memMatch) {
            const [, mTitle, mTime, mLoc, mStatus] = memMatch;
            const isConfirmed = mStatus.toLowerCase().includes("confirmed");
            innerBodyHtml = `
                <div class="zoreno-shared-memory-card">
                    <div class="zoreno-memory-badge-top">
                        <span>🤝 AGREEMENT CARD</span>
                        <span style="color:${isConfirmed ? '#10b981' : '#f59e0b'};">${isConfirmed ? '● CONFIRMED' : '● PENDING'}</span>
                    </div>
                    <div class="zoreno-memory-title">${escapeHtml(mTitle)}</div>
                    <div class="zoreno-memory-meta">
                        <div><i class="fa-regular fa-clock"></i> ${escapeHtml(mTime)}</div>
                        <div><i class="fa-solid fa-location-dot"></i> ${escapeHtml(mLoc)}</div>
                        <div style="color:${isConfirmed ? '#10b981' : '#7c3aed'}; font-weight:800; margin-top:4px;">${escapeHtml(mStatus)}</div>
                    </div>
                    <div class="zoreno-memory-actions">
                        <button type="button" class="zoreno-memory-btn" style="background:#10b981; color:#fff;" onclick="event.stopPropagation(); confirmSharedMemoryCardInChat('${escapeHtml(d.id)}', '${escapeHtml(chatId)}', '${escapeHtml(mTitle.replace(/'/g, ""))}', '${escapeHtml(mTime.replace(/'/g, ""))}', '${escapeHtml(mLoc.replace(/'/g, ""))}')">
                            ✓ Confirm Agreement
                        </button>
                    </div>
                </div>
            `;
        } else if (rawText) {
            innerBodyHtml = `${quotedBoxHtml}<div style="${d.imageData ? 'padding:6px 8px 2px;' : ''}">${expiryBadgeHtml}${escapeHtml(rawText)}</div>`;
        }

        const isMediaOnly = Boolean(d.imageData && !rawText);
        let tickIcon = '<i class="fa-solid fa-check" style="color:rgba(255,255,255,0.85); font-size:10px;"></i>';
        if (d.seen) {
            tickIcon = '<i class="fa-solid fa-check-double" style="color:#38bdf8; font-size:11px;"></i>';
        } else if (d.delivered) {
            tickIcon = '<i class="fa-solid fa-check-double" style="color:rgba(255,255,255,0.9); font-size:10px;"></i>';
        }

        const mediaHtml = d.imageData
            ? `<div class="sent-media-grid"><img src="${d.imageData}" class="sent-wide-photo" onclick="event.stopPropagation(); openFullImageModal('${d.imageData}')" alt="Photo"></div>`
            : "";

        const reactionHtml = d.reaction ? `<span class="msg-reaction-badge">${escapeHtml(d.reaction)}</span>` : "";
        const isBookmarked = Boolean(zorenoBookmarksMap[d.id]);
        const bookmarkTagHtml = isBookmarked ? `<div class="zoreno-bookmark-corner-tag"><i class="fa-solid fa-bookmark"></i> Saved</div>` : "";

        const row = document.createElement("div");
        row.className = `msg-row-with-avatar ${isMe ? "right-user" : "left-friend"}`;
        if (d.reaction) row.style.marginBottom = "18px";

        const extraClasses = `${isMediaOnly ? 'media-only-bubble' : ''} ${isStickerOnly ? 'sticker-transparent-bubble' : ''} ${isBookmarked ? 'bookmarked-msg-highlight' : ''}`.trim();

        if (isMe) {
            row.innerHTML = `
                <div class="clean-right-bubble ${extraClasses}" data-msg-id="${escapeHtml(d.id)}" data-chat-id="${escapeHtml(chatId)}" data-raw-text="${escapeHtml(rawText)}">
                    ${bookmarkTagHtml}
                    ${mediaHtml}
                    ${innerBodyHtml}
                    <div class="bubble-meta-time" style="${isStickerOnly ? 'background:rgba(15,23,42,0.55); color:#fff; padding:2px 7px; border-radius:10px;' : ''}">
                        <span>${escapeHtml(d.timeLabel || "Now")}</span>
                        ${tickIcon}
                    </div>
                    ${reactionHtml}
                </div>
            `;
        } else {
            row.innerHTML = `
                <img src="${friendDp}" onerror="this.src='logo.png'" class="msg-side-avatar dm-friend-side-dp" alt="DP" onclick="openFriendProfileScreen()" style="cursor:pointer;">
                <div class="clean-left-bubble ${extraClasses}" data-msg-id="${escapeHtml(d.id)}" data-chat-id="${escapeHtml(chatId)}" data-raw-text="${escapeHtml(rawText)}">
                    ${bookmarkTagHtml}
                    ${mediaHtml}
                    ${innerBodyHtml}
                    <div class="bubble-meta-time">
                        <span>${escapeHtml(d.timeLabel || "Now")}</span>
                    </div>
                    ${reactionHtml}
                </div>
            `;
        }
        fragment.appendChild(row);
    });

    msgContainer.innerHTML = "";
    msgContainer.appendChild(fragment);
    msgContainer.scrollTop = msgContainer.scrollHeight;
    bindCleanOneSecondHoldMenu();
}

function loadMessagesFromFirestore(recipientId) {
    const msgContainer = document.getElementById("activeChatMessages");
    if (!msgContainer) return;

    if (activeMessagesUnsubscribe) {
        activeMessagesUnsubscribe();
        activeMessagesUnsubscribe = null;
    }

    const myUid = auth?.currentUser?.uid || "local";
    const chatId = myUid < recipientId ? `${myUid}_${recipientId}` : `${recipientId}_${myUid}`;
    const cacheKey = `zorenoDmCache_${chatId}`;

    let cachedMsgs = [];
    try { cachedMsgs = JSON.parse(localStorage.getItem(cacheKey) || "[]"); } catch (e) { cachedMsgs = []; }
    renderDmMessagesListToDOM(chatId, cachedMsgs, myUid);

    if (!db || !auth?.currentUser) return;

    activeMessagesUnsubscribe = db.collection("chats").doc(chatId).collection("messages")
        .onSnapshot(snapshot => {
            const docs = snapshot.docs.slice().sort((a, b) => {
                const ta = a.data().timestampMs || a.data().createdAt?.toMillis?.() || 0;
                const tb = b.data().timestampMs || b.data().createdAt?.toMillis?.() || 0;
                return ta - tb;
            });

            const unseenRefs = [];
            const freshList = docs.map(doc => {
                const d = doc.data();
                if (d.senderId !== myUid && !d.seen) unseenRefs.push(doc.ref);
                return {
                    id: doc.id,
                    senderId: d.senderId,
                    text: d.text || "",
                    imageData: d.imageData || "",
                    reaction: d.reaction || "",
                    timeLabel: d.timeLabel || "Now",
                    timestampMs: d.timestampMs || d.createdAt?.toMillis?.() || 0,
                    delivered: true,
                    seen: d.senderId !== myUid ? true : !!d.seen
                };
            });

            try { localStorage.setItem(cacheKey, JSON.stringify(freshList.slice(-60))); } catch (e) {}
            renderDmMessagesListToDOM(chatId, freshList, myUid);
            markDmChatAsRead(recipientId);

            if (unseenRefs.length > 0) {
                const batch = db.batch();
                unseenRefs.forEach(ref => batch.update(ref, { seen: true, delivered: true }));
                batch.commit().catch(() => {});
            }
        });
}

// ================= CENTER-ALIGNED 1-SECOND HOLD MENU (BOOKMARK, REPLACE, DUST DELETE) =================
function closeZorenoHoldMenu() {
    document.getElementById("zorenoActiveHoldMenu")?.remove();
}

function openBookHoldMenuForMessage(touchEvent, opts) {
    closeZorenoHoldMenu();
    const oldDelModal = document.getElementById("deleteMsgModal");
    if (oldDelModal) oldDelModal.style.setProperty("display", "none", "important");
    if (navigator.vibrate) navigator.vibrate(26);

    const wrap = document.createElement("div");
    wrap.id = "zorenoActiveHoldMenu";
    wrap.className = "zoreno-tg-hold-wrap";

    const clientX = touchEvent?.touches?.[0]?.clientX || touchEvent?.clientX || (window.innerWidth / 2);
    const clientY = touchEvent?.touches?.[0]?.clientY || touchEvent?.clientY || (window.innerHeight / 2);

    // Strict Viewport Clamping so Emojis & Menu NEVER Cut Off on the Right Side (33543 Fix!)
    const menuWidth = 236;
    const leftPos = Math.max(14, Math.min(window.innerWidth - menuWidth - 14, clientX - (menuWidth / 2)));
    const topPos = Math.max(54, Math.min(window.innerHeight - 320, clientY - 50));
    wrap.style.left = leftPos + "px";
    wrap.style.top = topPos + "px";

    const tgEmojis = ["❤️", "🙏", "⚡", "👍", "🔥", "😂"];
    const isBookmarked = Boolean(opts.msgId && zorenoBookmarksMap[opts.msgId]);

    const emojiPillHtml = opts.isDm
        ? `<div class="zoreno-tg-emoji-pill" style="width:${menuWidth}px; justify-content:space-between;">
               ${tgEmojis.map(em => `<button type="button" onclick="triggerHoldMenuEmoji('${em}', '${opts.msgId || ""}', '${opts.chatId || ""}')">${em}</button>`).join("")}
           </div>`
        : "";

    wrap.innerHTML = `
        ${emojiPillHtml}
        <div class="zoreno-tg-action-card" style="width:${menuWidth}px;">
            <button type="button" class="zoreno-hold-item" onclick="replyToHoldMenuMessage()">
                <i class="fa-solid fa-reply" style="color:#3b82f6;"></i>
                <span>Reply</span>
            </button>
            ${opts.isDm ? `
            <button type="button" class="zoreno-hold-item" onclick="toggleBookmarkOnHoldMessage()">
                <i class="fa-solid fa-bookmark" style="color:#10b981;"></i>
                <span>${isBookmarked ? "Remove Bookmark" : "Bookmark Message"}</span>
            </button>
            ${opts.isMine ? `
            <button type="button" class="zoreno-hold-item" onclick="startRecallAndReplaceMessage()">
                <i class="fa-solid fa-pen-to-square" style="color:#8b5cf6;"></i>
                <span>Replace Message</span>
            </button>` : ""}
            <button type="button" class="zoreno-hold-item" onclick="openAiSmartReplyDrawerForMessage()">
                <i class="fa-solid fa-wand-magic-sparkles" style="color:#ec4899;"></i>
                <span>AI Smart Reply</span>
            </button>` : ""}
            <button type="button" class="zoreno-hold-item" onclick="copyHoldMenuMessageText()">
                <i class="fa-regular fa-copy" style="color:#0ea5e9;"></i>
                <span>Copy</span>
            </button>
            <button type="button" class="zoreno-hold-item" onclick="openForwardMessageModal()">
                <i class="fa-solid fa-share" style="color:#f59e0b;"></i>
                <span>Forward</span>
            </button>
            <button type="button" class="zoreno-hold-item" style="color:#ef4444;" onclick="executeHoldMenuDelete()">
                <i class="fa-regular fa-trash-can"></i>
                <span>Delete</span>
            </button>
        </div>
    `;

    window._currentHoldMenuMeta = opts;
    document.body.appendChild(wrap);
}

function bindCleanOneSecondHoldMenu() {
    document.querySelectorAll("#chatMessages .clean-right-bubble, #chatMessages .clean-left-bubble").forEach((bubble, i) => {
        bubble.removeAttribute("onclick");
        if (bubble.dataset.cleanHoldBound === "true") return;
        bubble.dataset.cleanHoldBound = "true";

        let t = null;
        bubble.addEventListener("touchstart", (e) => {
            if (e.target.closest("button, a, img.sent-wide-photo, .ai-action-btns-wrap")) return;
            t = setTimeout(() => {
                openBookHoldMenuForMessage(e, {
                    isAi: true,
                    aiIdx: Math.max(0, Math.floor((i - 1) / 2)),
                    text: bubble.innerText.replace(/Zoreno is AI can make mistakes/gi, "").trim(),
                    bubbleEl: bubble
                });
            }, 750);
        }, { passive: true });
        bubble.addEventListener("touchend", () => clearTimeout(t));
        bubble.addEventListener("touchmove", () => clearTimeout(t));
        bubble.addEventListener("touchcancel", () => clearTimeout(t));
    });

    document.querySelectorAll("#activeChatMessages .clean-right-bubble, #activeChatMessages .clean-left-bubble").forEach(bubble => {
        bubble.removeAttribute("onclick");
        if (bubble.dataset.cleanHoldBound === "true") return;
        bubble.dataset.cleanHoldBound = "true";

        let t = null;
        bubble.addEventListener("touchstart", (e) => {
            if (e.target.closest("button")) return;
            t = setTimeout(() => {
                openBookHoldMenuForMessage(e, {
                    isDm: true,
                    isMine: bubble.classList.contains("clean-right-bubble"),
                    msgId: bubble.dataset.msgId || "",
                    chatId: bubble.dataset.chatId || "",
                    text: bubble.dataset.rawText || bubble.innerText.replace(/\d{1,2}:\d{2}\s*(?:AM|PM)?/gi, "").trim(),
                    bubbleEl: bubble
                });
            }, 750);
        }, { passive: true });
        bubble.addEventListener("touchend", () => clearTimeout(t));
        bubble.addEventListener("touchmove", () => clearTimeout(t));
        bubble.addEventListener("touchcancel", () => clearTimeout(t));
    });
}

