// Smoke / Dust Particle Disintegration for Both Text Messages & Photos!
function spawnSmokeDustParticlesOnElement(el) {
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const colors = ["#a855f7", "#6366f1", "#38bdf8", "#cbd5e1", "#94a3b8", "#f472b6"];
    for (let i = 0; i < 28; i++) {
        const dot = document.createElement("div");
        dot.className = "zoreno-dust-particle-dot";
        const size = 5 + Math.floor(Math.random() * 8);
        dot.style.width = size + "px";
        dot.style.height = size + "px";
        dot.style.background = colors[i % colors.length];
        dot.style.left = (rect.left + Math.random() * rect.width) + "px";
        dot.style.top = (rect.top + Math.random() * rect.height) + "px";
        dot.style.setProperty("--dx", (Math.random() * 80 - 40).toFixed(0) + "px");
        dot.style.setProperty("--dy", (-30 - Math.random() * 70).toFixed(0) + "px");
        document.body.appendChild(dot);
        setTimeout(() => dot.remove(), 800);
    }
    el.classList.add("msg-smoke-dust-out");
}

window.executeHoldMenuDelete = async function () {
    const meta = window._currentHoldMenuMeta;
    closeZorenoHoldMenu();
    if (!meta) return;

    const targetBubble = meta.bubbleEl || (meta.msgId ? document.querySelector(`#activeChatMessages [data-msg-id="${meta.msgId}"]`) : null);
    if (targetBubble) {
        spawnSmokeDustParticlesOnElement(targetBubble);
        await new Promise(r => setTimeout(r, 620));
    }

    if (meta.isAi) {
        aiMsgIndexToDelete = meta.aiIdx;
        msgToDeleteId = null;
        msgToDeleteChatId = null;
        if (aiMsgIndexToDelete !== null && aiChatMessagesList[aiMsgIndexToDelete]) {
            const removed = aiChatMessagesList.splice(aiMsgIndexToDelete, 1)[0];
            localStorage.setItem("zorenoAiChatStream", JSON.stringify(aiChatMessagesList));
            renderAiChatStream();
            if (db && auth?.currentUser && removed?.timestampMs) {
                try {
                    const snap = await db.collection("users").doc(auth.currentUser.uid).collection("chats").where("timestampMs", "==", removed.timestampMs).get();
                    snap.forEach(d => d.ref.delete());
                } catch (e) {}
            }
        }
    } else if (meta.msgId && meta.chatId) {
        deletedMsgsMap[meta.msgId] = true;
        localStorage.setItem("zorenoDeletedMsgsMap", JSON.stringify(deletedMsgsMap));
        targetBubble?.closest(".msg-row-with-avatar")?.remove();
        if (db) {
            const col = currentChatIsGroup ? "groups" : "chats";
            try { await db.collection(col).doc(meta.chatId).collection("messages").doc(meta.msgId).delete(); } catch (e) {}
        }
    }
    showCompactGlassToast("✨", "Dissolved into dust");
};

