// ================= LIVE CLOCK & GEMINI API CALLER =================
async function buildLiveContextForAI(userText) {
    const now = new Date();
    let liveContext = `\n[LIVE REAL-TIME CLOCK]: Date: ${now.toLocaleDateString("en-IN", { weekday: "long", day: "numeric", month: "long", year: "numeric" })} | Time: ${now.toLocaleTimeString("en-IN")}. Current year is ${now.getFullYear()}.`;
    return liveContext;
}

async function callGeminiWithFallback(payloadBody, abortSignal) {
    let lastError = null;
    const groundedPayload = { ...payloadBody, tools: [{ googleSearch: {} }] };

    for (let attempt = 1; attempt <= 3; attempt++) {
        const bodyToSend = attempt === 1 ? groundedPayload : payloadBody;
        try {
            const response = await fetch(
                `https://generativelanguage.googleapis.com/v1beta/models/${ZORENO_AI_MODEL}:generateContent?key=${GEMINI_API_KEY}`,
                { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(bodyToSend), signal: abortSignal }
            );
            const data = await response.json();
            if (data.error) {
                lastError = new Error(data.error.message || "API Error");
                if (attempt === 1) continue;
                await new Promise(r => setTimeout(r, 1200 * attempt));
                continue;
            }
            const parts = data?.candidates?.[0]?.content?.parts || [];
            const fullText = parts.map(p => p.text || "").join("").trim();
            if (fullText) return fullText;
        } catch (err) {
            if (err.name === "AbortError") throw err;
            lastError = err;
            if (attempt < 3) await new Promise(r => setTimeout(r, 1000));
        }
    }
    throw lastError || new Error("Please try again in a moment.");
}

let isAiGenerating = false;
let currentAiAbortController = null;

function setSendBtnStopMode(isGenerating) {
    const sendBtn = document.getElementById("sendBtn");
    if (!sendBtn) return;
    sendBtn.disabled = false;
    if (isGenerating) {
        sendBtn.innerHTML = '<i class="fa-solid fa-stop"></i>';
        sendBtn.style.background = "linear-gradient(135deg, #ef4444, #dc2626)";
    } else {
        sendBtn.innerHTML = '<i class="fa-solid fa-paper-plane"></i>';
        sendBtn.style.background = "";
    }
}

async function sendMessage() {
    if (isAiGenerating && currentAiAbortController) {
        currentAiAbortController.abort();
        return;
    }

    const input = document.getElementById("userInput");
    const chatMessages = document.getElementById("chatMessages");
    if (!input || !chatMessages) return;

    if (pendingAiAttachments.some(a => a.loading)) {
        showCompactGlassToast("⏳", "Photo is still loading...");
        return;
    }

    let text = input.value.trim();
    const attachedImages = pendingAiAttachments.map(a => a.dataUrl).filter(Boolean).slice(0, 2);
    if (!text && attachedImages.length === 0) return;

    const usedToday = getLocalDailyAiCount();
    const todayLimit = userTier === 2 ? 90 : userTier === 1 ? 50 : getLocalDailyAiLimit();

    if (usedToday >= todayLimit) {
        openZorenoUsageLimitModal();
        return;
    }

    const nowTime = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    const msgIdx = aiChatMessagesList.length;
    input.value = "";
    input.style.height = "auto";
    pendingAiAttachments = [];
    if (typeof renderAiAttachmentPreviewStrip === "function") renderAiAttachmentPreviewStrip();

    const hasImgs = attachedImages.length > 0;
    const isMediaOnly = hasImgs && !text;
    const imgsPreviewHtml = attachedImages.map(src =>
        `<img src="${src}" class="sent-wide-photo" onclick="event.stopPropagation(); openFullImageModal('${src}')" alt="Uploaded">`
    ).join("");

    chatMessages.insertAdjacentHTML("beforeend", `
        <div class="msg-row-with-avatar right-user">
            <div class="clean-right-bubble ${isMediaOnly ? 'media-only-bubble' : ''}">
                ${imgsPreviewHtml ? `<div class="sent-media-grid">${imgsPreviewHtml}</div>` : ""}
                ${text ? `<div style="${hasImgs ? 'padding:6px 8px 2px;' : ''}">${escapeHtml(text)}</div>` : ""}
                <div class="bubble-meta-time">
                    <span>${nowTime}</span>
                    <i class="fa-solid fa-check-double"></i>
                </div>
            </div>
        </div>
    `);

    const guardrailCheck = checkQueryGuardrails(text);
    if (guardrailCheck.blocked) {
        await saveChatToFirebase(text, guardrailCheck.reply, nowTime, attachedImages);
        renderAiChatStream();
        return;
    }

    const thinkingId = "zorenoThinking_" + Date.now();
    chatMessages.insertAdjacentHTML("beforeend", `
        <div class="msg-row-with-avatar" id="${thinkingId}">
            <img src="logo.png" class="ai-logo-avatar" onerror="this.src='default_avatar.png'" alt="Zoreno">
            <div class="clean-left-bubble" style="padding:10px 16px!important; border-radius:22px!important;">
                <div style="display:flex; align-items:center; gap:10px; color:#7c3aed; font-weight:600; font-size:13.5px;">
                    <span>Zoreno is thinking</span>
                    <div class="thinking-dots"><span></span><span></span><span></span></div>
                </div>
            </div>
        </div>
    `);
    scrollToBottom();

    isAiGenerating = true;
    currentAiAbortController = new AbortController();
    setSendBtnStopMode(true);

    try {
        const recentHistory = [];
        aiChatMessagesList.slice(-20).forEach(pair => {
            if (pair.user) recentHistory.push({ role: "user", parts: [{ text: pair.user }] });
            if (pair.bot) recentHistory.push({ role: "model", parts: [{ text: pair.bot }] });
        });

        const currentParts = [];
        attachedImages.forEach(dataUrl => {
            const base64Data = dataUrl.split(",")[1];
            if (base64Data) currentParts.push({ inlineData: { mimeType: "image/jpeg", data: base64Data } });
        });
        currentParts.push({ text: text || "Please explain this image." });

        const dynamicLiveInfo = await buildLiveContextForAI(text);
        const payloadBody = {
            systemInstruction: { parts: [{ text: SYSTEM_INSTRUCTION + dynamicLiveInfo }] },
            contents: [...recentHistory, { role: "user", parts: currentParts }],
            generationConfig: { maxOutputTokens: 3000, temperature: 0.5 }
        };

        const replyText = await callGeminiWithFallback(payloadBody, currentAiAbortController.signal);
        incrementLocalDailyAiCount();
        await saveChatToFirebase(text, replyText, nowTime, attachedImages);
        renderAiChatStream();
    } catch (err) {
        const thinkingRow = document.getElementById(thinkingId);
        if (err.name === "AbortError") {
            await saveChatToFirebase(text, "⏹️ Response stopped by user.", nowTime, attachedImages);
            renderAiChatStream();
        } else if (thinkingRow) {
            thinkingRow.innerHTML = `<img src="logo.png" class="ai-logo-avatar" alt="Zoreno"><div class="clean-left-bubble"><span style="color:#ef4444; font-weight:600;">⚠️ ${escapeHtml(err.message)}</span></div>`;
        }
    } finally {
        isAiGenerating = false;
        currentAiAbortController = null;
        setSendBtnStopMode(false);
        scrollToBottom();
    }
}

async function saveChatToFirebase(userText, botText, timeLabel, imagesList = []) {
    const tLabel = timeLabel || new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    const item = { user: userText || "", bot: botText || "", images: (imagesList || []).slice(0, 2), timeLabel: tLabel, timestampMs: Date.now() };
    aiChatMessagesList.push(item);
    if (aiChatMessagesList.length > 40) aiChatMessagesList = aiChatMessagesList.slice(-40);
    try { localStorage.setItem("zorenoAiChatStream", JSON.stringify(aiChatMessagesList)); } catch (e) {}

    if (db && auth?.currentUser) {
        db.collection("users").doc(auth.currentUser.uid).collection("chats").add({
            user: userText || "", bot: botText || "", timeLabel: tLabel, timestampMs: item.timestampMs, createdAt: firebase.firestore.FieldValue.serverTimestamp()
        }).catch(() => {});
    }
}

async function loadUserChatsFromFirebase() {
    if (!db || !auth?.currentUser) return;
    try {
        const snap = await db.collection("users").doc(auth.currentUser.uid).collection("chats").orderBy("timestampMs", "asc").limitToLast(40).get();
        if (!snap.empty) {
            aiChatMessagesList = [];
            snap.forEach(doc => {
                const d = doc.data();
                aiChatMessagesList.push({ user: d.user || "", bot: d.bot || "", timeLabel: d.timeLabel || "", timestampMs: d.timestampMs || 0 });
            });
            localStorage.setItem("zorenoAiChatStream", JSON.stringify(aiChatMessagesList));
            renderAiChatStream();
        }
    } catch (e) {}
}

function clearAllChatHistory() {
    closeAllDropdownMenus();
    aiChatMessagesList = [];
    localStorage.removeItem("zorenoAiChatStream");
    renderAiChatStream();
    if (db && auth?.currentUser) {
        db.collection("users").doc(auth.currentUser.uid).collection("chats").get().then(snap => {
            const batch = db.batch();
            snap.forEach(d => batch.delete(d.ref));
            batch.commit();
        }).catch(() => {});
    }
    showCompactGlassToast("🗑️", "AI conversation cleared");
}

function clearCurrentAiChat() { clearAllChatHistory(); }

function scrollToBottom() {
    const container = document.getElementById("chatMessages");
    if (container) container.scrollTo({ top: container.scrollHeight, behavior: "smooth" });
}

