const FOCUS_TRACKS = [
    { title: "Rain Storm", icon: "fa-cloud-showers-heavy", file: "sounds/rain.mp3", cover: "https://images.unsplash.com/photo-1519692933481-e162a57d6721?w=300" },
    { title: "Deep Lo-Fi", icon: "fa-music", file: "sounds/lofi.mp3", cover: "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=300" },
    { title: "Forest Birds", icon: "fa-dove", file: "sounds/birds.mp3", cover: "https://images.unsplash.com/photo-1448375240586-882707db888b?w=300" },
    { title: "Ocean Waves", icon: "fa-water", file: "sounds/ocean.mp3", cover: "https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=300" },
    { title: "Cafe Ambient", icon: "fa-mug-saucer", file: "sounds/cafe.mp3", cover: "https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?w=300" }
];

let currentTrackIndex = 0;
let focusAudio = new Audio();
focusAudio.loop = true;
let isMusicPlaying = false;

function selectMusicTrack(index) {
    currentTrackIndex = index;
    const track = FOCUS_TRACKS[index];
    const titleEl = document.getElementById("currentTrackTitle");
    const coverEl = document.getElementById("currentTrackCover");
    if (titleEl) titleEl.innerText = track.title;
    if (coverEl) coverEl.src = track.cover;
    focusAudio.src = track.file;
    focusAudio.currentTime = 0;
    playFocusMusic();
}

function playFocusMusic() { focusAudio.play().then(() => { isMusicPlaying = true; updatePlayerUIState(true); }).catch(() => {}); }
function pauseFocusMusic() { focusAudio.pause(); isMusicPlaying = false; updatePlayerUIState(false); }
function toggleFocusMusicPlay() { if (isMusicPlaying) pauseFocusMusic(); else playFocusMusic(); }
function playNextTrack() { currentTrackIndex = (currentTrackIndex + 1) % FOCUS_TRACKS.length; selectMusicTrack(currentTrackIndex); }
function playPreviousTrack() { currentTrackIndex = (currentTrackIndex - 1 + FOCUS_TRACKS.length) % FOCUS_TRACKS.length; selectMusicTrack(currentTrackIndex); }

function updatePlayerUIState(playing) {
    const playIcon = document.getElementById("musicPlayIcon");
    const visualizer = document.getElementById("musicWaveVisualizer");
    if (playIcon) playIcon.className = playing ? "fa-solid fa-pause" : "fa-solid fa-play";
    if (playing) visualizer?.classList.add("playing"); else visualizer?.classList.remove("playing");
}

focusAudio.ontimeupdate = () => {
    const current = focusAudio.currentTime || 0;
    const duration = focusAudio.duration || 30;
    const elapsedEl = document.getElementById("musicTimeElapsed");
    const durEl = document.getElementById("musicTimeDuration");
    if (elapsedEl) elapsedEl.innerText = `${String(Math.floor(current / 60)).padStart(2, "0")}:${String(Math.floor(current % 60)).padStart(2, "0")}`;
    if (durEl) durEl.innerText = `${String(Math.floor(duration / 60)).padStart(2, "0")}:${String(Math.floor(duration % 60)).padStart(2, "0")}`;
    const percent = (current / duration) * 100;
    const fill = document.getElementById("musicProgressFill");
    const knob = document.getElementById("musicProgressKnob");
    if (fill) fill.style.width = `${percent}%`;
    if (knob) knob.style.left = `${percent}%`;
};

function handleMusicSeek(e) {
    const rail = document.querySelector(".music-progress-rail");
    if (!rail) return;
    const rect = rail.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const offsetX = Math.max(0, Math.min(rect.width, clientX - rect.left));
    focusAudio.currentTime = (offsetX / rect.width) * (focusAudio.duration || 30);
}

function seekMusicByClick(e) { handleMusicSeek(e); }

