async function triggerGoogleSignIn() {
    if (window.ZorenoGoogleAuth && typeof window.ZorenoGoogleAuth.signIn === "function") {
        window.ZorenoGoogleAuth.signIn();
        return;
    }
    try {
        await initFirebase();
        const provider = new firebase.auth.GoogleAuthProvider();
        provider.setCustomParameters({ prompt: "select_account" });
        const res = await auth.signInWithPopup(provider);
        if (res.user) {
            localStorage.setItem("zorenoSavedAuthEmail", res.user.email || "");
            document.getElementById("authScreen")?.style.setProperty("display", "none", "important");
            showChatsHome();
        }
    } catch (err) {
        try {
            const provider = new firebase.auth.GoogleAuthProvider();
            await auth.signInWithRedirect(provider);
        } catch (e2) {
            showCustomAlert("Google Sign-In", "Please use Email & Password or try again.");
        }
    }
}

