// ================= SEND REALTIME DM & GROUP MESSAGES =================
async function sendRealtimeMessage() {
    if (!currentChatIsGroup && (isCurrentChatBlockedByMe || blockedUsersMap[currentChatUserId] || isCurrentChatBlockedByFriend)) {
        syncDmBlockedFooterUI();
        return;
    }

    const input = document.getElementById("activeChatInput");
    let text = (input?.value || "").trim();
    if (!checkPersonalPrivacyBeforeSend(text)) return;

    if (pendingDmAttachmentsList.some(a => a.loading)) {
        showCompactGlassToast("⏳", "Photo is still loading...");
        return;
    }

    const readyPhotos = pendingDmAttachmentsList.filter(a => !a.loading && a.dataUrl);
    const imgData = readyPhotos[0]?.dataUrl || "";
    if ((!text && !imgData) || !currentChatUserId) return;

    if (!db || !auth?.currentUser) return;
    const myUid = auth.currentUser.uid;

    // 1. Handle Live Message Recall & Replace
    if (activeEditReplaceMsgId && activeEditReplaceMsgId.msgId && activeEditReplaceMsgId.chatId) {
        const { msgId, chatId } = activeEditReplaceMsgId;
        cancelActiveReplyOrEdit();
        if (input) { input.value = ""; input.style.height = "auto"; }
        const col = currentChatIsGroup ? "groups" : "chats";
        try {
            await db.collection(col).doc(chatId).collection("messages").doc(msgId).update({
                text: text
            });
            showCompactGlassToast("✓", "Message replaced live!");
        } catch (e) {}
        return;
    }

    // 2. Attach Quoted Reply Header if Replying
    if (activePendingReplyObj && text && !text.startsWith("[[")) {
        text = `[[REPLY:${activePendingReplyObj.sender}|${activePendingReplyObj.quote}]] ${text}`;
        cancelActiveReplyOrEdit();
    }

    // 3. Attach Disappearing Timer Header if Active
    if (activeMessageExpiryMs > 0 && text && !text.startsWith("[[EXP:")) {
        const expAt = Date.now() + activeMessageExpiryMs;
        text = `[[EXP:${expAt}]] ${text}`;
    }

    const safetyCheck = evaluateZorenoSafetyAlgorithm(text);
    if (safetyCheck.action === "block") {
        showCustomAlert("Security Shield 🛡️", `Message blocked (${safetyCheck.reason}).`);
        return;
    }

    const nowMs = Date.now();
    const nowTime = new Date(nowMs).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    if (input) { input.value = ""; input.style.height = "auto"; }
    clearDmAttachment();

    if (currentChatIsGroup) {
        const mutedUntil = currentActiveGroupData?.mutedMap?.[myUid] || 0;
        if (mutedUntil > Date.now()) {
            showCompactGlassToast("🔇", "You are muted in this group");
            return;
        }
        try {
            await db.collection("groups").doc(currentChatUserId).collection("messages").add({
                senderId: myUid,
                senderName: userName || "Student",
                senderAvatar: getSafeAvatar(userAvatarUrl),
                text: text,
                imageData: imgData,
                timeLabel: nowTime,
                timestampMs: nowMs,
                delivered: true,
                seen: true,
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
            });
            const cleanPrev = text.startsWith("[[ANIM3D:") ? "✨ Sticker" : text.startsWith("[[MEMORY:") ? "🤝 Agreement Card" : (text || "📷 Photo");
            await db.collection("groups").doc(currentChatUserId).set({
                lastMessage: `${userName.split(" ")[0]}: ${cleanPrev}`,
                lastMessageAtMs: nowMs,
                timeLabel: nowTime
            }, { merge: true });
        } catch (e) {}
        return;
    }

    const cleanPreviewText = text.startsWith("[[ANIM3D:")
        ? "✨ 3D Sticker"
        : text.startsWith("[[MEMORY:")
            ? "🤝 Agreement Card"
            : text.replace(/^\[\[REPLY:[^\]]+\]\]\s*/, "").replace(/^\[\[EXP:\d+\]\]\s*/, "");

    const previewLabel = cleanPreviewText ? `You: ${cleanPreviewText}` : "You: 📷 Photo";
    if (currentChatUserMeta) {
        upsertRecentDmOnHome(currentChatUserMeta.uid, currentChatUserMeta.name, currentChatUserMeta.avatar, currentChatUserMeta.username, previewLabel, nowTime, 0, nowMs);
    }

    const chatId = myUid < currentChatUserId ? `${myUid}_${currentChatUserId}` : `${currentChatUserId}_${myUid}`;
    try {
        await db.collection("chats").doc(chatId).collection("messages").add({
            senderId: myUid,
            text: text,
            imageData: imgData,
            timeLabel: nowTime,
            timestampMs: nowMs,
            delivered: true,
            seen: false,
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });

        await db.collection("chats").doc(chatId).set({
            participants: [myUid, currentChatUserId],
            lastMessage: cleanPreviewText || "📷 Photo",
            lastSenderId: myUid,
            lastSenderName: userName,
            lastSenderAvatar: getSafeAvatar(userAvatarUrl),
            lastSenderUsername: currentUsername || "@student",
            [`typing_${myUid}`]: false,
            lastMessageAtMs: nowMs,
            updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            timeLabel: nowTime
        }, { merge: true });

        if (readyPhotos.length > 1) {
            await db.collection("chats").doc(chatId).collection("messages").add({
                senderId: myUid,
                text: "",
                imageData: readyPhotos[1].dataUrl,
                timeLabel: nowTime,
                timestampMs: nowMs + 1,
                delivered: true,
                seen: false,
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
            });
        }
    } catch (e) {}
}

// ================= HOME DM LIST & STUDY GROUPS =================
function updateRecentDmMetaOnly(uid, name, avatar, username) {
    const idx = recentDmUsers.findIndex(x => x.uid === uid);
    if (idx < 0) return;
    recentDmUsers[idx].name = name || recentDmUsers[idx].name;
    recentDmUsers[idx].avatar = getSafeAvatar(avatar || recentDmUsers[idx].avatar);
    recentDmUsers[idx].username = username || recentDmUsers[idx].username;
    try { localStorage.setItem("zorenoRecentDms", JSON.stringify(recentDmUsers)); } catch (e) {}
    scheduleRenderSavedDmChats();
}

function upsertRecentDmOnHome(uid, name, avatar, username, lastMsg, timeStr, unreadCount = 0, msgTimestampMs = 0) {
    if (!uid || uid === "arjun_user_id") return;
    const idx = recentDmUsers.findIndex(x => x.uid === uid);
    const prev = idx >= 0 ? recentDmUsers[idx] : {};
    const effectiveMs = msgTimestampMs || prev.lastMessageAtMs || Date.now();

    const entry = {
        uid,
        name: name || prev.name || "Student",
        avatar: getSafeAvatar(avatar || prev.avatar),
        username: username || prev.username || "@student",
        lastMsg: lastMsg || prev.lastMsg || "Tap to chat",
        timeStr: formatSmartTimeLabel(effectiveMs) || timeStr || prev.timeStr || "",
        lastMessageAtMs: effectiveMs,
        unread: typeof unreadCount === "number" ? unreadCount : (prev.unread || 0)
    };

    if (idx >= 0) recentDmUsers.splice(idx, 1);
    recentDmUsers.push(entry);
    recentDmUsers.sort((a, b) => (b.lastMessageAtMs || 0) - (a.lastMessageAtMs || 0));
    localStorage.setItem("zorenoRecentDms", JSON.stringify(recentDmUsers.slice(0, 25)));
    scheduleRenderSavedDmChats();
}

let renderHomeDmTimer = null;
function scheduleRenderSavedDmChats() {
    clearTimeout(renderHomeDmTimer);
    renderHomeDmTimer = setTimeout(renderSavedDmChatsOnHome, 80);
}

function promptDeleteHomeChatProfile(uid, name, event) {
    if (event) event.stopPropagation();
    homeChatUidToDelete = uid;
    const titleEl = document.getElementById("delHomeChatTitle");
    if (titleEl) titleEl.textContent = `Delete ${name || "Chat"}?`;
    const modal = document.getElementById("deleteHomeChatModal");
    if (modal) modal.style.display = "flex";
}

async function confirmDeleteHomeChatAndFirebase() {
    const targetUid = homeChatUidToDelete;
    document.getElementById("deleteHomeChatModal").style.display = "none";
    if (!targetUid) return;

    recentDmUsers = recentDmUsers.filter(u => u.uid !== targetUid);
    localStorage.setItem("zorenoRecentDms", JSON.stringify(recentDmUsers));
    renderSavedDmChatsOnHome();

    if (db && auth?.currentUser) {
        const myUid = auth.currentUser.uid;
        const chatId = myUid < targetUid ? `${myUid}_${targetUid}` : `${targetUid}_${myUid}`;
        localStorage.removeItem(`zorenoDmCache_${chatId}`);
        try {
            const msgSnap = await db.collection("chats").doc(chatId).collection("messages").get();
            const batch = db.batch();
            msgSnap.forEach(doc => batch.delete(doc.ref));
            batch.delete(db.collection("chats").doc(chatId));
            await batch.commit();
        } catch (e) {}
    }
    homeChatUidToDelete = null;
    showCompactGlassToast("🗑️", "Chat deleted permanently");
}

