// ================= INLINE IMAGE PICKERS (AI & FRIEND DM) =================
function openImagePicker() {
    document.getElementById("imageInput")?.click();
}

function openFileOrPdfPicker() {
    document.getElementById("imageInput")?.click();
}

function handleMultipleImages(event) {
    const allSelected = Array.from(event.target.files || []);
    event.target.value = "";
    if (!allSelected.length) return;

    const remainingSlots = 2 - pendingAiAttachments.length;
    if (remainingSlots <= 0) {
        showCompactGlassToast("📷", "Maximum 2 photos allowed at once");
        return;
    }

    allSelected.slice(0, remainingSlots).forEach(file => {
        const tempId = "att_" + Date.now() + "_" + Math.random().toString(36).slice(2, 6);
        pendingAiAttachments.push({ id: tempId, loading: true, dataUrl: "" });
        renderAiAttachmentPreviewStrip();

        const reader = new FileReader();
        reader.onload = function (e) {
            const img = new Image();
            img.onload = function () {
                const canvas = document.createElement("canvas");
                const MAX_DIM = 600;
                let w = img.width, h = img.height;
                if (w > h && w > MAX_DIM) { h = Math.round((h * MAX_DIM) / w); w = MAX_DIM; }
                else if (h >= w && h > MAX_DIM) { w = Math.round((w * MAX_DIM) / h); h = MAX_DIM; }
                canvas.width = w;
                canvas.height = h;
                canvas.getContext("2d").drawImage(img, 0, 0, w, h);
                const compressed = canvas.toDataURL("image/jpeg", 0.62);

                const item = pendingAiAttachments.find(x => x.id === tempId);
                if (item) {
                    item.loading = false;
                    item.dataUrl = compressed;
                    renderAiAttachmentPreviewStrip();
                }
            };
            img.src = e.target.result;
        };
        reader.readAsDataURL(file);
    });
}

function renderAiAttachmentPreviewStrip() {
    const inlineRow = document.getElementById("geminiAiInlineImgRow");
    const pill = document.querySelector("#inputAreaContainer .chat-input-pill");
    if (!inlineRow || !pill) return;

    if (!pendingAiAttachments || pendingAiAttachments.length === 0) {
        inlineRow.innerHTML = "";
        inlineRow.classList.remove("active");
        pill.classList.remove("has-gemini-images");
        return;
    }

    inlineRow.classList.add("active");
    pill.classList.add("has-gemini-images");
    inlineRow.innerHTML = pendingAiAttachments.map(att => {
        if (att.loading) {
            return `<div class="gemini-inline-thumb-card"><div class="gemini-thumb-spinner"><i class="fa-solid fa-circle-notch fa-spin"></i></div></div>`;
        }
        return `
            <div class="gemini-inline-thumb-card">
                <img src="${att.dataUrl}" onclick="openFullImageModal('${att.dataUrl}')" alt="Selected">
                <button type="button" class="gemini-thumb-close-btn" onclick="removeAiAttachment('${att.id}')"><i class="fa-solid fa-xmark"></i></button>
            </div>
        `;
    }).join("");
}

function removeAiAttachment(id) {
    pendingAiAttachments = pendingAiAttachments.filter(x => x.id !== id);
    renderAiAttachmentPreviewStrip();
}

function openDmImagePicker() {
    document.getElementById("dmImageInput")?.click();
}

function handleDmImageSelect(event) {
    const allFiles = Array.from(event.target.files || []);
    event.target.value = "";
    if (!allFiles.length) return;

    const remainingSlots = 2 - pendingDmAttachmentsList.length;
    if (remainingSlots <= 0) {
        showCompactGlassToast("📷", "Maximum 2 photos allowed at once");
        return;
    }

    allFiles.slice(0, remainingSlots).forEach(file => {
        const tempId = "dmatt_" + Date.now() + "_" + Math.random().toString(36).slice(2, 6);
        pendingDmAttachmentsList.push({ id: tempId, loading: true, dataUrl: "" });
        renderDmAttachmentPreviewStrip();

        const reader = new FileReader();
        reader.onload = function (e) {
            const img = new Image();
            img.onload = function () {
                const canvas = document.createElement("canvas");
                const MAX_DIM = 680;
                let w = img.width, h = img.height;
                if (w > h && w > MAX_DIM) { h = Math.round((h * MAX_DIM) / w); w = MAX_DIM; }
                else if (h >= w && h > MAX_DIM) { w = Math.round((w * MAX_DIM) / h); h = MAX_DIM; }
                canvas.width = w;
                canvas.height = h;
                canvas.getContext("2d").drawImage(img, 0, 0, w, h);
                const compressed = canvas.toDataURL("image/jpeg", 0.65);

                const item = pendingDmAttachmentsList.find(x => x.id === tempId);
                if (item) {
                    item.loading = false;
                    item.dataUrl = compressed;
                    pendingDmAttachment = { loading: false, dataUrl: compressed };
                    renderDmAttachmentPreviewStrip();
                }
            };
            img.src = e.target.result;
        };
        reader.readAsDataURL(file);
    });
}

function renderDmAttachmentPreviewStrip() {
    const inlineRow = document.getElementById("geminiDmInlineImgRow");
    const pill = document.querySelector("#activeChatScreen .chat-input-pill");
    if (!inlineRow || !pill) return;

    if (!pendingDmAttachmentsList || pendingDmAttachmentsList.length === 0) {
        pendingDmAttachment = null;
        inlineRow.innerHTML = "";
        inlineRow.classList.remove("active");
        pill.classList.remove("has-gemini-images");
        return;
    }

    inlineRow.classList.add("active");
    pill.classList.add("has-gemini-images");
    inlineRow.innerHTML = pendingDmAttachmentsList.map(att => {
        if (att.loading) {
            return `<div class="gemini-inline-thumb-card"><div class="gemini-thumb-spinner"><i class="fa-solid fa-circle-notch fa-spin"></i></div></div>`;
        }
        return `
            <div class="gemini-inline-thumb-card">
                <img src="${att.dataUrl}" onclick="openFullImageModal('${att.dataUrl}')" alt="Selected">
                <button type="button" class="gemini-thumb-close-btn" onclick="removeSingleDmAttachment('${att.id}')"><i class="fa-solid fa-xmark"></i></button>
            </div>
        `;
    }).join("");
}

function removeSingleDmAttachment(id) {
    pendingDmAttachmentsList = pendingDmAttachmentsList.filter(x => x.id !== id);
    pendingDmAttachment = pendingDmAttachmentsList[0] || null;
    renderDmAttachmentPreviewStrip();
}

function clearDmAttachment() {
    pendingDmAttachmentsList = [];
    pendingDmAttachment = null;
    renderDmAttachmentPreviewStrip();
}

function openFullImageModal(dataUrl) {
    if (!dataUrl) return;
    pushScreenState("fullImagePreview");
    const modal = document.getElementById("fullImagePreviewModal");
    const img = document.getElementById("fullImagePreviewTarget");
    if (modal && img) {
        img.src = dataUrl;
        modal.style.setProperty("z-index", "2147483647", "important");
        modal.style.setProperty("display", "flex", "important");
    }
}

function downloadFullPreviewImage() {
    const img = document.getElementById("fullImagePreviewTarget");
    const src = img?.src || "";
    if (!src) return;
    const fileName = "Zoreno_Image_" + Date.now() + ".jpg";

    if (window.AndroidDownloader?.downloadImage) {
        window.AndroidDownloader.downloadImage(src, fileName);
    } else {
        const a = document.createElement("a");
        a.href = src;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        a.remove();
    }
    document.getElementById("fullImagePreviewModal").style.display = "none";
    showCompactGlassToast("📥", "Image saved to gallery!");
}

