async function submitCreateStudyGroup() {
    const gName = (document.getElementById("newStudyGroupName")?.value || "").trim();
    if (!gName || !db || !auth?.currentUser) return;
    const myUid = auth.currentUser.uid;
    const selectedUids = Array.from(document.querySelectorAll(".grp-invite-chk:checked")).map(cb => cb.value);

    try {
        const nowTime = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
        const grpRef = await db.collection("groups").add({
            name: gName,
            adminUid: myUid,
            admins: [myUid],
            members: [myUid],
            lastMessage: `Group "${gName}" created`,
            lastMessageAtMs: Date.now(),
            timeLabel: nowTime,
            createdAt: firebase.firestore.FieldValue.serverTimestamp()
        });

        for (const friendUid of selectedUids) {
            await db.collection("groupInvites").add({
                groupId: grpRef.id,
                groupName: gName,
                fromUid: myUid,
                inviterName: userName || "Friend",
                toUid: friendUid,
                status: "pending",
                createdAt: firebase.firestore.FieldValue.serverTimestamp()
            });
        }
        document.getElementById("zorenoCreateGroupModal").style.display = "none";
        showCompactGlassToast("🎉", `Group "${gName}" created!`);
    } catch (e) {}
}

async function respondToGroupInvite(inviteDocId, groupId, accept) {
    if (!db || !auth?.currentUser) return;
    const myUid = auth.currentUser.uid;
    try {
        if (accept) {
            await db.collection("groups").doc(groupId).update({
                members: firebase.firestore.FieldValue.arrayUnion(myUid)
            });
        }
        await db.collection("groupInvites").doc(inviteDocId).update({ status: accept ? "accepted" : "declined" });
        if (accept) showCompactGlassToast("🎉", "Joined study group!");
    } catch (e) {}
}

function openStudyGroupChat(grp) {
    closeAllDropdownMenus();
    currentChatIsGroup = true;
    currentActiveGroupData = grp;
    currentChatUserId = grp.id;
    currentChatUserMeta = {
        uid: grp.id,
        name: grp.name || "Study Group",
        avatar: grp.photoURL || "logo.png",
        username: `${(grp.members || []).length} Members`,
        bio: "Zoreno Study Group",
        isOnline: true
    };

    const chatWin = document.getElementById("activeChatScreen");
    const nameEl = document.getElementById("activeChatName");
    const avatarEl = document.getElementById("activeChatAvatar");
    const statusEl = document.getElementById("activeChatStatus");
    const bottomNav = document.getElementById("bottomNav");

    if (nameEl) nameEl.textContent = currentChatUserMeta.name;
    if (avatarEl) avatarEl.src = getSafeAvatar(grp.photoURL || "logo.png");
    if (statusEl) statusEl.innerHTML = `<span style="color:#10b981; font-weight:700;">👥 ${(grp.members || []).length} Members • Tap header for info</span>`;
    syncDmBlockedFooterUI();

    if (bottomNav) bottomNav.style.setProperty("display", "none", "important");
    if (chatWin) {
        chatWin.style.setProperty("display", "flex", "important");
        chatWin.style.setProperty("visibility", "visible", "important");
        chatWin.style.setProperty("pointer-events", "auto", "important");
    }

    if (activeMessagesUnsubscribe) activeMessagesUnsubscribe();
    const myUid = auth?.currentUser?.uid || "local";

    activeMessagesUnsubscribe = db.collection("groups").doc(grp.id).collection("messages")
        .onSnapshot(snapshot => {
            const docs = snapshot.docs.slice().sort((a, b) => (a.data().timestampMs || 0) - (b.data().timestampMs || 0));
            const list = docs.map(doc => {
                const d = doc.data();
                return {
                    id: doc.id,
                    senderId: d.senderId,
                    text: d.senderId !== myUid && d.senderName ? `${d.senderName}: ${d.text || ""}` : (d.text || ""),
                    imageData: d.imageData || "",
                    reaction: d.reaction || "",
                    timeLabel: d.timeLabel || "Now",
                    timestampMs: d.timestampMs || 0,
                    delivered: true,
                    seen: true
                };
            });
            renderDmMessagesListToDOM(grp.id, list, myUid);
        });
}

async function renderGroupMembersInsideProfile(grp) {
    const grpBox = document.getElementById("zorenoGroupMembersContainer");
    if (!grpBox || !grp) return;
    const myUid = auth?.currentUser?.uid || "";
    const memberUids = grp.members || [];
    const memCount = memberUids.length;

    const fName = document.getElementById("fpFullName");
    const uSub = document.getElementById("fpUsernameSub");
    if (fName) fName.textContent = grp.name || "Study Group";
    if (uSub) uSub.textContent = `Study Group • ${memCount} Members`;

    const memberProfiles = [];
    for (const uid of memberUids) {
        if (uid === myUid) {
            memberProfiles.push({ uid: myUid, name: userName || "You", username: currentUsername || "@student", avatar: getSafeAvatar(userAvatarUrl), isMe: true });
            continue;
        }
        let cached = userProfileCache[uid];
        if (!cached && db) {
            try {
                const uDoc = await db.collection("users").doc(uid).get();
                if (uDoc.exists) { cached = uDoc.data(); userProfileCache[uid] = cached; }
            } catch (e) {}
        }
        memberProfiles.push({
            uid: uid,
            name: cached?.name || "Student",
            username: cached?.username || "@student",
            avatar: getSafeAvatar(cached?.photoURL || cached?.avatarUrl),
            isMe: false
        });
    }

    grpBox.innerHTML = memberProfiles.map(m => `
        <div class="fp-info-card" style="justify-content:space-between; margin-bottom:9px; padding:12px 14px;">
            <div style="display:flex; align-items:center; gap:12px; min-width:0; flex:1;">
                <img src="${escapeHtml(m.avatar)}" onerror="this.src='logo.png'" style="width:42px; height:42px; border-radius:50%; object-fit:cover;">
                <div style="min-width:0; flex:1;">
                    <h4 style="margin:0; font-size:14.5px; font-weight:700;">${escapeHtml(m.name)} ${m.isMe ? "(You)" : ""}</h4>
                    <span style="font-size:12px; color:#94a3b8;">${escapeHtml(m.username)}</span>
                </div>
            </div>
        </div>
    `).join("");
}

