// Focus Sprint Timer
let sprintDurationMinutes = parseInt(localStorage.getItem("sprintSelectedDuration") || "20", 10);
let sprintInterval = null;
let memSprintTargetMs = 0;
let memSprintTotalMs = 0;

function selectSprintPreset(mins, btnEl) {
    sprintDurationMinutes = mins;
    localStorage.setItem("sprintSelectedDuration", String(mins));
    document.querySelectorAll(".preset-pill-btn").forEach(b => b.classList.remove("active"));
    if (btnEl) btnEl.classList.add("active");
    resetSprintState();
}

function toggleSprintTimer() {
    if (localStorage.getItem("sprintIsActive") === "true") {
        localStorage.setItem("sprintRemainingMs", String(Math.max(0, memSprintTargetMs - Date.now())));
        localStorage.setItem("sprintIsActive", "false");
        clearInterval(sprintInterval);
        sprintInterval = null;
        document.getElementById("sprintControlPill")?.classList.remove("running");
        const lbl = document.getElementById("sprintBtnLabel");
        if (lbl) lbl.innerText = "Go";
    } else {
        const now = Date.now();
        let rem = parseInt(localStorage.getItem("sprintRemainingMs") || "0", 10);
        if (!rem || rem <= 0) rem = sprintDurationMinutes * 60 * 1000;
        memSprintTotalMs = sprintDurationMinutes * 60 * 1000;
        memSprintTargetMs = now + rem;
        localStorage.setItem("sprintIsActive", "true");
        document.getElementById("sprintControlPill")?.classList.add("running");
        const lbl = document.getElementById("sprintBtnLabel");
        if (lbl) lbl.innerText = "Pause";
        if (sprintInterval) clearInterval(sprintInterval);
        sprintInterval = setInterval(() => {
            const leftMs = memSprintTargetMs - Date.now();
            if (leftMs <= 0) {
                resetSprintState();
                showCompactGlassToast("🏆", "Focus Sprint Completed!");
                return;
            }
            const secs = Math.ceil(leftMs / 1000);
            const tEl = document.getElementById("sprintTimerText");
            if (tEl) tEl.innerText = `${String(Math.floor(secs / 60)).padStart(2, "0")}:${String(secs % 60).padStart(2, "0")}`;
            const pct = Math.min(100, Math.max(0, ((memSprintTotalMs - leftMs) / memSprintTotalMs) * 100));
            const fill = document.getElementById("sprintProgressFill");
            const rab = document.getElementById("sprintRabbit");
            if (fill) fill.style.width = `${pct}%`;
            if (rab) rab.style.left = `${Math.min(94, pct)}%`;
        }, 1000);
    }
}

function resetSprintState() {
    if (sprintInterval) clearInterval(sprintInterval);
    sprintInterval = null;
    localStorage.setItem("sprintIsActive", "false");
    localStorage.removeItem("sprintRemainingMs");
    document.getElementById("sprintControlPill")?.classList.remove("running");
    const lbl = document.getElementById("sprintBtnLabel");
    if (lbl) lbl.innerText = "Go";
    const tEl = document.getElementById("sprintTimerText");
    if (tEl) tEl.innerText = `${String(sprintDurationMinutes).padStart(2, "0")}:00`;
    const fill = document.getElementById("sprintProgressFill");
    const rab = document.getElementById("sprintRabbit");
    if (fill) fill.style.width = "0%";
    if (rab) rab.style.left = "0%";
}

