// Hardware Back Button Handler & Global Click Listener
window.handleZorenoHardwareBack = function () {
    closeAllDropdownMenus();
    closeZorenoHoldMenu();
    const openModals = Array.from(document.querySelectorAll(".custom-modal-overlay")).filter(
        m => window.getComputedStyle(m).display !== "none"
    );
    if (openModals.length > 0) {
        openModals.forEach(m => { m.style.display = "none"; });
        return true;
    }
    const accCenter = document.getElementById("zorenoAccountCenterScreen");
    if (accCenter && window.getComputedStyle(accCenter).display !== "none") {
        closeZorenoAccountCenter();
        return true;
    }
    const fpScreen = document.getElementById("friendProfileScreen");
    if (fpScreen && window.getComputedStyle(fpScreen).display !== "none") {
        closeFriendProfileScreen();
        return true;
    }
    const dmScreen = document.getElementById("activeChatScreen");
    if (dmScreen && window.getComputedStyle(dmScreen).display !== "none") {
        closeActiveDmChat();
        return true;
    }
    const chatList = document.getElementById("chatListScreen");
    if (chatList && window.getComputedStyle(chatList).display === "none") {
        showChatsHome();
        return true;
    }
    return false;
};

