        const plusPrice = isIndia ? 249 : 3.99;
        const proPrice = isIndia ? 349 : 6.99;

        const found = RAW_WORLD_COUNTRIES.find(c => c.code === currentCountry) || RAW_WORLD_COUNTRIES[0];
        const displayEl = document.getElementById("selectedCountryDisplay");
