            if (proCard) {
                proCard.style.display = "flex";
                proCard.style.opacity = "1";
                proCard.classList.toggle("active", selectedTierLevel === 2);
            }
            selectedAmount = selectedTierLevel === 2 ? proPrice : plusPrice;
