    window.handleMusicSeek = function (e) {
        const rail = document.querySelector(".music-progress-rail");
        if (!rail) return;
        const rect = rail.getBoundingClientRect();
        const clientX = e.touches?.[0]?.clientX ?? e.changedTouches?.[0]?.clientX ?? e.clientX;
        if (typeof clientX !== "number") return;
        const ratio = Math.max(0, Math.min(1, (clientX - rect.left) / Math.max(1, rect.width)));
        const dur = (focusAudio.duration && isFinite(focusAudio.duration) && focusAudio.duration > 0)
            ? focusAudio.duration
            : 60;
        focusAudio.currentTime = ratio * dur;
        updateMusicTimeAndSeekDOM();
    };

