    // =========================================================
    // 2. TIERED VOICE: STUDIO NVIDIA NEURAL HD (PLUS/PRO) VS BASIC FREE VOICE
    // =========================================================
    window.speakAiResponseText = function (idx, btnEl) {
        const rawBot = aiChatMessagesList?.[idx]?.bot || "";
        if (!rawBot) return;

        const cleanSpeech = cleanLatexToNotebookMath(rawBot)
            .replace(/\[\[REPLY:[^\]]+\]\]/g, "")
            .replace(/[*#_~`>|]/g, " ")
            .replace(/[\u{1F300}-\u{1FAFF}\u{2600}-\u{27BF}]/gu, "")
            .replace(/\s+/g, " ")
            .trim();
        if (!cleanSpeech) return;

        if (activeSpeakingIdx === idx) {
            if (window.AndroidTTS?.stop) window.AndroidTTS.stop();
            if ("speechSynthesis" in window) window.speechSynthesis.cancel();
            activeSpeakingIdx = null;
            document.querySelectorAll(".ai-listen-btn").forEach(b => b.classList.remove("speaking"));
            return;
        }

        document.querySelectorAll(".ai-listen-btn").forEach(b => b.classList.remove("speaking"));
        activeSpeakingIdx = idx;
        if (btnEl) btnEl.classList.add("speaking");

        const activeTier = getEffectiveTier();
        const isHindi = /[\u0900-\u097F]/.test(cleanSpeech);
        const langCode = isHindi ? "hi-IN" : "en-IN";

        // Native Android Bridge: Pass tier flag so Plus/Pro uses NVIDIA Riva Neural HD TTS!
        if (window.AndroidTTS) {
            if (activeTier >= 1 && typeof window.AndroidTTS.speakNeural === "function") {
                window.AndroidTTS.speakNeural(cleanSpeech.slice(0, 1500), langCode);
                return;
            } else if (typeof window.AndroidTTS.speak === "function") {
                window.AndroidTTS.speak(cleanSpeech.slice(0, 1500), langCode);
                return;
            }
        }

        if (!("speechSynthesis" in window)) return;
        window.speechSynthesis.cancel();
        const voices = window.speechSynthesis.getVoices() || [];

        if (activeTier >= 1) {
            // PLUS & PRO: Studio Neural Bilingual Sentence-by-Sentence Voice
            const hiNeural = voices.find(v => v.lang.includes("hi") && /natural|swara|madhur|neural|google/i.test(v.name)) || voices.find(v => v.lang.includes("hi"));
            const enNeural = voices.find(v => v.lang.includes("en-IN") && /natural|neerja|prabhat|neural|google/i.test(v.name)) || voices.find(v => v.lang.includes("en"));
            const sentences = cleanSpeech.split(/(?<=[।.?!])\s+/).filter(Boolean);
            let sIdx = 0;

            const speakNext = () => {
                if (activeSpeakingIdx !== idx || sIdx >= sentences.length) {
                    activeSpeakingIdx = null;
                    if (btnEl) btnEl.classList.remove("speaking");
                    return;
                }
                const sent = sentences[sIdx++];
                const sentHindi = /[\u0900-\u097F]/.test(sent);
                const u = new SpeechSynthesisUtterance(sent);
                u.lang = sentHindi ? "hi-IN" : "en-IN";
                if (sentHindi && hiNeural) u.voice = hiNeural;
                else if (!sentHindi && enNeural) u.voice = enNeural;
                u.rate = 1.02;
                u.pitch = 1.0;
                u.onend = speakNext;
                u.onerror = speakNext;
                window.speechSynthesis.speak(u);
            };
            speakNext();
        } else {
            // FREE TIER: Basic Standard Voice
            const u = new SpeechSynthesisUtterance(cleanSpeech);
            u.lang = langCode;
            u.rate = 0.92;
            u.pitch = 0.88;
            u.onend = () => { activeSpeakingIdx = null; if (btnEl) btnEl.classList.remove("speaking"); };
            u.onerror = () => { activeSpeakingIdx = null; if (btnEl) btnEl.classList.remove("speaking"); };
            window.speechSynthesis.speak(u);
        }
    };

