    // 5. Markdown Table Formatter + Zero Top-Gap Fluid AI Replies (34025, 34034, 34035 Fix!)
    const _v38OrigFormatMd = formatMarkdown;
    formatMarkdown = function (t, seedOffset = 0) {
        if (!t) return "";
        const cleaned = cleanLatexToNotebookMath(String(t)).trim();

        // Check if reply contains a Markdown Table (`| ... |`) like 34034.png / 34035.png
        if (cleaned.includes("|") && /\n\s*\|?[\s\-:|]+\|/.test(cleaned)) {
            const lines = cleaned.split("\n");
            let out = [];
            let tableRows = [];

            const flushTable = () => {
                if (tableRows.length === 0) return;
                const validRows = tableRows.filter(r => !/^[\s|:\-]+$/.test(r));
                if (validRows.length > 0) {
                    let tHtml = `<div class="ai-glass-table-wrap"><table class="ai-glass-table">`;
                    validRows.forEach((rowStr, rIdx) => {
                        const cells = rowStr.replace(/^\||\|$/g, "").split("|").map(c => escapeHtml(c.trim()).replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>"));
                        if (rIdx === 0) {
                            tHtml += `<thead><tr>${cells.map(c => `<th>${c}</th>`).join("")}</tr></thead><tbody>`;
                        } else {
                            tHtml += `<tr>${cells.map(c => `<td>${c}</td>`).join("")}</tr>`;
                        }
                    });
                    tHtml += `</tbody></table></div>`;
                    out.push(tHtml);
                }
                tableRows = [];
            };

            lines.forEach(l => {
                const tr = l.trim();
                if (tr.startsWith("|") && tr.endsWith("|")) {
                    tableRows.push(tr);
                } else {
                    flushTable();
                    if (tr) out.push(_v38OrigFormatMd(tr, seedOffset));
                }
            });
            flushTable();
            return out.join("");
        }

        return _v38OrigFormatMd(cleaned, seedOffset);
    };

    // Reset AI tone immediately when user says "Hello" / "Hi" or changes topic (Fixes 34025/34026 Shayari Stuck Loop!)
    const _v38OrigBuildCtx = buildLiveContextForAI;
