// =========================================================

(function initZorenoV44FinalFix() {
    // 1. Restore <input type="file"> tags so + Button sends photos in AI & Friend Chat
    function ensureFileInputsExist() {
        if (!document.getElementById("imageInput")) {
            const aiFileInp = document.createElement("input");
            aiFileInp.type = "file";
            aiFileInp.id = "imageInput";
            aiFileInp.accept = "image/*";
            aiFileInp.multiple = true;
            aiFileInp.hidden = true;
            aiFileInp.onchange = (ev) => window.handleMultipleImages(ev);
            document.body.appendChild(aiFileInp);
        }
        if (!document.getElementById("dmImageInput")) {
            const dmFileInp = document.createElement("input");
            dmFileInp.type = "file";
            dmFileInp.id = "dmImageInput";
            dmFileInp.accept = "image/*";
            dmFileInp.multiple = true;
            dmFileInp.hidden = true;
            dmFileInp.onchange = (ev) => window.handleDmImageSelect(ev);
            document.body.appendChild(dmFileInp);
        }
    }

    window.openImagePicker = function () { ensureFileInputsExist(); document.getElementById("imageInput")?.click(); };
    window.openFileOrPdfPicker = function () { ensureFileInputsExist(); document.getElementById("imageInput")?.click(); };
    window.openDmImagePicker = function () { ensureFileInputsExist(); document.getElementById("dmImageInput")?.click(); };

    // 2. Fix Daily Limit & +3 Chats Reward for ALL Tiers (Free = 10, Plus = 50, Pro = 90 + Bonus Chats)
    const _baseGetDailyLimit = getLocalDailyAiLimit;
    getLocalDailyAiLimit = function () {
        const rawLim = _baseGetDailyLimit();
        const tierNow = getEffectiveTier();
        const baseCap = tierNow === 2 ? 90 : tierNow === 1 ? 50 : 10;
        return Math.max(baseCap, rawLim);
    };

    window.addBonusAiChats = function (extraChats = 3) {
        const today = getTodayLocalMidnightKey();
        const currentMax = getLocalDailyAiLimit();
        const newLimit = currentMax + extraChats;
        localStorage.setItem("zorenoAiLimitDate", today);
        localStorage.setItem("zorenoAiDailyLimit", String(newLimit));
        window.AndroidPrefs?.setString?.("zorenoAiLimitDate", today);
        window.AndroidPrefs?.setString?.("zorenoAiDailyLimit", String(newLimit));
        if (db && auth?.currentUser) {
            db.collection("users").doc(auth.currentUser.uid).set({
                dailyAiDate: today,
                dailyAiLimit: newLimit
            }, { merge: true }).catch(() => {});
        }
        return newLimit;
    };

    // Intercept sendMessage when quota is 100% full -> Open Rewarded Ad Modal (+3 Free Chats)!
    const _v44OrigSendMessage = sendMessage;
    sendMessage = async function () {
        if (!isAiGenerating) {
            const usedToday = getLocalDailyAiCount();
            const maxAllowedToday = getLocalDailyAiLimit();
            if (usedToday >= maxAllowedToday) {
                openRewardedAdModal();
                return;
            }
        }
        // Temporarily sync userTier limit check inside original sendMessage
        const savedTier = userTier;
        if (getLocalDailyAiLimit() > (userTier === 2 ? 90 : userTier === 1 ? 50 : 10)) {
            userTier = 0; // Forces original sendMessage to read getLocalDailyAiLimit() with +3 bonus!
        }
        try {
            await _v44OrigSendMessage();
        } finally {
            userTier = savedTier;
        }
    };

    window.triggerRewardedAdForChats = function () {
        const btn = document.getElementById("watchRewardedAdBtn");
        const txt = document.getElementById("watchAdBtnText");
        if (btn) btn.disabled = true;
        if (txt) txt.textContent = "Loading Ad...";

        if (window.AndroidAdMob && typeof window.AndroidAdMob.showRewardedAd === "function") {
            window.AndroidAdMob.showRewardedAd("ca-app-pub-5825754850490611/4904670790");
            setTimeout(() => {
                if (btn) btn.disabled = false;
                if (txt) txt.textContent = "Watch Ad";
            }, 2500);
            return;
        }
        setTimeout(() => {
            if (btn) btn.disabled = false;
            if (txt) txt.textContent = "Watch Ad";
            window.onAdMobRewardGranted();
        }, 1800);
    };

    window.onAdMobRewardGranted = function () {
        window.addBonusAiChats(3);
        closeRewardedAdModal();
        showCompactGlassToast("⚡", "+3 Free Chats Unlocked!");
    };

    // 3. Real AdMob Banner Ad Sync on Home Screen (Hidden on Plus/Pro)
    function syncRealAdMobBannerOnHome() {
        const bannerBox = document.getElementById("zorenoAdmobBannerContainer");
        if (!bannerBox) return;

        const activeTier = getEffectiveTier();
        const homeScreen = document.getElementById("chatListScreen");
        const isHomeVisible = homeScreen && window.getComputedStyle(homeScreen).display !== "none";
        const anyModalOpen = Array.from(document.querySelectorAll(".custom-modal-overlay")).some(
            m => window.getComputedStyle(m).display !== "none"
        );

        if (activeTier > 0) {
            bannerBox.style.setProperty("display", "none", "important");
            if (window.AndroidAdMob?.setBannerVisible) {
                window.AndroidAdMob.setBannerVisible(false, 0, 0, 0, 0);
            }
            return;
        }

        bannerBox.style.setProperty("display", "block", "important");
        if (window.AndroidAdMob?.setBannerVisible) {
            if (isHomeVisible && !anyModalOpen && !document.body.classList.contains("keyboard-open")) {
                const r = bannerBox.getBoundingClientRect();
                const showNow = r.top >= 45 && r.bottom <= window.innerHeight - 65;
                window.AndroidAdMob.setBannerVisible(
                    showNow,
                    Math.round(r.left),
                    Math.round(r.top),
                    Math.round(r.width),
                    Math.round(r.height)
                );
            } else {
                window.AndroidAdMob.setBannerVisible(false, 0, 0, 0, 0);
            }
        }
    }

    window.addEventListener("scroll", syncRealAdMobBannerOnHome, { passive: true });
    document.addEventListener("scroll", syncRealAdMobBannerOnHome, { passive: true, capture: true });

    // 4. Native Speech-to-Text Receiver
    window.onNativeSpeechResult = function (inputId, spokenText) {
        const inp = document.getElementById(inputId || "userInput");
        document.querySelectorAll(".zoreno-voice-mic-btn").forEach(b => b.classList.remove("recording"));
        document.querySelectorAll(".zoreno-live-voice-wave").forEach(w => w.classList.remove("active"));
        if (inp && spokenText) {
            inp.value = (inp.value ? inp.value.trim() + " " : "") + spokenText.trim();
            window.autoResizeChatInput(inp);
            inp.focus();
        }
    };

    setInterval(() => {
        ensureFileInputsExist();
        syncRealAdMobBannerOnHome();
    }, 500);

    setTimeout(() => {
        ensureFileInputsExist();
        syncRealAdMobBannerOnHome();
        try { (window.adsbygoogle = window.adsbygoogle || []).push({}); } catch (e) {}
    }, 250);
})();



