    window.getDailyVideoGenCount = function () {
        const today = getTodayLocalMidnightKey();
        if (localStorage.getItem("zorenoVidGenDate") !== today) {
            localStorage.setItem("zorenoVidGenDate", today);
            localStorage.setItem("zorenoVidGenCount", "0");
            return 0;
        }
        return parseInt(localStorage.getItem("zorenoVidGenCount") || "0", 10) || 0;
    };

    window.incrementDailyVideoGenCount = function () {
        const today = getTodayLocalMidnightKey();
        const next = window.getDailyVideoGenCount() + 1;
        localStorage.setItem("zorenoVidGenDate", today);
        localStorage.setItem("zorenoVidGenCount", String(next));
        return next;
    };

    window.canUserGenerateVideoToday = function () {
        if (getEffectiveTier() > 0) return true;
        if (window.getDailyVideoGenCount() >= 5) {
            showCustomAlert("Daily Limit Reached (5/5)", "Free users can generate up to 5 AI videos/audio narrations per day. Upgrade to Plus or Pro for higher limits!");
            openSubscription();
            return false;
        }
        return true;
    };

    // Crystal-Clear Natural Voice Parameters for All Users (Fixes robotic pitch/rate distortion)
    window.speakWithOptimizedClarity = function (text, langCode = "en-IN", onEndCb) {
        if (!text) return;
        const clean = String(text)
            .replace(/<[^>]+>/g, " ")
            .replace(/\[\[[^\]]+\]\]/g, " ")
            .replace(/[*#_~`>|]/g, " ")
            .replace(/\s+/g, " ")
            .trim();
        if (!clean) return;

        if (window.AndroidTTS?.speakNeural) {
            window.AndroidTTS.speakNeural(clean.slice(0, 1800), langCode);
            return;
        }
        if ("speechSynthesis" in window) {
            window.speechSynthesis.cancel();
            const voices = window.speechSynthesis.getVoices() || [];
            const langPrefix = langCode.split("-")[0].toLowerCase();
            const preferred = voices.find(v => v.lang.toLowerCase().startsWith(langPrefix) && /natural|neural|google|online|swara|neerja|prabhat|madhur/i.test(v.name))
                || voices.find(v => v.lang.toLowerCase().startsWith(langPrefix));
            const utter = new SpeechSynthesisUtterance(clean);
            if (preferred) utter.voice = preferred;
            utter.lang = preferred?.lang || langCode;
            utter.rate = 1.0;
            utter.pitch = 1.0;
            utter.volume = 1.0;
            if (typeof onEndCb === "function") {
                utter.onend = onEndCb;
                utter.onerror = onEndCb;
            }
            window.speechSynthesis.speak(utter);
        }
    };

