    window.confirmAndDeleteStudyGroup = function () {
        if (!currentChatIsGroup || !currentActiveGroupData) return;
        const myUid = auth?.currentUser?.uid || "";
        const isAdmin = currentActiveGroupData.adminUid === myUid || (currentActiveGroupData.admins || []).includes(myUid);
        if (!isAdmin) {
            showCustomAlert("Admin Permission Required", "Only the authorized Group Admin can delete this group.");
            return;
        }
        window.openAreYouSureConfirmModal(
            `Delete "${currentActiveGroupData.name}"?`,
            "WARNING: This will permanently delete this study group and all messages for all members. This cannot be undone.",
            async () => {
                try {
                    const gid = currentActiveGroupData.id;
                    const msgSnap = await db.collection("groups").doc(gid).collection("messages").get();
                    const batch = db.batch();
                    msgSnap.forEach(d => batch.delete(d.ref));
                    batch.delete(db.collection("groups").doc(gid));
                    await batch.commit();
                    closeFriendProfileScreen();
                    closeActiveDmChat();
                    showCompactGlassToast("", "Group deleted");
                } catch (e) {
                    showCustomAlert("Delete Failed", e.message);
                }
            }
        );
    };

    window.confirmAndLeaveStudyGroup = function () {
        if (!currentChatIsGroup || !currentActiveGroupData || !auth?.currentUser) return;
        const myUid = auth.currentUser.uid;
        const grp = currentActiveGroupData;
        const members = (grp.members || []).filter(u => u !== myUid);
        const isAdmin = grp.adminUid === myUid || (grp.admins || []).includes(myUid);

        window.openAreYouSureConfirmModal(
            `Leave "${grp.name}"?`,
            isAdmin && members.length > 0
                ? "You are the Admin. Leaving will automatically transfer Admin ownership to the next member."
                : "Are you sure you want to leave this study group?",
            async () => {
                try {
                    if (members.length === 0) {
                        await db.collection("groups").doc(grp.id).delete();
                    } else {
                        const updates = {
                            members: firebase.firestore.FieldValue.arrayRm ? firebase.firestore.FieldValue.arrayRemove(myUid) : members
                        };
                        if (grp.adminUid === myUid) {
                            updates.adminUid = members[0];
                            updates.admins = [members[0]];
                        }
                        await db.collection("groups").doc(grp.id).update(updates);
                    }
                    closeFriendProfileScreen();
                    closeActiveDmChat();
                    showCompactGlassToast("", "Left group");
                } catch (e) {
                    showCustomAlert("Error", e.message);
                }
            }
        );
    };

