    window.executeSecureDailyLimitReset = async function () {
        const pass = (document.getElementById("tokoResetConfirmPassInp")?.value || "").trim();
        const err = document.getElementById("tokoResetPassErr");
        if (pass !== SECRET_PRO_PASS && pass !== SECRET_PLUS_PASS) {
            if (err) err.style.display = "block";
            return;
        }
        const today = getTodayLocalMidnightKey();
        localStorage.setItem("zorenoAiDate", today);
        localStorage.setItem("zorenoAiCount", "0");
        localStorage.setItem("zorenoVidGenDate", today);
        localStorage.setItem("zorenoVidGenCount", "0");
        window.AndroidPrefs?.setString?.("zorenoAiDate", today);
        window.AndroidPrefs?.setString?.("zorenoAiCount", "0");

        if (db && auth?.currentUser) {
            try {
                await db.collection("users").doc(auth.currentUser.uid).set({
                    dailyAiDate: today,
                    dailyAiCount: 0
                }, { merge: true });
            } catch (e) {}
        }
        document.getElementById("tokoSecureResetModal").style.display = "none";
        showCompactGlassToast("", "Daily usage limit reset");
        window.openTokoCentralAnalyticsModal();
    };

