    function setupToolsHubAndPreserveMusic() {
        const toolsScreen = document.getElementById("toolsScreen");
        if (!toolsScreen) return;
        let ws = document.getElementById("ztoolDynamicWorkspace");
        let fm = document.getElementById("ztoolFocusMusicSubView");

        if (!ws) {
            ws = document.createElement("div");
            ws.id = "ztoolDynamicWorkspace";
            ws.style.width = "100%";
            toolsScreen.insertBefore(ws, toolsScreen.firstChild);
        }
        if (!fm) {
            fm = document.createElement("div");
            fm.id = "ztoolFocusMusicSubView";
            fm.style.cssText = "display:none !important; flex-direction:column; gap:12px; width:100%;";
            Array.from(toolsScreen.children).forEach(ch => {
                if (ch.id !== "ztoolDynamicWorkspace" && ch.id !== "ztoolFocusMusicSubView") {
                    fm.appendChild(ch);
                }
            });
            toolsScreen.appendChild(fm);
        }
        focusMusicSubContainer = fm;
        const musicBackBtn = fm.querySelector(".music-top-bar .music-circle-icon-btn");
        if (musicBackBtn) {
            musicBackBtn.onclick = (e) => {
                if (e) e.stopPropagation();
                window.openZorenoToolView("hub");
            };
        }
        if (!toolsScreen.dataset.v45HubReady) {
            toolsScreen.dataset.v45HubReady = "true";
            renderToolsHubView();
        }
    }

