    // Central Entitlement Check for Pro-Only Tools (Tools 5-10)
    window.requireZorenoProForTool = function (toolId, toolTitle) {
        const toolObj = ALL_10_TOOLS_DEF.find(t => t.id === toolId);
        if (!toolObj || toolObj.access === "free" || toolObj.access === "freemium") {
            return true;
        }
        // Strict 3-Layer Entitlement Check: Effective Tier === 2 (₹349 Pro) AND Not Expired
        const effTier = getEffectiveTier();
        const isNotExpired = !subExpiresAtMs || subExpiresAtMs > Date.now();
        if (effTier >= 2 && isNotExpired) {
            return true;
        }
        openProToolUpgradeGateModal(toolTitle || toolObj.title);
        return false;
    };

