    window.handleCombinePdfFiles = function (ev) {
        const files = Array.from(ev.target.files || []);
        ev.target.value = "";
        let done = 0;
        files.forEach(f => {
            const r = new FileReader();
            r.onload = (e) => {
                combinePdfList.push({ name: f.name, sizeStr: formatFileSizeStr(f.size), bytes: new Uint8Array(e.target.result) });
                done++;
                if (done === files.length) renderCombinePdfTool();
            };
            r.readAsArrayBuffer(f);
        });
    };

    window.executeCombinePdfsNow = async function () {
        if (!window.requireZorenoProForTool("combine_pdf", "Combine PDF")) return;
        if (combinePdfList.length < 2) return showCompactGlassToast("", "Select at least 2 PDFs");
        try {
            const merged = await window.PDFLib.PDFDocument.create();
            let totalPages = 0;
            for (const f of combinePdfList) {
                const src = await window.PDFLib.PDFDocument.load(f.bytes);
                const copied = await merged.copyPages(src, src.getPageIndices());
                copied.forEach(p => { merged.addPage(p); totalPages++; });
            }
            const uri = await merged.saveAsBase64({ dataUri: true });
            combinePdfResult = { fileName: "Combined_Document.pdf", pages: totalPages, dataUrl: uri };
            renderCombinePdfTool();
        } catch (err) {
            showCustomAlert("Encrypted or Corrupted PDF", "One of the selected PDFs is password-protected and cannot be merged.");
        }
    };

