    window.executeSaveEditedPdf = async function () {
        if (!window.requireZorenoProForTool("edit_pdf", "Edit PDF")) return;
        if (!editPdfRawBytes) return showCompactGlassToast("", "Choose a PDF file first");
        try {
            const doc = await window.PDFLib.PDFDocument.load(editPdfRawBytes);
            const pages = doc.getPages();
            const txt = (document.getElementById("editPdfOverlayText")?.value || "").trim();
            const useWhiteout = document.getElementById("editPdfWhiteoutChk")?.checked;
            const rot = parseInt(document.getElementById("editPdfRotateSel")?.value || "0", 10);

            if (pages.length > 0) {
                const first = pages[0];
                const { height } = first.getSize();
                if (useWhiteout && txt) {
                    first.drawRectangle({ x: 36, y: height - 68, width: 260, height: 32, color: window.PDFLib.rgb(1, 1, 1) });
                }
                if (txt) {
                    first.drawText(txt, { x: 42, y: height - 56, size: 16, color: window.PDFLib.rgb(0.42, 0.16, 0.85) });
                }
                if (rot > 0) {
                    pages.forEach(p => p.setRotation(window.PDFLib.degrees(rot)));
                }
            }
            const uri = await doc.saveAsBase64({ dataUri: true });
            window.triggerZorenoFileSave(uri, editPdfRawName, "application/pdf");
        } catch (e) {
            showCustomAlert("Edit Error", "Could not modify this PDF.");
        }
    };

