    window.executeGenerateTextPdf = async function () {
        if (!window.requireZorenoProForTool("create_pdf", "Create PDF")) return;
        const title = (document.getElementById("createPdfDocTitle")?.value || "Zoreno_Notes").trim();
        const body = (document.getElementById("createPdfDocBody")?.value || "").trim();
        if (!body) return showCompactGlassToast("", "Write some text first");

        const doc = await window.PDFLib.PDFDocument.create();
        const page = doc.addPage([595.28, 841.89]);
        page.drawText(title, { x: 44, y: 785, size: 20, color: window.PDFLib.rgb(0.38, 0.15, 0.85) });

        const words = body.replace(/\r\n/g, "\n").split(/\s+/);
        let lines = [];
        let cur = "";
        words.forEach(w => {
            if ((cur + " " + w).length > 78) { lines.push(cur); cur = w; }
            else cur = cur ? cur + " " + w : w;
        });
        if (cur) lines.push(cur);

        let y = 748;
        lines.slice(0, 42).forEach(ln => {
            page.drawText(ln, { x: 44, y, size: 11.5, color: window.PDFLib.rgb(0.08, 0.1, 0.15) });
            y -= 16;
        });

        const uri = await doc.saveAsBase64({ dataUri: true });
        const outFile = (title.replace(/[^a-zA-Z0-9_-]/g, "_") || "Document") + ".pdf";
        saveRecentGeneratedPdfRecord(outFile, 1, Math.round((uri.length * 3) / 4), uri);
        window.triggerZorenoFileSave(uri, outFile, "application/pdf");
        renderCreatePdfTool();
    };

