    // =========================================================
    // 3. ANDROID WEBVIEW + BROWSER RELIABLE DOWNLOAD & SHARE ENGINE
    // =========================================================
    async function triggerSingleFileDownload(blob, filename, mimeType) {
        const dataUrl = await blobToDataUrl(blob);
        const base64Only = dataUrl.split(",")[1] || "";

        // 1. Try Native Android WebView Download Bridges first (100% Reliable in APK Wrapper!)
        try {
            if (window.AndroidDownloader?.downloadFile) {
                window.AndroidDownloader.downloadFile(dataUrl, filename, mimeType);
                return true;
            }
            if (window.AndroidDownloader?.downloadBase64) {
                window.AndroidDownloader.downloadBase64(base64Only, filename, mimeType);
                return true;
            }
            if (mimeType === "application/pdf" && window.AndroidDownloader?.downloadPdf) {
                window.AndroidDownloader.downloadPdf(dataUrl, filename);
                return true;
            }
            if (mimeType.startsWith("image/") && window.AndroidDownloader?.downloadImage) {
                window.AndroidDownloader.downloadImage(dataUrl, filename);
                return true;
            }
        } catch (e) {}

        // 2. Fallback: DataURL anchor download (works in Android WebView & Chrome without blob: crash)
        try {
            const a = document.createElement("a");
            a.href = blob.size > 7 * 1024 * 1024 ? URL.createObjectURL(blob) : dataUrl;
            a.download = filename;
            a.rel = "noopener";
            document.body.appendChild(a);
            a.click();
            setTimeout(() => {
                if (a.href.startsWith("blob:")) URL.revokeObjectURL(a.href);
                a.remove();
            }, 1000);
            return true;
        } catch (err) {
            return false;
        }
    }

    async function executeToolDownloadNow() {
        const res = ztState.result;
        if (!res) return;

        try {
            if (res.type === "pdf") {
                await triggerSingleFileDownload(res.blob, res.fileName, "application/pdf");
                showCompactGlassToast("", "PDF Downloaded!");
            } else if (res.type === "single_image") {
                await triggerSingleFileDownload(res.blob, res.fileName, res.mime);
                showCompactGlassToast("", "Saved to Gallery!");
            } else if (res.type === "multi_image") {
                for (let i = 0; i < res.items.length; i++) {
                    const it = res.items[i];
                    await triggerSingleFileDownload(it.blob, it.fileName, it.mime);
                    if (i < res.items.length - 1) await new Promise(r => setTimeout(r, 260));
                }
                showCompactGlassToast("", `${res.items.length} Images Saved!`);
            }
        } catch (e) {
            showCompactGlassToast("", "Download failed, try Share");
        }
    }

    async function executeToolShareNow() {
        const res = ztState.result;
        if (!res) return;

        const filesToShare = [];
        if (res.type === "pdf") {
            filesToShare.push(new File([res.blob], res.fileName, { type: "application/pdf" }));
        } else if (res.type === "single_image") {
            filesToShare.push(new File([res.blob], res.fileName, { type: res.mime }));
        } else if (res.type === "multi_image") {
            res.items.forEach(it => filesToShare.push(new File([it.blob], it.fileName, { type: it.mime })));
        }

        // 1. Web Share API (Native Android Share Sheet)
        try {
            if (navigator.canShare && navigator.share && navigator.canShare({ files: filesToShare })) {
                await navigator.share({
                    title: "Shared from Zoreno",
                    text: "Created with Zoreno Tools",
                    files: filesToShare
                });
                return;
            }
        } catch (e) {
            if (e.name === "AbortError") return;
        }

        // 2. Android Native Share Bridge
        try {
            const firstFile = filesToShare[0];
            if (firstFile) {
                const dUrl = await blobToDataUrl(firstFile);
                if (window.AndroidShare?.shareFile) {
                    window.AndroidShare.shareFile(dUrl, firstFile.name, firstFile.type);
                    return;
                }
                if (firstFile.type.startsWith("image/") && window.AndroidShare?.shareImageAndText) {
                    window.AndroidShare.shareImageAndText(dUrl, "Created with Zoreno Tools");
                    return;
                }
            }
        } catch (e) {}

        // 3. Fallback: Save directly so user never hits a dead button
        await executeToolDownloadNow();
    }

