    // ---------------------------------------------------------
    function fixThinkingBubbleText(labelText) {
        const rows = document.querySelectorAll('[id^="zorenoThinking_"]');
        if (!rows.length) return;
        const latestRow = rows[rows.length - 1];
        // Clean any text accidentally injected into the 6px dot spans!
        latestRow.querySelectorAll(".thinking-dots span").forEach(dot => {
            if (dot.textContent) dot.textContent = "";
        });
        // Put live status text cleanly in the FIRST label span (next to .thinking-dots)
        const labelSpan = latestRow.querySelector(".clean-left-bubble > div > span:first-child");
        if (labelSpan && labelText) {
            labelSpan.textContent = labelText;
        }
    }

    const _v58OrigBuildCtx = buildLiveContextForAI;
    buildLiveContextForAI = async function (userText) {
        const res = await _v58OrigBuildCtx(userText);
        // Immediately repair any text written to dot spans by V57
        const hasUrl = /https?:\/\//i.test(userText || "");
        const needsWeb = /\b(price|stock|share|nifty|sensex|bitcoin|gold|weather|news|score|today|latest|current|live|2026|rate|exchange|usd|inr)\b/i.test(userText || "");
        fixThinkingBubbleText(hasUrl ? "Reading link" : needsWeb ? "Searching live web" : "Zoreno is thinking");
        return res;
    };

    // Guard observer on #chatMessages so dot spans NEVER hold text characters
    function guardThinkingDots() {
        const box = document.getElementById("chatMessages");
        if (!box || box.dataset.v58DotGuard === "true") return;
        box.dataset.v58DotGuard = "true";
        const obs = new MutationObserver(() => {
            box.querySelectorAll(".thinking-dots span").forEach(dot => {
                if (dot.textContent && dot.textContent.trim().length > 0) {
                    const txt = dot.textContent.replace(/^[^\w]+/, "").trim();
                    dot.textContent = "";
                    const parentRow = dot.closest('[id^="zorenoThinking_"]');
                    const lbl = parentRow?.querySelector(".clean-left-bubble > div > span:first-child");
                    if (lbl && txt) lbl.textContent = txt.replace(/\.\.\.$/, "");
                }
            });
        });
        obs.observe(box, { childList: true, subtree: true, characterData: true });
    }
    guardThinkingDots();
    window.addEventListener("DOMContentLoaded", guardThinkingDots);

    // ---------------------------------------------------------
    // 2. ROCK-SOLID KEYBOARD LIFT FOR BOTH AI CHAT & FRIEND CHAT INPUTS
    // ---------------------------------------------------------
    let baseFullWindowHeight = window.innerHeight;

    function syncChatComposerAboveKeyboard() {
        const activeEl = document.activeElement;
        const isChatInp = Boolean(activeEl && (activeEl.id === "userInput" || activeEl.id === "activeChatInput"));

        if (!isChatInp && window.innerHeight > baseFullWindowHeight) {
            baseFullWindowHeight = window.innerHeight;
        }

        const vv = window.visualViewport;
        const visibleH = vv ? Math.round(vv.height) : window.innerHeight;
        const offsetTop = vv ? Math.round(vv.offsetTop) : 0;

        const footerAi = document.getElementById("inputAreaContainer");
        const footerDm = document.querySelector("#activeChatScreen .chat-win-footer");

        // Case A: Viewport shrank (resizes-content mode) -> visibleH is already above keyboard!
        // Case B: Viewport stayed tall (overlays-content mode) -> compute difference to lift bottom!
        const diffFromWindow = Math.max(0, Math.round(window.innerHeight - (visibleH + offsetTop)));
        const kbLift = diffFromWindow > 70 ? diffFromWindow : 0;

        document.documentElement.style.setProperty("--zoreno-chat-vh", visibleH + "px");
        document.documentElement.style.setProperty("--zoreno-kb-offset", kbLift + "px");

        if (isChatInp) {
            // Pin visible composer explicitly to the bottom of the live visual viewport
            const targetFooter = activeEl.id === "userInput" ? footerAi : footerDm;
            if (targetFooter && window.getComputedStyle(targetFooter).display !== "none") {
                targetFooter.style.setProperty("bottom", `${10 + kbLift}px`, "important");
            }
            const scrollEl = activeEl.id === "userInput"
                ? document.getElementById("chatMessages")
                : document.getElementById("activeChatMessages");
            if (scrollEl) {
                setTimeout(() => { scrollEl.scrollTop = scrollEl.scrollHeight; }, 60);
            }
        } else {
            if (footerAi) footerAi.style.removeProperty("bottom");
            if (footerDm) footerDm.style.removeProperty("bottom");
        }
    }

    if (window.visualViewport) {
        window.visualViewport.addEventListener("resize", syncChatComposerAboveKeyboard);
        window.visualViewport.addEventListener("scroll", syncChatComposerAboveKeyboard);
    }
    window.addEventListener("resize", syncChatComposerAboveKeyboard);
    document.addEventListener("focusin", (e) => {
        if (e.target && (e.target.id === "userInput" || e.target.id === "activeChatInput")) {
            setTimeout(syncChatComposerAboveKeyboard, 80);
            setTimeout(syncChatComposerAboveKeyboard, 280);
        }
    });
    document.addEventListener("focusout", () => {
        setTimeout(syncChatComposerAboveKeyboard, 120);
    });

