    // ---------------------------------------------------------
    // 5. FULL TOKO INTELLIGENCE DASHBOARD (ANALYTICS, REPORTS, API, PLANS)
    // ---------------------------------------------------------
    let intelState = {
        tab: "analytics",
        chartMetric: "appOpens",
        loading: false,
        globalStats: {},
        dailySeries: [],
        reports: [],
        feedbacks: [],
        cloudApiKey: GEMINI_API_KEY || "",
        showApiKey: false
    };

    function getLast7DateKeys() {
        const keys = [];
        for (let i = 6; i >= 0; i--) {
            const d = new Date();
            d.setDate(d.getDate() - i);
            keys.push(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`);
        }
        return keys;
    }

    async function fetchAllIntelligenceData() {
        intelState.loading = true;
        renderIntelScreen();

        if (!db) {
            intelState.loading = false;
            renderIntelScreen();
            return;
        }

        await flushTelemetryToFirestore();

        try {
            const [gDoc, apiDoc, repSnap, fbSnap] = await Promise.all([
                db.collection("analytics").doc("globalStats").get().catch(() => null),
                db.collection("appConfig").doc("aiSettings").get().catch(() => null),
                db.collection("reports").limit(25).get().catch(() => null),
                db.collection("feedbacks").limit(25).get().catch(() => null)
            ]);

            intelState.globalStats = gDoc?.exists ? (gDoc.data() || {}) : {};
            if (apiDoc?.exists && apiDoc.data()?.geminiApiKey) {
                intelState.cloudApiKey = String(apiDoc.data().geminiApiKey).trim();
            } else {
                intelState.cloudApiKey = GEMINI_API_KEY || "";
            }

            if (repSnap) {
                intelState.reports = repSnap.docs
                    .map(d => ({ id: d.id, ...d.data() }))
                    .sort((a, b) => (b.timestampMs || b.createdAt?.toMillis?.() || 0) - (a.timestampMs || a.createdAt?.toMillis?.() || 0));
            }
            if (fbSnap) {
                intelState.feedbacks = fbSnap.docs
                    .map(d => ({ id: d.id, ...d.data() }))
                    .sort((a, b) => (b.createdAt?.toMillis?.() || 0) - (a.createdAt?.toMillis?.() || 0));
            }

            // Load 7-Day Trading Series
            const dateKeys = getLast7DateKeys();
            const dayDocs = await Promise.all(
                dateKeys.map(k => db.collection("analytics").doc(`daily_${k}`).get().catch(() => null))
            );
            intelState.dailySeries = dateKeys.map((k, idx) => {
                const d = dayDocs[idx]?.exists ? (dayDocs[idx].data() || {}) : {};
                return {
                    label: k.slice(5),
                    appOpens: d.appOpens || 0,
                    aiChats: d.aiChats || 0,
                    friendChats: d.friendChats || 0,
                    toolUses: d.toolUses || 0,
                    adViews: d.adViews || 0,
                    screenTimeMin: Math.round((d.screenTimeSec || 0) / 60)
                };
            });
        } catch (e) {}

        intelState.loading = false;
        renderIntelScreen();
    }

    function buildTradingSvgChart(series, metricKey) {
        const vals = series.map(s => Number(s[metricKey] || 0));
        const maxVal = Math.max(4, ...vals);
        const w = 320, h = 135, padX = 16, padY = 16;
        const stepX = (w - padX * 2) / Math.max(1, vals.length - 1);

        const pts = vals.map((v, i) => {
            const x = padX + i * stepX;
            const y = h - padY - ((v / maxVal) * (h - padY * 2));
            return { x, y, v, lbl: series[i]?.label || "" };
        });

        const linePath = pts.map((p, i) => `${i === 0 ? "M" : "L"} ${p.x.toFixed(1)} ${p.y.toFixed(1)}`).join(" ");
        const areaPath = `${linePath} L ${pts[pts.length - 1].x.toFixed(1)} ${(h - padY).toFixed(1)} L ${pts[0].x.toFixed(1)} ${(h - padY).toFixed(1)} Z`;

        const latest = vals[vals.length - 1] || 0;
        const prev = vals[vals.length - 2] || 0;
        const delta = latest - prev;
        const trendColor = delta >= 0 ? "#10b981" : "#ef4444";

        return `
            <div style="display:flex; justify-content:space-between; align-items:baseline; margin-bottom:6px; padding:0 4px;">
                <div>
                    <span style="font-size:10.5px; color:#64748b; font-weight:700;">TODAY LIVE</span>
                    <div style="font-size:22px; font-weight:800; line-height:1.1;">${latest}</div>
                </div>
                <span style="font-size:11.5px; font-weight:800; color:${trendColor}; background:${trendColor}18; padding:3px 9px; border-radius:999px;">
                    ${delta >= 0 ? "▲ +" : "▼ "}${delta} vs yesterday
                </span>
            </div>
            <svg viewBox="0 0 ${w} ${h + 18}" style="width:100%; height:auto; display:block;">
                <defs>
                    <linearGradient id="zv59AreaGrad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stop-color="${trendColor}" stop-opacity="0.35"/>
                        <stop offset="100%" stop-color="${trendColor}" stop-opacity="0.02"/>
                    </linearGradient>
                </defs>
                <line x1="${padX}" y1="${padY}" x2="${w - padX}" y2="${padY}" stroke="rgba(148,163,184,0.2)" stroke-dasharray="3 3"/>
                <line x1="${padX}" y1="${h / 2}" x2="${w - padX}" y2="${h / 2}" stroke="rgba(148,163,184,0.2)" stroke-dasharray="3 3"/>
                <line x1="${padX}" y1="${h - padY}" x2="${w - padX}" y2="${h - padY}" stroke="rgba(148,163,184,0.28)"/>
                <path d="${areaPath}" fill="url(#zv59AreaGrad)"/>
                <path d="${linePath}" fill="none" stroke="${trendColor}" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>
                ${pts.map(p => `
                    <circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="3.4" fill="${trendColor}" stroke="#ffffff" stroke-width="1.5"/>
                    <text x="${p.x.toFixed(1)}" y="${h + 10}" text-anchor="middle" font-size="9" font-weight="700" fill="#64748b">${p.lbl}</text>
                `).join("")}
            </svg>
        `;
    }

    function renderBarBreakdown(objMap, labelDict) {
        const entries = Object.entries(objMap || {}).sort((a, b) => (b[1] || 0) - (a[1] || 0));
        if (!entries.length) return `<div style="font-size:12px; color:#64748b; padding:4px 0;">Collecting live events from this update...</div>`;
        const maxV = Math.max(1, ...entries.map(e => Number(e[1] || 0)));
        return entries.slice(0, 8).map(([k, v]) => {
            const pct = Math.max(4, Math.round((Number(v || 0) / maxV) * 100));
            const label = (labelDict && labelDict[k]) || k;
            return `
                <div class="zv59-bar-row">
                    <div class="zv59-bar-head"><span>${escapeHtml(label)}</span><strong>${v}</strong></div>
                    <div class="zv59-bar-track"><div class="zv59-bar-fill" style="width:${pct}%;"></div></div>
                </div>
            `;
        }).join("");
    }

