        const fromTs = userDocData.lastActiveAt?.toMillis?.() || 0;
        if (fromTs > 1000000000000) return fromTs;

        const fromUpd = userDocData.updatedAt?.toMillis?.() || 0;
        if (fromUpd > 1000000000000) return fromUpd;

