    // Ensure loadMessagesFromFirestore preserves the REAL `d.delivered` boolean from Firestore
    loadMessagesFromFirestore = function (recipientId) {
        const msgContainer = document.getElementById("activeChatMessages");
        if (!msgContainer) return;

        if (activeMessagesUnsubscribe) {
            activeMessagesUnsubscribe();
            activeMessagesUnsubscribe = null;
        }

        const myUid = auth?.currentUser?.uid || "local";
        const chatId = myUid < recipientId ? `${myUid}_${recipientId}` : `${recipientId}_${myUid}`;
        const cacheKey = `zorenoDmCache_${chatId}`;

        let cachedMsgs = [];
        try { cachedMsgs = JSON.parse(localStorage.getItem(cacheKey) || "[]"); } catch (e) { cachedMsgs = []; }
        evaluateStrangerAntiSpamLock(cachedMsgs, myUid, recipientId);
        renderDmMessagesListToDOM(chatId, cachedMsgs, myUid);

        if (!db || !auth?.currentUser) return;

        activeMessagesUnsubscribe = db.collection("chats").doc(chatId).collection("messages")
            .onSnapshot(snapshot => {
                const docs = snapshot.docs.slice().sort((a, b) => {
                    const ta = a.data().timestampMs || a.data().createdAt?.toMillis?.() || 0;
                    const tb = b.data().timestampMs || b.data().createdAt?.toMillis?.() || 0;
                    return ta - tb;
                });

                const unseenRefs = [];
                const freshList = docs.map(doc => {
                    const d = doc.data();
                    if (d.senderId !== myUid && !d.seen) unseenRefs.push(doc.ref);
                    return {
                        id: doc.id,
                        senderId: d.senderId,
                        text: d.text || "",
                        imageData: d.imageData || "",
                        reaction: d.reaction || "",
                        timeLabel: d.timeLabel || "Now",
                        timestampMs: d.timestampMs || d.createdAt?.toMillis?.() || 0,
                        delivered: d.senderId !== myUid ? true : (d.delivered === true || d.seen === true),
                        seen: d.senderId !== myUid ? true : (d.seen === true)
                    };
                });

                try { localStorage.setItem(cacheKey, JSON.stringify(freshList.slice(-60))); } catch (e) {}
                evaluateStrangerAntiSpamLock(freshList, myUid, recipientId);
                renderDmMessagesListToDOM(chatId, freshList, myUid);
                markDmChatAsRead(recipientId);

                if (unseenRefs.length > 0) {
                    const batch = db.batch();
                    unseenRefs.forEach(ref => batch.update(ref, { seen: true, delivered: true }));
                    batch.commit().catch(() => {});
                }
            });
    };

