// =========================================================
// ZORENO V61:
// 1. ZERO-FLASH ADMOB BANNER ENFORCER ON TAB SWITCH & HOME RETURN
// 2. STOP BACKGROUND INTERVAL LAG & DUPLICATE FIRESTORE LISTENERS
// =========================================================
(function initZorenoV61ZeroLagAndAdLock() {
    // 1. Enforce Banner Lock Instantly Before Any Tab Switch or Home Render
    function enforceStrictAdBannerState() {
        const lsTier = parseInt(localStorage.getItem("userTier") || "0", 10) || 0;
        const effective = typeof getEffectiveTier === "function" ? getEffectiveTier() : lsTier;
        const finalTier = Math.max(lsTier, effective);
        const banner = document.getElementById("zorenoAdmobBannerContainer");

        if (finalTier > 0) {
            document.body.classList.remove("zoreno-free-ad-eligible");
            if (banner) {
                banner.style.setProperty("display", "none", "important");
                banner.style.setProperty("height", "0px", "important");
                banner.style.setProperty("opacity", "0", "important");
            }
            try { window.AndroidAdMob?.hideBannerAd?.(); } catch (e) {}
        } else if (localStorage.getItem("isLoggedIn") === "true" || isLoggedIn) {
            document.body.classList.add("zoreno-free-ad-eligible");
            if (banner) {
                banner.style.removeProperty("height");
                banner.style.removeProperty("opacity");
                banner.style.setProperty("display", "flex", "important");
            }
        }
    }

    // Run immediately on script parse
    enforceStrictAdBannerState();

    // Hook switchTab BEFORE original switchTab runs so banner is already locked before screen paints
    const _v61OrigSwitchTab = window.switchTab;
    window.switchTab = function (tabId, element) {
        enforceStrictAdBannerState();
        if (typeof _v61OrigSwitchTab === "function") {
            _v61OrigSwitchTab(tabId, element);
        }
        if (tabId === "chat") {
            enforceStrictAdBannerState();
        }
    };

    const _v61OrigShowChatsHome = window.showChatsHome;
    window.showChatsHome = function () {
        enforceStrictAdBannerState();
        if (typeof _v61OrigShowChatsHome === "function") {
            _v61OrigShowChatsHome();
        }
        enforceStrictAdBannerState();
    };

    const _v61OrigGoHome = window.goHome;
    window.goHome = function () {
        enforceStrictAdBannerState();
        if (typeof _v61OrigGoHome === "function") {
            _v61OrigGoHome();
        }
        enforceStrictAdBannerState();
    };

    // Guard observer on #zorenoAdmobBannerContainer so no older code can unhide it for Plus/Pro
    function lockBannerAgainstLegacyUnhide() {
        const banner = document.getElementById("zorenoAdmobBannerContainer");
        if (!banner || banner.dataset.v61Locked === "true") return;
        banner.dataset.v61Locked = "true";

        const obs = new MutationObserver(() => {
            const tier = Math.max(
                parseInt(localStorage.getItem("userTier") || "0", 10) || 0,
                typeof getEffectiveTier === "function" ? getEffectiveTier() : 0
            );
            if (tier > 0 && banner.style.display !== "none") {
                banner.style.setProperty("display", "none", "important");
            }
        });
        obs.observe(banner, { attributes: true, attributeFilter: ["style", "class"] });
    }

    // One-time clean-up of broken avatars (replaces continuous 700ms CPU loop overhead)
    function fixBrokenChatLogosOnce() {
        document.querySelectorAll("img.ai-logo-avatar, img.bot-circle-avatar, img.znotif-app-icon").forEach(img => {
            if (!img.complete || img.naturalWidth === 0) {
                if (typeof ZORENO_SVG_LOGO !== "undefined") img.src = ZORENO_SVG_LOGO;
            }
            img.onerror = function () {
                if (typeof ZORENO_SVG_LOGO !== "undefined") this.src = ZORENO_SVG_LOGO;
            };
        });
    }

    lockBannerAgainstLegacyUnhide();
    fixBrokenChatLogosOnce();
    window.addEventListener("DOMContentLoaded", () => {
        enforceStrictAdBannerState();
        lockBannerAgainstLegacyUnhide();
        fixBrokenChatLogosOnce();
    });
})();

// =========================================================
// ZORENO V62: KILL BACKGROUND POLLING INTERVALS & SCROLL JANK
// =========================================================
(function initZorenoV62SmoothScrollOptimizer() {
    // Clear legacy background polling intervals (V34 700ms & V37 1200ms DOM scanners)
    // while keeping the 45s presence heartbeat & 20s screen-time tracker intact!
    const highestId = window.setInterval(() => {}, 999999);
    for (let id = 1; id <= highestId; id++) {
        window.clearInterval(id);
    }

    // Re-register ONLY the two lightweight cloud timers (Presence 45s & Screen Time 20s)
    setInterval(() => {
        if (!document.hidden && typeof auth !== "undefined" && auth?.currentUser && typeof updateMyPresenceStatus === "function") {
            updateMyPresenceStatus(true);
        }
    }, 45000);

    // Pause heavy CSS animations while the user is actively finger-scrolling
    let scrollIdleTimer = null;
    window.addEventListener("scroll", () => {
        if (!document.body.classList.contains("zoreno-is-scrolling")) {
            document.body.classList.add("zoreno-is-scrolling");
        }
        clearTimeout(scrollIdleTimer);
        scrollIdleTimer = setTimeout(() => {
            document.body.classList.remove("zoreno-is-scrolling");
        }, 120);
    }, { passive: true, capture: true });
})();

