    function getLiveDailyAiEnergyStats() {
        const tier = typeof getEffectiveTier === "function" ? getEffectiveTier() : 0;
        const maxLimit = tier >= 2 ? 90 : tier === 1 ? 50 : 10;
        const todayKey = typeof getTodayLocalMidnightKey === "function"
            ? getTodayLocalMidnightKey()
            : new Date().toISOString().slice(0, 10);

        let used = 0;
        try {
            const rawObj = JSON.parse(localStorage.getItem("zorenoDailyAiUsage") || "{}");
            if (rawObj && rawObj.date === todayKey) used = Number(rawObj.count || 0);
        } catch (e) {}

        if (used === 0) {
            const fallbackKeys = [`zorenoAiUsed_${todayKey}`, "zorenoDailyMsgCount", "dailyAiCount"];
            for (const k of fallbackKeys) {
                const v = parseInt(localStorage.getItem(k) || "0", 10);
                if (v > 0) { used = v; break; }
            }
        }
        if (used === 0 && Array.isArray(aiChatMessagesList)) {
            const startOfToday = new Date();
            startOfToday.setHours(0, 0, 0, 0);
            used = aiChatMessagesList.filter(m => (m.timestampMs || 0) >= startOfToday.getTime()).length;
        }

        const pct = Math.min(100, Math.round((used / Math.max(1, maxLimit)) * 100));
        return { pct, tier };
    }

