// =========================================================
// ZORENO V74:
// 1. CLEAN NON-COLLIDING PERSONAL INFO ROWS (37891.png FIX)
// 2. UNIVERSAL SMOOTH BOOK-FOLD CLOSE ANIMATION FOR ALL CARDS & SUB-PAGES
// =========================================================
(function initZorenoV74CardAnimationsAndPersonalInfoFix() {
    // ---------------------------------------------------------
    // 1. UNIVERSAL SMOOTH ANIMATED CLOSE HELPER (200MS BOOK-FOLD)
    // ---------------------------------------------------------
    window.zorenoSmoothCloseEl = function (el, onAfterHide) {
        if (!el || el.style.display === "none") {
            if (typeof onAfterHide === "function") onAfterHide();
            return;
        }
        if (el.classList.contains("zv74-closing")) return;
        el.classList.add("zv74-closing");
        setTimeout(() => {
            el.classList.remove("zv74-closing");
            el.style.display = "none";
            if (typeof onAfterHide === "function") onAfterHide();
        }, 195);
    };

    const OVERLAY_SELECTOR = ".custom-modal-overlay, #zorenoV70Modal, #zorenoV70FinalDeleteConfirm, #zorenoV71EnergyModal, #zorenoV71SubModal, #zorenoV73PersonalModal, #zorenoV59AdminLockModal";

    // Intercept Close Buttons (X / Cancel / Back) & Backdrop Taps to Play Smooth Fold-Out Animation
    document.addEventListener("click", (e) => {
        // A. Tapping outside card on dark backdrop smoothly closes the modal
        if (e.target && e.target.matches(OVERLAY_SELECTOR)) {
            if (e.target.id === "zorenoV71SubModal" && typeof closeV71SubModal === "function") {
                closeV71SubModal();
            } else {
                zorenoSmoothCloseEl(e.target);
            }
            return;
        }

        // B. Intercept simple inline close buttons (style.display='none') so they animate out smoothly!
        const closeBtn = e.target?.closest?.(".zv70-close-x, .modal-close-btn, .zloc66-close-btn");
        if (!closeBtn) return;
        const inlineOc = closeBtn.getAttribute("onclick") || "";
        if (/style\.display\s*=\s*['"]none['"]/i.test(inlineOc) && !inlineOc.includes("zorenoSmoothCloseEl")) {
            const parentOverlay = closeBtn.closest(OVERLAY_SELECTOR);
            if (parentOverlay) {
                e.preventDefault();
                e.stopImmediatePropagation();
                zorenoSmoothCloseEl(parentOverlay);
            }
        }
    }, true);

    // Upgrade Named Close Functions to Use Smooth Book-Fold Close Animation
    const _v74OrigClosePI = window.closeV73PersonalInfoModal;
    window.closeV73PersonalInfoModal = function () {
        const m = document.getElementById("zorenoV73PersonalModal");
        if (m) zorenoSmoothCloseEl(m);
        else if (typeof _v74OrigClosePI === "function") _v74OrigClosePI();
    };

    const _v74OrigCloseV71Sub = window.closeV71SubModal;
    window.closeV71SubModal = function () {
        const m = document.getElementById("zorenoV71SubModal");
        if (m && m.style.display !== "none") {
            zorenoSmoothCloseEl(m, () => {
                if (typeof _v74OrigCloseV71Sub === "function") _v74OrigCloseV71Sub();
            });
        } else if (typeof _v74OrigCloseV71Sub === "function") {
            _v74OrigCloseV71Sub();
        }
    };

    window.closeZorenoAppearanceScreen = function () {
        const s = document.getElementById("zorenoAppearanceScreen");
        if (s) zorenoSmoothCloseEl(s);
    };

    window.closeZorenoPrivacyScreen = function () {
        const s = document.getElementById("zorenoPrivacyScreen");
        if (s) zorenoSmoothCloseEl(s);
    };

    window.closeTokoIntelligenceDashboard = function () {
        const s = document.getElementById("zorenoV59IntelScreen");
        if (s) zorenoSmoothCloseEl(s);
    };

    // Smoothly close Security & Sign-in Fullscreen via Back Button too
    document.addEventListener("click", (e) => {
        const backBtn = e.target?.closest?.("#zorenoV71SecurityModal .zt47-back");
        if (backBtn) {
            e.preventDefault();
            e.stopImmediatePropagation();
            const m = document.getElementById("zorenoV71SecurityModal");
            if (m) zorenoSmoothCloseEl(m);
        }
    }, true);

    // ---------------------------------------------------------
    // 2. FIX PERSONAL INFORMATION ROW OVERLAP (37891.png)
    // ---------------------------------------------------------
    const _v74OrigOpenPI = window.openV73PersonalInfoModal;
    window.openV73PersonalInfoModal = function () {
        if (typeof _v74OrigOpenPI === "function") _v74OrigOpenPI();
        const modal = document.getElementById("zorenoV73PersonalModal");
        if (!modal) return;

        modal.querySelectorAll(".zv73-info-row").forEach(row => {
            const lblBox = row.querySelector(".zv73-row-lbl");
            const valSpan = row.querySelector(".zv73-row-val");
            if (!lblBox || !valSpan) return;

            const isAccent = valSpan.classList.contains("accent");
            const valText = valSpan.textContent || "";
            const subP = lblBox.querySelector("p");
            if (subP) {
                subP.className = "zv74-val-line" + (isAccent ? " accent" : "");
                subP.textContent = valText;
            }
            valSpan.remove();
        });
    };
})();

