// =========================================================
(function initZorenoV75GalaxyProfileAndAvatarViewer() {
    function injectGalaxyOrbitAndViewerHook() {
        const ring = document.querySelector("#friendProfileScreen .fp-avatar-ring");
        if (!ring) return;

        if (!ring.querySelector(".zv75-galaxy-stage")) {
            ring.insertAdjacentHTML("afterbegin", `
                <div class="zv75-galaxy-stage"><div class="zv75-galaxy-ring"></div></div>
                <span class="zv75-sparkle s1">✦</span>
                <span class="zv75-sparkle s2">✦</span>
                <span class="zv75-avatar-status-dot"></span>
            `);
        }

        if (ring.dataset.v75ViewerBound !== "true") {
            ring.dataset.v75ViewerBound = "true";
            ring.addEventListener("click", (e) => {
                e.stopPropagation();
                const imgEl = ring.querySelector("img");
                const src = imgEl?.getAttribute("src") || "";
                const name = document.getElementById("fpFullName")?.textContent?.trim() || "Profile Photo";
                const uname = document.getElementById("fpUsernameSub")?.textContent?.trim() || "";
                if (src) window.openZorenoAvatarViewer(src, name, uname);
            });
        }
    }

    window.openZorenoAvatarViewer = function (imgSrc, displayName, usernameStr) {
        let lb = document.getElementById("zorenoV75AvatarLightbox");
        if (!lb) {
            lb = document.createElement("div");
            lb.id = "zorenoV75AvatarLightbox";
            lb.addEventListener("click", (e) => {
                if (e.target === lb) window.closeZorenoAvatarViewer();
            });
            document.body.appendChild(lb);
        }

        lb.innerHTML = `
            <button type="button" class="zv75-lb-close" onclick="closeZorenoAvatarViewer()" aria-label="Close">
                <i class="fa-solid fa-xmark"></i>
            </button>
            <div class="zv75-lb-card" onclick="event.stopPropagation()">
                <div class="zv75-lb-img-frame">
                    <img src="${escapeHtml(imgSrc)}" alt="${escapeHtml(displayName)}">
                </div>
                <div class="zv75-lb-meta">
                    <h4>${escapeHtml(displayName)}</h4>
                    ${usernameStr ? `<p>${escapeHtml(usernameStr)}</p>` : ""}
                </div>
            </div>
        `;
        lb.style.display = "flex";
    };

    window.closeZorenoAvatarViewer = function () {
        const lb = document.getElementById("zorenoV75AvatarLightbox");
        if (!lb) return;
        if (typeof window.zorenoSmoothCloseEl === "function") {
            window.zorenoSmoothCloseEl(lb);
        } else {
            lb.style.display = "none";
        }
    };

    // Hook into both Friend Profile & AI Profile openers
    const _v75OrigOpenFp = window.openFriendProfileScreen;
    if (typeof _v75OrigOpenFp === "function") {
        window.openFriendProfileScreen = function (...args) {
            const res = _v75OrigOpenFp.apply(this, args);
            injectGalaxyOrbitAndViewerHook();
            return res;
        };
    }

    const _v75OrigSyncFp = window.syncFriendProfileViewDOM;
    if (typeof _v75OrigSyncFp === "function") {
        window.syncFriendProfileViewDOM = function (...args) {
            const res = _v75OrigSyncFp.apply(this, args);
            injectGalaxyOrbitAndViewerHook();
            return res;
        };
    }

    // Hardware Back closes Avatar Lightbox cleanly
    const _v75OrigHwBack = window.handleZorenoHardwareBack;
    window.handleZorenoHardwareBack = function () {
        const lb = document.getElementById("zorenoV75AvatarLightbox");
        if (lb && lb.style.display !== "none") {
            window.closeZorenoAvatarViewer();
            return true;
        }
        return typeof _v75OrigHwBack === "function" ? _v75OrigHwBack() : false;
    };

    injectGalaxyOrbitAndViewerHook();
    window.addEventListener("DOMContentLoaded", injectGalaxyOrbitAndViewerHook);
})();


