// 1. UPWARD DUST/SMOKE DELETE + 48H RETENTION
// 2. COMPLETE EDIT PROFILE (AUTO-INTERCEPTS OLD #profileScreen & HOME PENCIL)
// 3. PUBLIC / FRIENDS / PRIVATE CONTROLS + EXTENDED FRIEND PROFILE + GREEN TICK
// 4. AI FACE VERIFICATION (LIVENESS MOTION + ANTI-BOT + 12+ AGE CHECK)
// =========================================================
(function initZorenoV76Compact() {
    const RETENTION_48H = 48 * 60 * 60 * 1000;

    // 1. UPWARD DUST & SMOKE DELETE ANIMATION
    function dustFloatUp(el) {
        return new Promise(res => {
            if (!el) return res();
            const r = el.getBoundingClientRect();
            if (r.width <= 0 || r.height <= 0) return res();
            const right = el.classList.contains("clean-right-bubble");
            const dark = document.body.classList.contains("dark-mode");
            const cols = right ? ["#6366f1","#7c3aed","#38bdf8","#c4b5fd"] : (dark ? ["#64748b","#94a3b8","#cbd5e1"] : ["#fff","#cbd5e1","#c4b5fd","#94a3b8"]);
            const dpr = Math.min(window.devicePixelRatio || 1, 2);
            const cv = document.createElement("canvas");
            cv.style.cssText = "position:fixed;inset:0;width:100vw;height:100dvh;pointer-events:none;z-index:2147483647;";
            cv.width = Math.round(window.innerWidth * dpr); cv.height = Math.round(window.innerHeight * dpr);
            document.body.appendChild(cv);
            const ctx = cv.getContext("2d"); ctx.scale(dpr, dpr);
            const pts = Array.from({ length: 135 }, (_, i) => {
                const sm = i >= 118, ry = Math.random();
                return { x: r.left + Math.random()*r.width, y: r.top + ry*r.height, vx: (Math.random()-.5)*1.1, vy: -(1.4 + Math.random()*2.6), s: sm ? 11+Math.random()*12 : 1.6+Math.random()*2.6, a: sm ? .26 : .9, d: ry*200 + Math.random()*70, l: 700+Math.random()*320, p: Math.random()*6.28, c: sm ? "#cbd5e1" : cols[i % cols.length], sm };
            });
            el.classList.add("msg-wind-erode-up");
            navigator.vibrate?.([12, 18, 10]);
            const t0 = performance.now();
            (function loop(now) {
                const e = now - t0; ctx.clearRect(0, 0, window.innerWidth, window.innerHeight); let live = 0;
                for (const p of pts) {
                    if (e < p.d) { live++; continue; }
                    const age = e - p.d; if (age >= p.l) continue; live++;
                    const k = age / p.l; p.x += p.vx + Math.sin(age*.012 + p.p)*.55; p.y += p.vy*(1 + k*.45); p.vy -= .024;
                    ctx.globalAlpha = Math.max(0, p.a * (1 - k*k)); ctx.fillStyle = p.c;
                    ctx.beginPath(); ctx.arc(p.x, p.y, p.sm ? p.s*(1+k*.7) : Math.max(.6, p.s*(1-k*.45)), 0, 6.283); ctx.fill();
                }
                ctx.globalAlpha = 1;
                if (e < 1020 && live) requestAnimationFrame(loop); else { cv.remove(); res(); }
            })(t0);
        });
    }

    window.executeHoldMenuDelete = async function () {
        const m = window._currentHoldMenuMeta; closeZorenoHoldMenu?.(); if (!m) return;
        const b = m.bubbleEl || (m.msgId ? document.querySelector(`#activeChatMessages [data-msg-id="${m.msgId}"]`) : null);
        if (b) await dustFloatUp(b);
        if (m.isAi && aiChatMessagesList?.[m.aiIdx]) {
            const rem = aiChatMessagesList.splice(m.aiIdx, 1)[0];
            localStorage.setItem("zorenoAiChatStream", JSON.stringify(aiChatMessagesList));
            renderAiChatStream?.();
            if (db && auth?.currentUser && rem?.timestampMs) db.collection("users").doc(auth.currentUser.uid).collection("chats").where("timestampMs","==",rem.timestampMs).get().then(s => s.forEach(d => d.ref.delete())).catch(()=>{});
        } else if (m.msgId && m.chatId) {
            deletedMsgsMap[m.msgId] = true; localStorage.setItem("zorenoDeletedMsgsMap", JSON.stringify(deletedMsgsMap));
            b?.closest(".msg-row-with-avatar")?.remove();
            if (db) { const col = currentChatIsGroup ? "groups" : "chats", now = Date.now(); db.collection(col).doc(m.chatId).collection("messages").doc(m.msgId).set({ deleted: true, deletedAtMs: now, retainUntilMs: now + RETENTION_48H }, { merge: true }).catch(()=>{}); }
        }
        showCompactGlassToast?.("", "Message deleted");
    };

    // 2. EDIT PROFILE DATA + PRESETS (INDIAN & INTERNATIONAL)
    const P = {
        interests: ["Study","AI","Technology","Science","Maths","Coding","Startups","Design","Finance","Gaming","Movies","Fitness","Music"],
        hobbies: ["Reading","Coding","Gym","Video Editing","Painting","Photography","Gaming","Music","Writing","Cricket","Chess","DIY"],
        skills: ["HTML/CSS","JavaScript","Kotlin","Python","Flutter","Firebase","UI/UX","Video Editing","Graphic Design","AI Prompting"],
        languages: ["English","Hindi","Spanish","French","German","Arabic","Bengali","Tamil","Telugu","Marathi","Japanese","Korean"],
        eduLevel: ["","School (Class 6-10)","High School (Class 11-12)","Diploma","Undergraduate","Postgraduate","Doctorate (PhD)","Other"],
        qualification: ["","CBSE","ICSE / ISC","State Board","IB Diploma","IGCSE","A-Levels","US High School (AP)","B.Tech / B.E.","MBBS","B.Sc","B.Com","BA","BCA","BBA","LLB","M.Tech","MS","MBA","M.Sc","MCA","PhD","Other"],
        gender: ["","Male","Female","Non-Binary","Prefer not to say"],
        marital: ["","Unmarried","Married","Prefer not to say"],
        blood: ["","A+","A-","B+","B-","O+","O-","AB+","AB-"],
        category: ["","General","OBC","SC","ST","EWS","Prefer not to say"],
        emp: ["","Student","Founder","Freelancer","Employed","Intern","Self-Employed","Exam Prep"],
        mode: ["","Regular","Online","Distance","Hybrid"]
    };

    const defExt = () => ({
        interests: ["Study","AI"], hobbies: ["Reading"], dob: "", gender: "", marital: "", blood: "", nationality: "Indian", religion: "", category: "",
        languages: ["English","Hindi"], country: "India", state: "", city: "", pin: "",
        eduLevel: "", qualification: "", curEdu: "", institution: "", passYear: "", eduMode: "Regular",
        emp: "Student", profession: "", org: "", exp: "", skills: [],
        social: { instagram: "", facebook: "", linkedin: "", github: "", youtube: "" },
        vis: { about: "public", personal: "friends", location: "friends", education: "public", work: "public", social: "public" }
    });

    function loadLocalExt() {
        const d = defExt();
        try { const r = JSON.parse(localStorage.getItem("zorenoExtendedProfile") || "{}"); return { ...d, ...r, social: { ...d.social, ...(r.social||{}) }, vis: { ...d.vis, ...(r.vis||{}) } }; } catch { return d; }
    }

    let draft = loadLocalExt(), tab = "edit", dName = "", dUser = "", dBio = "";
    const esc = s => (typeof escapeHtml === "function" ? escapeHtml(s) : String(s||"").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])));
    const visBtn = k => {
        const v = draft.vis[k] || "public";
        const m = v === "private" ? ["private","fa-lock","Private"] : v === "friends" ? ["friends","fa-user-group","Friends"] : ["public","fa-earth-asia","Public"];
        return `<button type="button" class="zp76-vis ${m[0]}" onclick="zp76Vis('${k}')"><i class="fa-solid ${m[1]}"></i>${m[2]}</button>`;
    };
    const sel = (k, arr, cur) => `<select class="zp76-inp" onchange="zp76Set('${k}',this.value)">${(arr.includes(cur)?arr:[...arr,cur]).map(o=>`<option value="${esc(o)}" ${o===cur?"selected":""}>${o?esc(o):"Select..."}</option>`).join("")}</select>`;
    const inp = (k, v, ph, t="text") => `<input type="${t}" class="zp76-inp" value="${esc(v)}" oninput="zp76Set('${k}',this.value)" placeholder="${ph}">`;
    const chips = (k, pre, lbl) => {
        const on = Array.isArray(draft[k]) ? draft[k] : [];
        return `<div class="zp76-chips">${Array.from(new Set([...pre,...on])).map(x=>`<button type="button" class="zp76-chip ${on.includes(x)?"on":""}" onclick="zp76Chip('${k}','${esc(x.replace(/['"]/g,""))}')">${esc(x)}${on.includes(x)?" ✓":""}</button>`).join("")}<button type="button" class="zp76-chip" style="border-style:dashed;" onclick="zp76AddChip('${k}','${lbl}')">+ Add</button></div>`;
    };

    window.zp76Vis = k => { const o = ["public","friends","private"]; draft.vis[k] = o[(o.indexOf(draft.vis[k]||"public")+1)%3]; renderEdit(); };
    window.zp76Chip = (k, v) => { draft[k] = draft[k] || []; const i = draft[k].indexOf(v); i >= 0 ? draft[k].splice(i,1) : draft[k].push(v); renderEdit(); };
    window.zp76AddChip = (k, l) => { const v = (prompt(`Add ${l}:`)||"").replace(/['"]/g,"").trim().slice(0,24); if (!v) return; draft[k] = draft[k] || []; if (!draft[k].includes(v)) draft[k].push(v); renderEdit(); };
    window.zp76Set = (k, v) => { if (k==="_n") dName=v; else if (k==="_u") dUser=v; else if (k==="_b") { dBio=v.slice(0,150); const c=document.getElementById("zp76BC"); if(c) c.textContent=`${dBio.length}/150`; } else if (k.startsWith("s.")) draft.social[k.slice(2)]=v; else draft[k]=v; };
    window.zp76Tab = t => { if (t==="security") { window.openV71SecurityModal?.(); return; } tab = t; renderEdit(); };
    window.zp76Close = () => { const s = document.getElementById("zorenoV76Profile"); if (s) (window.zorenoSmoothCloseEl ? zorenoSmoothCloseEl(s) : s.style.display="none"); };

    window.zp76Save = async function () {
        const cn = dName.trim() || userName || "Student";
        let cu = dUser.trim().replace(/\s+/g,"").toLowerCase(); if (cu && !cu.startsWith("@")) cu = "@"+cu; cu = cu || currentUsername || "@student";
        const cb = dBio.trim().slice(0,150);
        userName = cn; currentUsername = cu;
        localStorage.setItem("userName", cn); localStorage.setItem("zorenoUsername", cu); localStorage.setItem("userBio", cb);
        localStorage.setItem("zorenoExtendedProfile", JSON.stringify(draft));
        if (db && auth?.currentUser) db.collection("users").doc(auth.currentUser.uid).set({ name: cn, username: cu, bio: cb, extendedProfile: draft, updatedAt: firebase.firestore.FieldValue.serverTimestamp() }, { merge: true }).catch(()=>{});
        updateProfileUI?.(); showCompactGlassToast?.("", "Profile saved ✓"); zp76Close();
    };

    window.zp76Preview = () => {
        const uid = auth?.currentUser?.uid || "self";
        currentChatIsGroup = false; currentChatUserId = uid;
        currentChatUserMeta = { uid, name: dName||userName, username: dUser||currentUsername, avatar: getSafeAvatar(userAvatarUrl, dName||userName), bio: dBio, userTier: typeof getEffectiveTier==="function"?getEffectiveTier():0, isOnline: true, lastActiveAtMs: Date.now(), isAccountVerified: localStorage.getItem("zorenoMyVerified")==="true", extendedProfile: draft, _self: true };
        openFriendProfileScreen?.();
    };

    function renderEdit() {
        let scr = document.getElementById("zorenoV76Profile");
        if (!scr) { scr = document.createElement("div"); scr.id = "zorenoV76Profile"; document.body.appendChild(scr); }
        const e = draft, av = getSafeAvatar(userAvatarUrl, dName||userName), ver = localStorage.getItem("zorenoMyVerified")==="true";
        const pct = Math.round(([dName,dUser,dBio,e.interests.length,e.hobbies.length,e.dob,e.gender,e.city||e.state,e.eduLevel||e.qualification,e.institution,e.profession||e.emp,e.skills.length,Object.values(e.social).some(Boolean)].filter(Boolean).length / 13) * 100);

        let body = "";
        if (tab === "privacy") {
            const list = [["about","About You (Bio, Interests, Hobbies)"],["personal","Personal Details (DOB, Gender, Blood...)"],["location","Location & Languages"],["education","Education & Qualification"],["work","Work, Profession & Skills"],["social","Social Links"]];
            body = `<div class="zp76-card"><div class="zp76-head"><h4><span class="zp76-ico"><i class="fa-regular fa-eye"></i></span>Profile Visibility</h4></div><p style="font-size:11.5px;color:#64748b;margin:0 0 8px;">Tap any pill: <b>Public</b> (all), <b>Friends</b> (friends only), or <b>Private</b> (only you).</p>${list.map(([k,n])=>`<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;padding:8px 0;border-bottom:1px solid rgba(148,163,184,.16);"><span style="font-size:12.2px;font-weight:700;">${n}</span>${visBtn(k)}</div>`).join("")}</div>`;
        } else if (tab === "overview") {
            body = `<div class="zp76-card"><div class="zp76-head"><h4><span class="zp76-ico"><i class="fa-regular fa-id-badge"></i></span>Overview</h4><button type="button" class="zp76-prev-btn" style="height:28px;" onclick="zp76Preview()">Live View</button></div><div class="zp76-kv"><div><span>Name</span><strong>${esc(dName||"-")}</strong></div><div><span>Username</span><strong>${esc(dUser||"-")}</strong></div><div><span>Education</span><strong>${esc(e.qualification||e.eduLevel||"-")}</strong></div><div><span>Institution</span><strong>${esc(e.institution||"-")}</strong></div><div><span>Profession</span><strong>${esc(e.profession||e.emp||"-")}</strong></div><div><span>Location</span><strong>${esc([e.city,e.state,e.country].filter(Boolean).join(", ")||"-")}</strong></div></div></div>`;
        } else {
            body = `
            <div class="zp76-card"><div class="zp76-head"><h4><span class="zp76-ico"><i class="fa-solid fa-user"></i></span>Basic Information</h4><span class="zp76-vis public" style="cursor:default;"><i class="fa-solid fa-earth-asia"></i>Public</span></div>
                <div class="zp76-f"><label>Full Name *</label>${inp("_n",dName,"Your full name")}</div>
                <div class="zp76-f"><label>Username *</label>${inp("_u",dUser,"@username")}</div>
            </div>
            <div class="zp76-card"><div class="zp76-head"><h4><span class="zp76-ico"><i class="fa-solid fa-quote-left"></i></span>About You</h4>${visBtn("about")}</div>
                <div class="zp76-f"><label><span>Bio</span><span id="zp76BC">${dBio.length}/150</span></label><textarea class="zp76-inp" rows="2" maxlength="150" oninput="zp76Set('_b',this.value)" placeholder="Write your bio...">${esc(dBio)}</textarea></div>
                <div class="zp76-f"><label>Interests</label>${chips("interests",P.interests,"Interest")}</div>
                <div class="zp76-f"><label>Hobbies</label>${chips("hobbies",P.hobbies,"Hobby")}</div>
            </div>
            <div class="zp76-card"><div class="zp76-head"><h4><span class="zp76-ico"><i class="fa-regular fa-id-card"></i></span>Personal Details</h4>${visBtn("personal")}</div>
                <div class="zp76-grid">
                    <div class="zp76-f"><label>Date of Birth</label>${inp("dob",e.dob,"","date")}</div>
                    <div class="zp76-f"><label>Gender</label>${sel("gender",P.gender,e.gender)}</div>
                    <div class="zp76-f"><label>Marital Status</label>${sel("marital",P.marital,e.marital)}</div>
                    <div class="zp76-f"><label>Blood Group</label>${sel("blood",P.blood,e.blood)}</div>
                    <div class="zp76-f"><label>Nationality</label>${inp("nationality",e.nationality,"Indian")}</div>
                    <div class="zp76-f"><label>Religion</label>${inp("religion",e.religion,"Optional")}</div>
                </div>
                <div class="zp76-f" style="margin-top:8px;"><label>Category</label>${sel("category",P.category,e.category)}</div>
            </div>
            <div class="zp76-card"><div class="zp76-head"><h4><span class="zp76-ico"><i class="fa-solid fa-location-dot"></i></span>Location & Languages</h4>${visBtn("location")}</div>
                <div class="zp76-grid">
                    <div class="zp76-f"><label>Country</label>${inp("country",e.country,"India")}</div>
                    <div class="zp76-f"><label>State</label>${inp("state",e.state,"State")}</div>
                    <div class="zp76-f"><label>City</label>${inp("city",e.city,"City")}</div>
                    <div class="zp76-f"><label>PIN / ZIP</label>${inp("pin",e.pin,"Optional")}</div>
                </div>
                <div class="zp76-f" style="margin-top:8px;"><label>Languages Known</label>${chips("languages",P.languages,"Language")}</div>
            </div>
            <div class="zp76-card"><div class="zp76-head"><h4><span class="zp76-ico"><i class="fa-solid fa-graduation-cap"></i></span>Education & Qualification</h4>${visBtn("education")}</div>
                <div class="zp76-grid">
                    <div class="zp76-f"><label>Level</label>${sel("eduLevel",P.eduLevel,e.eduLevel)}</div>
                    <div class="zp76-f"><label>Board / Degree</label>${sel("qualification",P.qualification,e.qualification)}</div>
                    <div class="zp76-f"><label>Class / Year</label>${inp("curEdu",e.curEdu,"e.g. Class 9 / 2nd Yr")}</div>
                    <div class="zp76-f"><label>Passing Year</label>${inp("passYear",e.passYear,"e.g. 2028")}</div>
                    <div class="zp76-f"><label>School / College</label>${inp("institution",e.institution,"Institute name")}</div>
                    <div class="zp76-f"><label>Mode</label>${sel("eduMode",P.mode,e.eduMode)}</div>
                </div>
            </div>
            <div class="zp76-card"><div class="zp76-head"><h4><span class="zp76-ico"><i class="fa-solid fa-briefcase"></i></span>Work & Professional</h4>${visBtn("work")}</div>
                <div class="zp76-grid">
                    <div class="zp76-f"><label>Status</label>${sel("emp",P.emp,e.emp)}</div>
                    <div class="zp76-f"><label>Role / Profession</label>${inp("profession",e.profession,"e.g. Developer")}</div>
                    <div class="zp76-f"><label>Organization</label>${inp("org",e.org,"Company / Brand")}</div>
                    <div class="zp76-f"><label>Experience</label>${inp("exp",e.exp,"e.g. 1 Year")}</div>
                </div>
                <div class="zp76-f" style="margin-top:8px;"><label>Skills</label>${chips("skills",P.skills,"Skill")}</div>
            </div>
            <div class="zp76-card"><div class="zp76-head"><h4><span class="zp76-ico"><i class="fa-solid fa-share-nodes"></i></span>Social Links</h4>${visBtn("social")}</div>
                <div class="zp76-f"><label>Instagram</label>${inp("s.instagram",e.social.instagram,"https://instagram.com/...")}</div>
                <div class="zp76-f"><label>Facebook</label>${inp("s.facebook",e.social.facebook,"https://facebook.com/...")}</div>
                <div class="zp76-f"><label>LinkedIn</label>${inp("s.linkedin",e.social.linkedin,"https://linkedin.com/in/...")}</div>
                <div class="zp76-f"><label>GitHub</label>${inp("s.github",e.social.github,"https://github.com/...")}</div>
                <div class="zp76-f"><label>YouTube</label>${inp("s.youtube",e.social.youtube,"https://youtube.com/@...")}</div>
            </div>`;
        }

        scr.innerHTML = `
            <div class="zp76-top">
                <button type="button" class="zt47-back" onclick="zp76Close()"><i class="fa-solid fa-arrow-left"></i></button>
                <div style="flex:1;min-width:0;"><h2 style="margin:0;font-size:18px;font-weight:800;">My Profile</h2><p style="margin:1px 0 0;font-size:10.5px;color:#64748b;font-weight:600;">Details, education & privacy</p></div>
                <button type="button" class="zp76-prev-btn" onclick="zp76Preview()"><i class="fa-regular fa-eye"></i> Preview</button>
            </div>
            <div class="zp76-body">
                <div class="zp76-card" style="padding:11px 12px;">
                    <div style="display:flex;align-items:center;gap:11px;margin-bottom:8px;">
                        <div style="position:relative;width:52px;height:52px;flex-shrink:0;cursor:pointer;" onclick="triggerZorenoAccountDpUpload?.(event)">
                            <img src="${esc(av)}" style="width:52px;height:52px;border-radius:50%;object-fit:cover;border:2px solid #8b5cf6;">
                            ${ver?`<span class="zp76-vtick" style="width:18px!important;height:18px!important;font-size:8.5px!important;"><i class="fa-solid fa-check"></i></span>`:""}
                            <span class="zv73-av-pen"><i class="fa-solid fa-camera"></i></span>
                        </div>
                        <div style="flex:1;min-width:0;"><div style="font-size:15px;font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${esc(dName||userName)}</div><div style="font-size:11.2px;color:#64748b;font-weight:600;">${esc(dUser||currentUsername)}</div></div>
                        <span style="font-size:11.2px;font-weight:800;color:#7c3aed;">${pct}%</span>
                    </div>
                    <div class="zv70-energy-track" style="margin:0;height:6.5px;"><div class="zv70-energy-fill" style="width:${Math.max(8,pct)}%;"></div></div>
                </div>
                <div class="zp76-tabs">
                    ${[["edit","Edit"],["overview","Overview"],["privacy","Privacy"],["security","Security"]].map(([k,l])=>`<button type="button" class="zp76-tab ${tab===k?"active":""}" onclick="zp76Tab('${k}')">${l}</button>`).join("")}
                </div>
                ${body}
            </div>
            <div class="zp76-foot">
                <button type="button" class="zv70-pill-glass" onclick="zp76Close()">Discard</button>
                <button type="button" class="zv70-pill-purple" style="height:44px;" onclick="zp76Save()"><i class="fa-solid fa-circle-check"></i> Save Profile</button>
            </div>`;
        scr.style.display = "flex";
    }

    async function openNewEditProfile() {
        tab = "edit"; dName = userName || localStorage.getItem("userName") || "";
        dUser = currentUsername || localStorage.getItem("zorenoUsername") || "";
        dBio = localStorage.getItem("userBio") || ""; draft = loadLocalExt();
        renderEdit();
        if (db && auth?.currentUser) {
            try {
                const doc = await db.collection("users").doc(auth.currentUser.uid).get();
                if (doc.exists) {
                    const d = doc.data() || {};
                    if (d.name) dName = d.name; if (d.username) dUser = d.username; if (typeof d.bio==="string") dBio = d.bio;
                    if (d.isAccountVerified) localStorage.setItem("zorenoMyVerified", "true");
                    if (d.extendedProfile) { const df = defExt(); draft = { ...df, ...d.extendedProfile, social: { ...df.social, ...(d.extendedProfile.social||{}) }, vis: { ...df.vis, ...(d.extendedProfile.vis||{}) } }; localStorage.setItem("zorenoExtendedProfile", JSON.stringify(draft)); }
                    renderEdit();
                }
            } catch {}
        }
    }

    // 100% RELIABLE INTERCEPT: Catch BOTH Function Calls AND Old #profileScreen Opening!
    window.openProfileScreen = window.openEditProfile = window.openMyProfile = openNewEditProfile;

    function watchLegacyProfileScreen() {
        const old = document.getElementById("profileScreen");
        if (!old || old.dataset.zp76Watched) return;
        old.dataset.zp76Watched = "1";
        const hijack = () => {
            if (window.getComputedStyle(old).display !== "none") {
                old.style.setProperty("display", "none", "important");
                old.classList.remove("active", "show");
                openNewEditProfile();
            }
        };
        new MutationObserver(hijack).observe(old, { attributes: true, attributeFilter: ["style", "class"] });
    }
    watchLegacyProfileScreen();
    window.addEventListener("DOMContentLoaded", watchLegacyProfileScreen);

    // Direct Click Catch on Home Top-Right Pencil Button (Backup!)
    document.addEventListener("click", (e) => {
        const btn = e.target?.closest?.("#chatListScreen button, #chatListScreen [onclick]");
        if (!btn) return;
        const oc = (btn.getAttribute("onclick") || "").toLowerCase();
        if (btn.querySelector(".fa-pen-to-square, .fa-edit, .fa-user-pen") || (oc.includes("profile") && !oc.includes("friend") && !oc.includes("ai"))) {
            e.preventDefault(); e.stopImmediatePropagation(); openNewEditProfile();
        }
    }, true);

    // 3. EXTENDED FRIEND PROFILE + PRIVACY FILTER + GREEN VERIFIED TICK EVERYWHERE
    const canSee = (v, fr, self) => self || !v || v === "public" || (v === "friends" && fr);
    const urlFix = u => /^https?:\/\//i.test(u.trim()) ? u.trim() : "https://" + u.trim();

    function paintFriendExtras(meta) {
        const scr = document.getElementById("friendProfileScreen"); if (!scr || !meta) return;
        const ring = scr.querySelector(".fp-avatar-ring");
        if (ring) { ring.querySelector(".zp76-vtick")?.remove(); if (meta.isAccountVerified) ring.insertAdjacentHTML("beforeend", `<span class="zp76-vtick"><i class="fa-solid fa-check"></i></span>`); }
        scr.querySelectorAll(".zp76-tier-pill").forEach(x => x.remove());
        const un = document.getElementById("fpUsernameSub");
        if (un && Number(meta.userTier||0) >= 1 && meta.uid !== "zoreno_ai") un.insertAdjacentHTML("afterend", `<div class="zp76-tier-pill"><i class="fa-solid fa-crown" style="color:#fde047;"></i>${meta.userTier>=2?"Zoreno Pro":"Zoreno Plus"}</div>`);

        let wrap = document.getElementById("fpV76Ext");
        if (!wrap) { wrap = document.createElement("div"); wrap.id = "fpV76Ext"; scr.appendChild(wrap); }
        const ex = meta.extendedProfile; if (!ex || meta.uid === "zoreno_ai") { wrap.innerHTML = ""; return; }
        const self = Boolean(meta._self || (auth?.currentUser?.uid && meta.uid === auth.currentUser.uid));
        const fr = Boolean(myFriendsMap?.[meta.uid]), v = ex.vis || {}, cards = [];
        const kv = pairs => `<div class="zp76-kv">${pairs.filter(p=>p[1]).map(p=>`<div><span>${p[0]}</span><strong>${esc(p[1])}</strong></div>`).join("")}</div>`;

        if (canSee(v.about,fr,self) && (ex.interests?.length||ex.hobbies?.length)) cards.push(`<div class="zp76-card" style="margin:0;"><div class="zp76-head" style="margin-bottom:6px;"><h4><span class="zp76-ico"><i class="fa-solid fa-sparkles"></i></span>Interests & Hobbies</h4></div><div class="zp76-chips">${[...(ex.interests||[]),...(ex.hobbies||[])].map(c=>`<span class="zp76-chip on">${esc(c)}</span>`).join("")}</div></div>`);
        if (canSee(v.education,fr,self) && (ex.eduLevel||ex.qualification||ex.institution||ex.curEdu)) cards.push(`<div class="zp76-card" style="margin:0;"><div class="zp76-head" style="margin-bottom:6px;"><h4><span class="zp76-ico"><i class="fa-solid fa-graduation-cap"></i></span>Education</h4></div>${kv([["Level",ex.eduLevel],["Board/Degree",ex.qualification],["Current",ex.curEdu],["Institute",ex.institution],["Passing Yr",ex.passYear],["Mode",ex.eduMode]])}</div>`);
        if (canSee(v.work,fr,self) && (ex.emp||ex.profession||ex.org||ex.skills?.length)) cards.push(`<div class="zp76-card" style="margin:0;"><div class="zp76-head" style="margin-bottom:6px;"><h4><span class="zp76-ico"><i class="fa-solid fa-briefcase"></i></span>Work & Skills</h4></div>${kv([["Status",ex.emp],["Role",ex.profession],["Org",ex.org],["Exp",ex.exp]])}${ex.skills?.length?`<div class="zp76-chips" style="margin-top:7px;">${ex.skills.map(s=>`<span class="zp76-chip">${esc(s)}</span>`).join("")}</div>`:""}</div>`);
        if (canSee(v.personal,fr,self) && (ex.dob||ex.gender||ex.blood||ex.nationality||ex.marital||ex.religion||ex.category)) cards.push(`<div class="zp76-card" style="margin:0;"><div class="zp76-head" style="margin-bottom:6px;"><h4><span class="zp76-ico"><i class="fa-regular fa-id-card"></i></span>Personal Details</h4></div>${kv([["DOB",ex.dob],["Gender",ex.gender],["Status",ex.marital],["Blood",ex.blood],["Nationality",ex.nationality],["Religion",ex.religion],["Category",ex.category]])}</div>`);
        if (canSee(v.location,fr,self) && (ex.city||ex.state||ex.country||ex.languages?.length)) cards.push(`<div class="zp76-card" style="margin:0;"><div class="zp76-head" style="margin-bottom:6px;"><h4><span class="zp76-ico"><i class="fa-solid fa-location-dot"></i></span>Location & Languages</h4></div>${kv([["Location",[ex.city,ex.state,ex.country].filter(Boolean).join(", ")],["Languages",(ex.languages||[]).join(", ")]])}</div>`);
        if (canSee(v.social,fr,self) && ex.social) {
            const ls = [["instagram","Instagram","fa-instagram"],["facebook","Facebook","fa-facebook"],["linkedin","LinkedIn","fa-linkedin"],["github","GitHub","fa-github"],["youtube","YouTube","fa-youtube"]].filter(x=>ex.social[x[0]]?.trim());
            if (ls.length) cards.push(`<div class="zp76-card" style="margin:0;"><div class="zp76-head" style="margin-bottom:6px;"><h4><span class="zp76-ico"><i class="fa-solid fa-share-nodes"></i></span>Social Links</h4></div><div class="zp76-chips">${ls.map(x=>`<a class="zp76-soc" href="${esc(urlFix(ex.social[x[0]]))}" target="_blank" rel="noopener"><i class="fa-brands ${x[2]}"></i>${x[1]}</a>`).join("")}</div></div>`);
        }
        wrap.innerHTML = cards.join("");
    }

    function paintChatHeaderTick(ver) {
        const av = document.querySelector("#activeChatScreen .chat-win-avatar-wrap");
        if (av) { av.style.position = "relative"; av.querySelector(".zp76-vtick")?.remove(); if (ver) av.insertAdjacentHTML("beforeend", `<span class="zp76-vtick" style="width:15px!important;height:15px!important;font-size:7.5px!important;border-width:1.5px!important;"><i class="fa-solid fa-check"></i></span>`); }
    }

    const _origSyncFp = window.syncFriendProfileViewDOM;
    window.syncFriendProfileViewDOM = function (...a) {
        _origSyncFp?.apply(this, a);
        if (!currentChatUserMeta) return;
        paintFriendExtras(currentChatUserMeta);
        if (!currentChatUserMeta.extendedProfile && db && currentChatUserId && currentChatUserId !== "zoreno_ai" && !currentChatUserMeta._self) {
            db.collection("users").doc(currentChatUserId).get().then(d => {
                if (!d.exists || currentChatUserId !== d.id) return;
                const x = d.data() || {};
                currentChatUserMeta.extendedProfile = x.extendedProfile || null;
                currentChatUserMeta.isAccountVerified = x.isAccountVerified === true;
                currentChatUserMeta.userTier = x.userTier || 0;
                paintFriendExtras(currentChatUserMeta); paintChatHeaderTick(x.isAccountVerified === true);
            }).catch(()=>{});
        }
    };

    const _origChat = window.openChatWithUser;
    window.openChatWithUser = function (uid, ...r) {
        _origChat?.apply(this, [uid, ...r]);
        if (db && uid) db.collection("users").doc(uid).get().then(d => {
            if (!d.exists || currentChatUserId !== uid) return;
            const x = d.data() || {};
            if (currentChatUserMeta) { currentChatUserMeta.isAccountVerified = x.isAccountVerified === true; currentChatUserMeta.extendedProfile = x.extendedProfile || null; currentChatUserMeta.userTier = x.userTier || 0; }
            paintChatHeaderTick(x.isAccountVerified === true);
        }).catch(()=>{});
    };

    // 4. REAL AI FACE VERIFICATION (LIVENESS + ANTI-BOT + 12+ AGE CHECK, ZERO SERVER STORAGE)
    window.runV71FaceLivenessScan = async function () {
        const btn = document.getElementById("zv71StartScanBtn"), st = document.getElementById("zv71FaceStatus"), vid = document.getElementById("zv71FaceVideo");
        if (!vid || vid.readyState < 2) { if (st) st.textContent = "Camera loading..."; return; }
        const grab = (w,h) => { const c = document.createElement("canvas"); c.width=w; c.height=h; const x=c.getContext("2d"); x.drawImage(vid,0,0,w,h); return { c, d: x.getImageData(0,0,w,h).data }; };
        if (btn) { btn.disabled = true; btn.innerHTML = `<i class="fa-solid fa-circle-notch fa-spin"></i> Scanning...`; }
        if (st) { st.style.color = "#6d28d9"; st.textContent = "Blink or turn your head slightly..."; }
        try {
            const f1 = grab(64,64); await new Promise(r => setTimeout(r, 1100)); const f2 = grab(64,64);
            let diff = 0; for (let i=0; i<f1.d.length; i+=4) diff += Math.abs(f1.d[i]-f2.d[i]) + Math.abs(f1.d[i+1]-f2.d[i+1]);
            if (diff / (64*64*2) < 1.2) throw new Error("No live movement detected. Static photos/screens are rejected.");
            if (st) st.textContent = "AI checking real human & age (12+)...";
            const b64 = grab(320,320).c.toDataURL("image/jpeg", .72).split(",")[1];
            const raw = await callGeminiWithFallback({
                contents: [{ role: "user", parts: [{ text: `Return ONLY valid JSON: {"isRealHuman":boolean,"isClearFace":boolean,"age12Plus":boolean,"reason":"short"}. Reject bots, cartoons, objects, screen spoofs, or young children visibly under 12.` }, { inline_data: { mime_type: "image/jpeg", data: b64 } }] }],
                generationConfig: { temperature: .1, maxOutputTokens: 140 }
            });
            const v = JSON.parse((raw||"").match(/\{[\s\S]*\}/)?.[0] || "{}");
            if (!v.isRealHuman || !v.isClearFace) throw new Error(v.reason || "Real live face not detected.");
            if (v.age12Plus === false) throw new Error("Rejected: User must visibly appear 12+ years old.");
            if (db && auth?.currentUser) await db.collection("users").doc(auth.currentUser.uid).set({ faceVerifyRequestedAtMs: Date.now(), aiFaceCheckPassed: true, isAccountVerified: false }, { merge: true });
            closeV71SubModal?.(); showCompactGlassToast?.("", "AI Face Check Passed ✓ Verified in 48h!"); window.openV71SecurityModal?.();
        } catch (err) {
            if (st) { st.style.color = "#dc2626"; st.textContent = err?.message || "Verification failed. Retry."; }
            if (btn) { btn.disabled = false; btn.textContent = "Retry Face Scan"; }
        }
    };

    const _origBack = window.handleZorenoHardwareBack;
    window.handleZorenoHardwareBack = () => { const s = document.getElementById("zorenoV76Profile"); if (s && s.style.display !== "none") { zp76Close(); return true; } return _origBack?.() || false; };
})();

