    // ---------------------------------------------------------
    // 3. GLOBAL PIN / ZIP CODE FETCHER (INDIA + US + 60+ COUNTRIES)
    // ---------------------------------------------------------
    const COUNTRY_ISO2 = {
        "India": "in", "United States": "us", "United Kingdom": "gb", "Canada": "ca", "Australia": "au",
        "Germany": "de", "France": "fr", "Italy": "it", "Spain": "es", "Netherlands": "nl",
        "Switzerland": "ch", "Sweden": "se", "Norway": "no", "Denmark": "dk", "Finland": "fi",
        "Poland": "pl", "Turkey": "tr", "Brazil": "br", "Mexico": "mx", "Argentina": "ar",
        "Japan": "jp", "South Korea": "kr", "Malaysia": "my", "Thailand": "th", "Philippines": "ph",
        "Pakistan": "pk", "Bangladesh": "bd", "Sri Lanka": "lk", "South Africa": "za", "New Zealand": "nz",
        "Russia": "ru", "Portugal": "pt", "Belgium": "be", "Austria": "at", "Czech Republic": "cz",
        "Hungary": "hu", "Singapore": "sg", "Ireland": "ie", "Indonesia": "id", "United Arab Emirates": "ae"
    };

    const US_STATE_ABBR = {
        "alabama":"al","alaska":"ak","arizona":"az","arkansas":"ar","california":"ca","colorado":"co",
        "connecticut":"ct","delaware":"de","florida":"fl","georgia":"ga","hawaii":"hi","idaho":"id",
        "illinois":"il","indiana":"in","iowa":"ia","kansas":"ks","kentucky":"ky","louisiana":"la",
        "maine":"me","maryland":"md","massachusetts":"ma","michigan":"mi","minnesota":"mn","mississippi":"ms",
        "missouri":"mo","montana":"mt","nebraska":"ne","nevada":"nv","new hampshire":"nh","new jersey":"nj",
        "new mexico":"nm","new york":"ny","north carolina":"nc","north dakota":"nd","ohio":"oh","oklahoma":"ok",
        "oregon":"or","pennsylvania":"pa","rhode island":"ri","south carolina":"sc","south dakota":"sd",
        "tennessee":"tn","texas":"tx","utah":"ut","vermont":"vt","virginia":"va","washington":"wa",
        "west virginia":"wv","wisconsin":"wi","wyoming":"wy","district of columbia":"dc"
    };

    const globalPinCache = {};

    async function fetchGlobalPins(country, state, city) {
        const key = `${country}|${state}|${city}`.toLowerCase();
        if (globalPinCache[key]) return globalPinCache[key];

        const results = [];
        const seen = new Set();
        const addPin = (code, desc) => {
            const c = String(code || "").trim();
            if (!c || seen.has(c)) return;
            seen.add(c);
            results.push({ value: c, title: c, sub: desc || city });
        };

        // A. India Postal API
        if (country === "India" && city) {
            try {
                const r = await fetch(`https://api.postalpincode.in/postoffice/${encodeURIComponent(city)}`);
                const j = await r.json();
                (j?.[0]?.PostOffice || []).forEach(o => addPin(o.Pincode, `${o.Name}, ${o.District || state}`));
            } catch {}
        }

        // B. Zippopotam Global Postal API (US, CA, GB, DE, FR, AU, etc.)
        const iso = COUNTRY_ISO2[country];
        if (!results.length && iso && city) {
            const stCode = iso === "us" ? (US_STATE_ABBR[(state || "").toLowerCase()] || state) : state;
            if (stCode) {
                try {
                    const r = await fetch(`https://api.zippopotam.us/${iso}/${encodeURIComponent(stCode)}/${encodeURIComponent(city)}`);
                    if (r.ok) {
                        const j = await r.json();
                        (j?.places || []).forEach(p => addPin(p["post code"], `${p["place name"] || city}, ${state}`));
                    }
                } catch {}
            }
        }

        // C. Universal OpenStreetMap Nominatim Fallback (Works for almost any city worldwide!)
        if (!results.length && (city || state)) {
            try {
                const q = [city, state, country].filter(Boolean).join(", ");
                const r = await fetch(`https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&limit=15&q=${encodeURIComponent(q)}`);
                if (r.ok) {
                    const arr = await r.json();
                    (Array.isArray(arr) ? arr : []).forEach(item => {
                        const pc = item?.address?.postcode;
                        if (pc) {
                            String(pc).split(/[;,]/).forEach(part => addPin(part.trim(), item.display_name?.split(",").slice(0, 2).join(", ")));
                        }
                    });
                }
            } catch {}
        }

        if (results.length) globalPinCache[key] = results;
        return results;
    }

