// ZORENO V94: LIQUID GLASS AUTH ENHANCER (38213 & 38243)
// =========================================================
(function initZorenoV94LiquidGlassAuth() {
    function enhanceAuthScreens() {
        const authScr = document.getElementById("authScreen");
        if (!authScr || authScr.dataset.v94Enhanced === "true") return;
        authScr.dataset.v94Enhanced = "true";

        // 1. Add Crisp </> Icon in Top Toko Platforms Pill
        const brandBox = authScr.querySelector(".toko-auth-top-brand");
        if (brandBox && !brandBox.querySelector(".toko-v94-code-ico")) {
            brandBox.querySelector("svg")?.remove();
            brandBox.insertAdjacentHTML("afterbegin", `<i class="fa-solid fa-code toko-v94-code-ico"></i>`);
        }

        // 2. Wrap Login & SignUp Forms Inside Frosted Glass Cards
        ["loginViewSection", "signUpViewSection"].forEach(secId => {
            const sec = document.getElementById(secId);
            if (!sec || sec.querySelector(".zv94-auth-glass-card")) return;
            const form = sec.querySelector("form");
            if (!form) return;
            const card = document.createElement("div");
            card.className = "zv94-auth-glass-card";
            form.parentNode.insertBefore(card, form);
            card.appendChild(form);
            // Move OR divider & Google button inside the same frosted glass card
            const orDiv = sec.querySelector(".auth-divider, .or-divider");
            const gBtn = sec.querySelector(".google-auth-btn, .auth-google-btn");
            if (orDiv) card.appendChild(orDiv);
            if (gBtn) card.appendChild(gBtn);
        });

        // 3. Add 3-Column Trust Strip Below Login Switch Pill (38213.png)
        const loginSec = document.getElementById("loginViewSection");
        if (loginSec && !loginSec.querySelector(".zv94-trust-strip")) {
            const strip = document.createElement("div");
            strip.className = "zv94-trust-strip";
            strip.innerHTML = `
                <div class="zv94-trust-item"><i class="fa-solid fa-shield-halved"></i><span>Secure &amp; Private</span></div>
                <div class="zv94-trust-item"><i class="fa-solid fa-bolt"></i><span>Fast &amp; Easy</span></div>
                <div class="zv94-trust-item"><i class="fa-solid fa-users"></i><span>Join Zoreno Community</span></div>
            `;
            loginSec.appendChild(strip);
        }
    }

    setTimeout(enhanceAuthScreens, 120);
    window.addEventListener("DOMContentLoaded", enhanceAuthScreens);
})();

