    const COMPACT_ZORENO_SYSTEM_PROMPT = `You are Zoreno AI, a warm, smart study partner & daily assistant created by Achyut Tiwari (Toko Platforms — mention creator only if asked).
Rules:
1. Answer directly in sentence 1 (no repeated "Hello/Hi"). Keep answers crisp & structured using **bold** terms and numbered steps; give long details only if asked.
2. Mirror user's exact language & script (English, Roman Hinglish, or Devanagari Hindi). If user asks for Devanagari Hindi, reply 100% in Devanagari script.
3. Math/Science: solve step-by-step internally first for 100% accuracy. Use clean Unicode math (÷, ×, π, θ, √, ², ³), zero LaTeX ($...$). Put key formulas on a line starting with "Formula:".
4. Comparisons: use compact Markdown tables. Letters/applications: write cleanly.
5. Refuse bomb-making, self-harm, hacking, illegal crimes, or writing full programming code. Answer general knowledge, creative writing, study, and health info helpfully.
App Plans: Free (10 AI chats/day, Friend/Group chat, Focus Timer/Music), Plus ₹249/mo (50 AI chats/day, ad-free, 3D stickers, custom themes, expanded tools), Pro ₹349/mo (90 AI chats/day, Vision AI, AI Smart Reply, Agreement Cards, Disappearing Timer, Anti-Screenshot).`;

    function needsLiveGoogleSearch(q) {
        const s = String(q || "");
        if (/https?:\/\//i.test(s)) return true;
        return /\b(price|stock|share|nifty|sensex|bitcoin|btc|crypto|gold rate|silver rate|weather|mausam|news|khabar|live score|ipl|match|cricket score|today|aaj|latest|current|abhi|2026|2027|exchange rate|dollar|usd to inr|who is the (?:pm|president|ceo|cm)|winner|election|release date)\b/i.test(s);
    }

    async function scanUrlCompact(url) {
        const ctrl = new AbortController();
        const tm = setTimeout(() => ctrl.abort(), 4200);
        try {
            if (/(?:youtube\.com\/(?:watch\?v=|shorts\/|live\/)|youtu\.be\/)/i.test(url)) {
                const r = await fetch(`https://noembed.com/embed?url=${encodeURIComponent(url)}`, { signal: ctrl.signal });
                if (r.ok) {
                    const m = await r.json();
                    if (m?.title) return `[YouTube] Title: ${m.title} | Channel: ${m.author_name || "Unknown"} | URL: ${url}`;
                }
                return `[YouTube URL]: ${url}`;
            }
            const r = await fetch(`https://r.jina.ai/${url}`, { signal: ctrl.signal });
            if (r.ok) {
                const txt = (await r.text()).replace(/\s+/g, " ").trim().slice(0, 1600);
                if (txt.length > 60) return `[Webpage ${url}]: ${txt}`;
            }
        } catch (e) {} finally { clearTimeout(tm); }
        return `[URL]: ${url}`;
    }

    // Optimize AI Image Compression to 480px (Lower Vision Token Cost, Crisp for Notes/Questions)
    window.handleMultipleImages = function (event) {
        const allSelected = Array.from(event.target.files || []);
        event.target.value = "";
        if (!allSelected.length) return;
        const activeTier = typeof window.getEffectiveTier === "function" ? window.getEffectiveTier() : 0;
        const maxPhotos = activeTier >= 2 ? 2 : 1;
        const remainingSlots = maxPhotos - pendingAiAttachments.length;
        if (remainingSlots <= 0) {
            if (activeTier < 2) {
                showCompactGlassToast?.("👑", "Upgrade to Pro for 2 photos at once");
            } else {
                showCompactGlassToast?.("📷", "Max 2 photos allowed");
            }
            return;
        }
        allSelected.slice(0, remainingSlots).forEach(file => {
            const tempId = "att_" + Date.now() + "_" + Math.random().toString(36).slice(2, 6);
            pendingAiAttachments.push({ id: tempId, loading: true, dataUrl: "" });
            renderAiAttachmentPreviewStrip?.();
            const reader = new FileReader();
            reader.onload = function (e) {
                const img = new Image();
                img.onload = function () {
                    const canvas = document.createElement("canvas");
                    const MAX_DIM = 480;
                    let w = img.width, h = img.height;
                    if (w > h && w > MAX_DIM) { h = Math.round((h * MAX_DIM) / w); w = MAX_DIM; }
                    else if (h >= w && h > MAX_DIM) { w = Math.round((w * MAX_DIM) / h); h = MAX_DIM; }
                    canvas.width = w; canvas.height = h;
                    canvas.getContext("2d").drawImage(img, 0, 0, w, h);
                    const compressed = canvas.toDataURL("image/jpeg", 0.55);
                    const item = pendingAiAttachments.find(x => x.id === tempId);
                    if (item) { item.loading = false; item.dataUrl = compressed; renderAiAttachmentPreviewStrip?.(); }
                };
                img.src = e.target.result;
            };
            reader.readAsDataURL(file);
        });
    };

    // Single Clean Cost-Optimized sendMessage (Replaces Stacked V44/V45/V47/V71/V89/V91 Chain!)
    window.sendMessage = async function () {
        if (isAiGenerating && currentAiAbortController) {
            currentAiAbortController.abort();
            return;
        }

        const input = document.getElementById("userInput");
        const chatMessages = document.getElementById("chatMessages");
        if (!input || !chatMessages) return;

        if (pendingAiAttachments.some(a => a.loading)) {
            showCompactGlassToast?.("⏳", "Photo is still loading...");
            return;
        }

        let text = input.value.trim();
        const attachedImages = pendingAiAttachments.map(a => a.dataUrl).filter(Boolean).slice(0, 2);
        if (!text && attachedImages.length === 0) return;

        // Input Cap: Max 2,500 chars per message (~600 tokens) to protect API costs
        if (text.length > 2500) {
            text = text.slice(0, 2500);
            showCompactGlassToast?.("ℹ️", "Message trimmed to 2500 characters");
        }

        // Single Unified Daily Quota Check (Free=10+bonus, Plus=50+bonus, Pro=90+bonus)
        const met = window.getZorenoAiEnergyMetrics();
        if (met.remainingChats <= 0) {
            window.openV89AiLimitModal();
            return;
        }

        let promptToSend = text;
        if (window.activeAiReplyObj?.quote) {
            promptToSend = `[Replying to: "${window.activeAiReplyObj.quote.slice(0, 100)}"]\n${text}`;
            window.activeAiReplyObj = null;
            document.getElementById("aiReplyPreviewStrip")?.classList.remove("active");
        }

        document.getElementById("inputAreaContainer")?.classList.remove("gemini-expanded-box");
        const nowTime = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
        window._lastStoppedUserPromptText = text;
        input.value = "";
        input.style.height = "auto";
        pendingAiAttachments = [];
        renderAiAttachmentPreviewStrip?.();

        const hasImgs = attachedImages.length > 0;
        const isMediaOnly = hasImgs && !text;
        const imgsHtml = attachedImages.map(src =>
            `<img src="${src}" class="sent-wide-photo" onclick="event.stopPropagation(); openFullImageModal('${src}')" alt="Uploaded">`
        ).join("");

        chatMessages.insertAdjacentHTML("beforeend", `
            <div class="msg-row-with-avatar right-user">
                <div class="clean-right-bubble ${isMediaOnly ? 'media-only-bubble' : ''}">
                    ${imgsHtml ? `<div class="sent-media-grid">${imgsHtml}</div>` : ""}
                    ${text ? `<div style="${hasImgs ? 'padding:6px 8px 2px;' : ''}">${escapeHtml(text)}</div>` : ""}
                    <div class="bubble-meta-time"><span>${nowTime}</span><i class="fa-solid fa-check-double"></i></div>
                </div>
            </div>
        `);

        const guardrailCheck = checkQueryGuardrails(text);
        if (guardrailCheck.blocked) {
            await saveChatToFirebase(text, guardrailCheck.reply, nowTime, attachedImages);
            renderAiChatStream();
            return;
        }

        const urls = (promptToSend.match(/https?:\/\/[^\s<>"{}|\\^`[\]]+/gi) || []).slice(0, 1);
        const useLiveSearch = needsLiveGoogleSearch(promptToSend);
        const thinkLabel = urls.length ? "Reading link" : useLiveSearch ? "Searching live web" : "Zoreno is thinking";

        const thinkingId = "zorenoThinking_" + Date.now();
        chatMessages.insertAdjacentHTML("beforeend", `
            <div class="msg-row-with-avatar" id="${thinkingId}">
                <img src="logo.png" class="ai-logo-avatar" onerror="this.src=ZORENO_SVG_LOGO" alt="Zoreno">
                <div class="clean-left-bubble" style="padding:10px 16px!important; border-radius:22px!important;">
                    <div style="display:flex; align-items:center; gap:10px; color:#7c3aed; font-weight:600; font-size:13.5px;">
                        <span>${thinkLabel}</span>
                        <div class="thinking-dots"><span></span><span></span><span></span></div>
                    </div>
                </div>
            </div>
        `);
        scrollToBottom();

        isAiGenerating = true;
        currentAiAbortController = new AbortController();
        setSendBtnStopMode(true);

        try {
            // Compact Context Window: Max last 6 turns, each capped at 420 chars (keeps total input well under ~4500 chars!)
            const recentHistory = [];
            aiChatMessagesList.slice(-6).forEach(pair => {
                if (pair.user) recentHistory.push({ role: "user", parts: [{ text: String(pair.user).slice(0, 420) }] });
                if (pair.bot) recentHistory.push({ role: "model", parts: [{ text: String(pair.bot).slice(0, 420) }] });
            });

            let extraLinkCtx = "";
            if (urls.length > 0) {
                extraLinkCtx = "\n" + await scanUrlCompact(urls[0]);
            }

            const now = new Date();
            const sysText = COMPACT_ZORENO_SYSTEM_PROMPT +
                `\nDate: ${now.toLocaleDateString("en-IN", { day: "numeric", month: "short", year: "numeric" })}` +
                extraLinkCtx;

            const currentParts = [];
            attachedImages.forEach(dataUrl => {
                const b64 = dataUrl.split(",")[1];
                if (b64) currentParts.push({ inlineData: { mimeType: "image/jpeg", data: b64 } });
            });
            currentParts.push({ text: promptToSend || "Explain this image concisely." });

            const basePayload = {
                systemInstruction: { parts: [{ text: sysText }] },
                contents: [...recentHistory, { role: "user", parts: currentParts }],
                generationConfig: { maxOutputTokens: 3000, temperature: 0.5 }
            };

            // CONDITIONAL GOOGLE SEARCH: ONLY attach search tool if query actually needs live web/URL!
            const primaryModel = typeof ZORENO_AI_MODEL !== "undefined" ? ZORENO_AI_MODEL : "gemini-3.5-flash-lite";
            const attempts = useLiveSearch
                ? [
                    { model: primaryModel, body: { ...basePayload, tools: [{ google_search: {} }] } },
                    { model: "gemini-3.5-flash-lite", body: { ...basePayload, tools: [{ google_search: {} }] } },
                    { model: "gemini-3.5-flash-lite", body: basePayload }
                ]
                : [
                    { model: primaryModel, body: basePayload },
                    { model: "gemini-3.5-flash-lite", body: basePayload }
                ];

            let replyText = "";
            let lastErr = null;
            for (const step of attempts) {
                try {
                    const res = await fetch(
                        `https://generativelanguage.googleapis.com/v1beta/models/${step.model}:generateContent?key=${GEMINI_API_KEY}`,
                        { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(step.body), signal: currentAiAbortController.signal }
                    );
                    const data = await res.json();
                    if (data.error) { lastErr = new Error(data.error.message || "API Error"); continue; }
                    const full = (data?.candidates?.[0]?.content?.parts || []).map(p => p.text || "").join("").trim();
                    if (full) { replyText = full; break; }
                } catch (e) {
                    if (e.name === "AbortError") throw e;
                    lastErr = e;
                }
            }

            if (!replyText) throw lastErr || new Error("Unable to get response. Please retry.");

            // Deduct 1 confirmed chat from unified Firebase + local quota
            const qNow = readUnifiedQuota();
            persistUnifiedQuota(qNow.count + 1, qNow.bonus);

            await saveChatToFirebase(text, replyText, nowTime, attachedImages);
            renderAiChatStream();
        } catch (err) {
            const thinkingRow = document.getElementById(thinkingId);
            if (err.name === "AbortError") {
                await saveChatToFirebase(text, "", nowTime, attachedImages);
                renderAiChatStream();
                showCompactGlassToast?.("", "Stopped");
            } else if (thinkingRow) {
                thinkingRow.innerHTML = `<img src="logo.png" class="ai-logo-avatar" onerror="this.src=ZORENO_SVG_LOGO" alt="Zoreno"><div class="clean-left-bubble"><span style="color:#ef4444; font-weight:600;">⚠️ ${escapeHtml(err.message)}</span></div>`;
            }
        } finally {
            isAiGenerating = false;
            currentAiAbortController = null;
            setSendBtnStopMode(false);
            scrollToBottom();
        }
    };

